local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>ห้องโถงแห่งความยุติธรรม สวนลุมโปลิส</color>",
  ui_story_5043_50430101_2_dialog_content = "ท่านผู้ทรงเกียรติ ไม่เป็นเช่นนั้น!",
  ui_story_5043_50430101_3_dialog_content = "ฉันขอสาบานต่อพระเจ้าแห่งแสงสว่าง ฉันไม่ได้โกหกเธอในเรื่องของหัวใจ",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5043_50430101_5_dialog_content = "สั่งศาล! จำเลยจะงดเว้นไม่ขัดขวางโจทก์",
