  ui_story_5043_50430101_7_dialog_content = "นางสาวคุณระบุเพียงว่าโจทก์ไม่สามารถปฏิบัติหน้าที่ในฐานะคู่หมั้นของคุณในระหว่างที่คุณหมั้นหมายได้ ถูกต้องหรือไม่?",
  ui_story_5043_50430101_8_dialog_content = "มันคือ!",
  ui_story_5043_50430101_9_dialog_content = "คุณอาจแถลงครั้งสุดท้ายก่อนที่ศาลจะเริ่มพิจารณา",
  ui_story_5043_50430101_10_dialog_content = "Mooncrown Day ของเดือนที่แล้วเป็นวันครบรอบเจ็ดเดือนที่เราหมั้นหมายกัน",
  ui_story_5043_50430101_11_dialog_content = "แต่ช่างไร้ค่าคนนั้นไม่สนใจด้วยซ้ำ!",
  ui_story_5043_50430101_12_dialog_content = "โอ้ได้โปรด. คุณไม่สามารถคาดหวังให้ฉันฉลองการหมั้นของเราทุกเดือน!",
  ui_story_5043_50430101_13_dialog_content = "ฉันอาจจะไม่ได้คัดค้าน แต่คุณจัดการเพื่อซื้อของขวัญที่แตกต่างกันสำหรับคนอื่น ๆ หลายคน!",
  ui_story_5043_50430101_14_dialog_content = "รอสักครู่. ฉันอธิบายไปแล้ว พวกนั้นเป็นความสัมพันธ์ทางธุรกิจของครอบครัวฉัน—",
  ui_story_5043_50430101_15_dialog_content = "H-เดี๋ยวก่อน! อย่าเพิ่งเถียงกันตอนนี้...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>ทีน่า ตอนนี้คุณเป็นผู้พิพากษาแล้ว ทำตัวเหมือน!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>เออ ถูกต้อง! ฉัน. โอเค ดูนี่ อะแฮ่ม...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>สั่ง สั่ง!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5043_50430101_20_dialog_content = "(ที่อยากรู้คือทำไมมานั่งฟังแฟนเพ้อเจ้อ...)",
  ui_story_5043_50430101_21_dialog_content = "เริ่มใจร้อน PlayerName? คุณเริ่มดูเบื่อ",
  ui_story_5043_50430101_22_dialog_content = "อะไรฉัน? ไม่เลย... โอเค เธอพูดถูกเหมือนเคย คาร์ลีน",
  ui_story_5043_50430101_23_dialog_content = "พูดตามตรงฉันรู้สึกเหมือนกันทุกประการ",
  ui_story_5043_50430101_24_dialog_content = "แต่ไม่เหมือนคุณ ฉันไม่สามารถแสดงมันได้ หลังจากนั้น-",
  ui_story_5043_50430101_25_dialog_content = "ฉันรู้. ในระดับหนึ่ง มันจะส่งผลไม่ดีต่อเจ้าเมืองที่นั่น",
  ui_story_5043_50430101_26_dialog_content = "...",
  ui_story_5043_50430101_27_dialog_content = "จนถึงตอนนี้เขายังไม่ได้พูดอะไรเลย",
  ui_story_5043_50430101_28_dialog_content = "ขอโทษ. ตอนแรกฉันตั้งใจจะให้คุณมาที่สวนลุมโปลิสเพื่อรายงานเกี่ยวกับการผจญภัยของคุณในหลงโจว",
  ui_story_5043_50430101_29_dialog_content = "แต่ดูเหมือนว่าเจ้าเมืองจะไม่ได้เผื่อเวลาไว้เลย",
  ui_story_5043_50430101_30_dialog_content = "ไม่มีปัญหา. ไม่ใช่ว่าฉันมีอะไรด่วนต้องทำ",
  ui_story_5043_50430101_31_dialog_content = "<size=30>และด้วยความสัตย์จริง ฉันไม่อยากกลับเข้าไปในห้องประชุมเคร่งขรึมห้องใดห้องหนึ่งเลย...</size>",
  ui_story_5043_50430101_32_dialog_content = "ขอโทษอะไร?",
  ui_story_5043_50430101_33_dialog_content = "อ๊ะ! เปล่านะ!",
  ui_story_5043_50430101_34_dialog_content = "(ตอนนี้ฉันคิดเกี่ยวกับมันฉันไม่ได้มาที่นี่ตั้งแต่นั้นมา <color=#FFB400>เหตุการณ์</color>...)",
  ui_story_5043_50430101_35_dialog_content = "(Irridon นั่งตรงที่ที่เธออยู่ตอนนี้ อ่านคำตัดสินของ Hall of Justice เกี่ยวกับ Carleen)",
  ui_story_5043_50430101_36_dialog_content = "(และคาร์ลีน... ก็ เธอเปลี่ยนไปมากตั้งแต่นั้นมา)",
  ui_story_5043_50430101_37_dialog_content = "PlayerNameคุณกำลังฝันกลางวันอยู่หรือเปล่า?",
  ui_story_5043_50430101_38_dialog_content = "อืม... ฉันแค่คิดว่า...",
  ui_story_5043_50430101_39_dialog_content = "ฉันแค่คิดถึงผลที่ Mooncrown Day มีต่อ Lumopolis!",
  ui_story_5043_50430101_40_dialog_content = "ใช่ เรื่องแบบนี้เป็นเรื่องปกติในช่วงเวลานี้ของปี",
  ui_story_5043_50430101_41_dialog_content = "ในขณะที่ชายหนุ่มและหญิงสาวเพลิดเพลินกับบรรยากาศของ Mooncrown บางคนก็เริ่มต้นความรักครั้งใหม่ และบางครั้งก็เกิดรอยร้าวในความสัมพันธ์ที่มีอยู่",
  ui_story_5043_50430101_42_dialog_content = "จากนั้นมีขุนนางที่เสื่อมโทรมซึ่งมีแนวโน้มที่จะพยายามคิดหาวิธีที่จะทำให้ความบันเทิงอยู่ได้นานที่สุด",
  ui_story_5043_50430101_43_dialog_content = "เป็นผลให้ Hall of Justice จบลงด้วยข้อพิพาทด้านความสัมพันธ์ที่ต้องจัดการ",
  ui_story_5043_50430101_44_dialog_content = "เจ้าเมืองนั่งฟังบ่อยกว่าปกติ เพื่อป้องกันไม่ให้สถานการณ์ที่คาดไม่ถึงเกิดขึ้นหรือควบคุมไม่ได้",
  ui_story_5043_50430101_45_dialog_content = "อย่างไรก็ตาม ฉันชอบนั่งเป็นผู้ชมที่นี่มากกว่านั่งเก้าอี้จำเลย",
  ui_story_5043_50430101_46_dialog_content = "คาร์ลีน...",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>ตุ๊ด ตุ๊ด ตุ๊ด ตุ๊ด!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>คำสั่ง!</size>",
  ui_story_5043_50430101_49_dialog_content = "สรุปแล้วมันใจร้ายและไม่น่าให้อภัย!",
  ui_story_5043_50430101_50_dialog_content = "ฉันจึงขอให้ศาลยุติการหมั้นของเรา!",
  ui_story_5043_50430101_51_dialog_content = "หึหึ โจทก์ที่รัก ฉันเข้าใจดีว่าคุณมาจากไหน",
  ui_story_5043_50430101_52_dialog_content = "ตามที่ฉันเข้าใจ นี่เป็นข้อตกลงระหว่างครอบครัวของคุณที่มีมายาวนาน และคุณกับจำเลยเป็นคู่รักในวัยเด็ก",
  ui_story_5043_50430101_53_dialog_content = "ซึ่งสมเหตุสมผล เป็นการยากที่จะจินตนาการว่าผู้ชายเช่นจำเลยจะชนะใจหญิงสาวผู้บริสุทธิ์เช่นคุณโดยปราศจากข้อได้เปรียบเช่นนี้",
  ui_story_5043_50430101_54_dialog_content = "คุณถูก. เราโตมาด้วยกัน ฉันจึงรู้จักเขาดีกว่าใครๆ",
  ui_story_5043_50430101_55_dialog_content = "น่าอิจฉาขนาดไหน. ทำไมฉันเกือบอิจฉาจำเลย",
  ui_story_5043_50430101_56_dialog_content = "(อะไรนะ! ผู้พิพากษาคนนี้น่าขนลุกชะมัด!)",
  ui_story_5043_50430101_57_dialog_content = "J-Judge Schwab...",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5043_50430101_59_dialog_content = "ผู้พิพากษา Schwab โปรดรักษาความเป็นมืออาชีพของคุณ",
  ui_story_5043_50430101_60_dialog_content = "ท้ายที่สุด แม้แต่ข้าพเจ้าและหัวหน้าผู้พิพากษาก็ไม่มีความรู้เกี่ยวกับอุปนิสัยของจำเลยเลย",
  ui_story_5043_50430101_61_dialog_content = "สิ่งที่เราแน่ใจได้ก็คือคุณต้องตัดสินใจหลังจากการพิจารณาอย่างถี่ถ้วนตามจำนวนปีที่คุณรู้จักเขา",
  ui_story_5043_50430101_62_dialog_content = "เอ่อ...?",
  ui_story_5043_50430101_63_dialog_content = "(เฮ้ เธอตกหลุมรักมัน)",
  ui_story_5043_50430101_64_dialog_content = "เอ่อ ฉัน...",
  ui_story_5043_50430101_65_dialog_content = "จำเลย คุณมีอะไรจะพูดก่อนที่หัวหน้าผู้พิพากษา Irridon จะตัดสินหรือไม่",
  ui_story_5043_50430101_66_dialog_content = "<size=45>ที่รักของฉัน! คุณเป็นคนเดียวสำหรับฉันเสมอ!</size>",
  ui_story_5043_50430101_67_dialog_content = "H-คุณพูดแบบนี้ที่นี่ได้ยังไง...",
  ui_story_5043_50430101_68_dialog_content = "ดีมาก. และต่อไป—",
  ui_story_5043_50430101_69_dialog_content = "<size=45>เดี๋ยวก่อน!</size>",
  ui_story_5043_50430101_70_dialog_content = "ฉันเสียใจ. แต่ฉันได้คิดทบทวนแล้ว",
  ui_story_5043_50430101_71_dialog_content = "ฉันต้องการ <color=#FFB400>ถอน</color> กรณีของฉัน.",
  ui_story_5043_50430101_72_dialog_content = "(อะไรอย่างนั้นเหรอ?)",
  ui_story_5043_50430101_73_dialog_content = "ฉันขอโทษจริงๆ ฉันไม่สามารถพิจารณาการกระทำของฉันอย่างเต็มที่ เราควรแก้ไขความเข้าใจผิดของตัวเอง",
  ui_story_5043_50430101_74_dialog_content = "ไม่ มันเป็นความผิดของฉันที่ไม่รักมากกว่านี้ ฉันเองที่ทำผิดต่อคุณ",
  ui_story_5043_50430101_75_dialog_content = "คำขอถูกปฏิเสธ. ต้องเคารพกระบวนการของศาล มีพิธีการที่ต้องปฏิบัติตามทั้งเมื่อนำคดีและเมื่อถอนฟ้อง",
  ui_story_5043_50430101_76_dialog_content = "แต่มีวิธีที่ง่ายกว่าในการจัดการกับสิ่งนี้",
  ui_story_5043_50430101_77_dialog_content = "ฉันพบจำเลย—",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5043_50430101_79_dialog_content = "-ไม่สำนึก!",
  ui_story_5043_50430101_80_dialog_content = "สุดที่รัก!",
  ui_story_5043_50430101_81_dialog_content = "ความหวาน! มาค่ะ ไปจิบชายามบ่ายกัน...",
  ui_story_5043_50430101_82_dialog_content = "ปิดคดี. ศาลมีคำสั่งเลื่อน",
  ui_story_5043_50430101_83_dialog_content = "ท่านชวาบ โปรดรอสักครู่!",
  ui_story_5043_50430101_84_dialog_content = "ขอแสดงความยินดีกับการได้ยินที่ประสบความสำเร็จ ลอร์ดชวาบ! โปรดรับดอกไม้เหล่านี้!",
  ui_story_5043_50430101_85_dialog_content = "A-และฉันก็มีไวท์ช็อกโกแลตให้คุณด้วย ที่นี่...",
  ui_story_5043_50430101_86_dialog_content = "(โอ๊ย...)",
  ui_story_5043_50430101_87_dialog_content = "ทีละคน คนสวยของฉัน เรียงคิวเป็นระเบียบ...",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>สวนลุมโมโปลิส สำนักงานหัวหน้าผู้พิพากษา</color>",
  ui_story_5043_50430101_89_dialog_content = "ประเด็นของการมีกฎคือเพื่อให้เราเห็นได้อย่างรวดเร็วว่าความวุ่นวายยังคงครอบงำอยู่",
  ui_story_5043_50430101_90_dialog_content = "กรณีความสัมพันธ์ที่ไร้สาระเหล่านี้ปรากฏในศาลนานแค่ไหน?",
  ui_story_5043_50430101_91_dialog_content = "เจ้าเมืองครับ เฉพาะในเดือนที่ผ่านมานี้",
  ui_story_5043_50430101_92_dialog_content = "ฉันเห็น. อาจะเป็นหนุ่มอีกครั้ง...",
  ui_story_5043_50430101_93_dialog_content = "แต่ Hall of Justice เป็นสถานที่ศักดิ์สิทธิ์และจริงจัง",
  ui_story_5043_50430101_94_dialog_content = "ท่านต้องการให้เราหยุดฟังคดีเหล่านี้ ท่านลอร์ด?",
  ui_story_5043_50430101_95_dialog_content = "ไม่ มันยังไม่ถึงเวลานั้น",
  ui_story_5043_50430101_96_dialog_content = "นั่นจะส่งผลให้ประชาชนส่งความโกรธไปที่ Hall of Justice",
  ui_story_5043_50430101_97_dialog_content = "แล้วจะให้เราทำอะไร?",
  ui_story_5043_50430101_98_dialog_content = "จัดตั้งศาลรองชั่วคราวเพื่อจัดการกับข้อพิพาทที่โรแมนติกเหล่านี้",
  ui_story_5043_50430101_99_dialog_content = "จะยังคงเป็นส่วนหนึ่งของสวนลุมโปลิส แต่แยกออกจาก Hall of Justice",
  ui_story_5043_50430101_100_dialog_content = "ส่วนการจัดกำลังพล...ส่งน้องไปบางส่วน มันจะเป็นประสบการณ์ที่ดีสำหรับพวกเขา",
  ui_story_5043_50430101_101_dialog_content = "ศาลชั่วคราวจะต้องมีหัวหน้าผู้พิพากษาชั่วคราว",
  ui_story_5043_50430101_102_dialog_content = "ฉันขอถามได้ไหมว่าเธอมีใครในใจไหม?",
  ui_story_5043_50430101_103_dialog_content = "ก่อนหน้านี้ฉันบังเอิญสังเกตเห็นผู้สมัครอายุน้อยคนหนึ่ง...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>ห้องโถงแห่งความยุติธรรม สวนลุมโปลิส</color>",
  ui_story_5043_50430101_105_dialog_content = "ดูเหมือน Irridon และ City Lord กำลังคุยเรื่องสำคัญกันอยู่",
  ui_story_5043_50430101_106_dialog_content = "ฉันเดาว่าการประชุมวันนี้จะไม่เกิดขึ้น ถ้าจำไม่ผิด ช่องต่อไปในตารางของเขาคือ...",
  ui_story_5043_50430101_107_dialog_content = "โอ้ขอโทษ, PlayerName. คุณจะต้องรอเป็นวัน",
  ui_story_5043_50430101_108_dialog_content = "คุณจะชินไปเอง เขามักจะทำลายการนัดหมายและไม่สนใจความคิดเห็นของคนอื่น",
  ui_story_5043_50430101_109_dialog_content = "D-อย่าพูดแบบนั้น และตอนนี้เรามีเวลาว่างแล้วใช่ไหม?",
  ui_story_5043_50430101_110_dialog_content = "แม้แต่การเฝ้าดูผู้พิพากษาเหล่านี้จัดระเบียบเอกสารก็เป็นวิธีที่ดีในการฆ่าเวลา",
  ui_story_5043_50430101_111_dialog_content = "คำฟ้อง หลักฐาน. ข้อโต้แย้ง... โอเค นั่นคือทั้งหมด",
  ui_story_5043_50430101_112_dialog_content = "ฉันเกือบจะเสร็จแล้วที่นี่ ทีน่า เป็นไงบ้าง?",
  ui_story_5043_50430101_113_dialog_content = "หา? อะไรนะ?",
  ui_story_5043_50430101_114_dialog_content = "ขอโทษนะเลน การได้ยินนั้นดำเนินไปเป็นเวลาสามชั่วโมง ฉันทั้งหมด—หาว...",
  ui_story_5043_50430101_115_dialog_content = "อ๋อ อย่างนั้นเหรอ",
  ui_story_5043_50430101_116_dialog_content = "ช่างเป็นวันที่วุ่นวายของคุณ นี่ ทีน่าที่รัก ดื่มเครื่องดื่มปลอบประโลมใจสักถ้วยเพื่อให้เธอรู้สึกดีขึ้น...",
  ui_story_5043_50430101_117_dialog_content = "อืม ขอบคุณนะเลย์ *อึก*",
  ui_story_5043_50430101_118_dialog_content = "เอ๋!?",
  ui_story_5043_50430101_119_dialog_content = "ช็อคโกแลตร้อน?! เกลียดน้ำหวาน!!!",
  ui_story_5043_50430101_120_dialog_content = "ฮี่ฮี่ ตื่นแล้วเหรอ? ฉันไม่สนหรอกว่าคุณจะมีอาการเฉียบ ทำงานก่อน นอนทีหลัง",
  ui_story_5043_50430101_121_dialog_content = "และตอนนี้ที่ฉันคิดเกี่ยวกับมัน... ฉันรู้สึกเหมือนคุณง่วงนอนมากกว่าปกติในช่วง 2-3 วันที่ผ่านมา",
  ui_story_5043_50430101_122_dialog_content = "ฉันไม่คิดอย่างนั้น ฉันตั้งเป้าที่จะตื่นเป็นเวลาสี่ชั่วโมงทุกวัน",
  ui_story_5043_50430101_123_dialog_content = "แม้แต่วันนี้? และคุณก็เริ่มหาวก่อนที่เราจะทำงานเสร็จเมื่อวานนี้",
  ui_story_5043_50430101_124_dialog_content = "คุณนอนหลับไม่ดีเหรอ? นึกไม่ถึงว่าคุณเป็นโรคนอนไม่หลับ",
  ui_story_5043_50430101_125_dialog_content = "อะไร มันไร้สาระ เหมือนกับ...",
  ui_story_5043_50430101_126_dialog_content = "โอเค นั่นคือทุกอย่างเรียบร้อย ฉันจะกลับบ้าน.",
  ui_story_5043_50430101_127_dialog_content = "เจอกันพรุ่งนี้นะทุกคน",
  ui_story_5043_50430101_128_dialog_content = "ใช่ ฉันจะไปเร็วๆ นี้",
  ui_story_5043_50430101_129_dialog_content = "ลาก่อน เลดี้คาร์ลีนและสหายชาย",
  ui_story_5043_50430101_130_dialog_content = "แล้วเจอกัน!",
  ui_story_5043_50430101_131_dialog_content = "(นี่ฉันโดนลดสถานะเป็น \"เพื่อนผู้ชาย\" เหรอ?)",
  ui_story_5043_50430101_132_dialog_content = "ว้าว! ไม่เจอกันนาน เพื่อนชายของเลดี้คาร์ลีน!",
  ui_story_5043_50430101_133_dialog_content = "ฉันรู้จักเสียงนั้น...",
  ui_story_5043_50430101_134_dialog_content = "มาติเยอ! และโลเว ฉันไม่ได้คาดหวังว่าจะเจอคุณสองคน",
  ui_story_5043_50430101_135_dialog_content = "Matthieu ฉันเห็นว่าคุณเกียจคร้านและหน้าด้านเช่นเคย",
  ui_story_5043_50430101_136_dialog_content = "อย่าโกรธเจ้าหญิง ฉันไม่ได้มาที่นี่เพื่ออยู่เฉยๆ",
  ui_story_5043_50430101_137_dialog_content = "สิ่งที่น่าสนใจกำลังดำเนินอยู่ คุณต้องการใน?",
  ui_story_5043_50430101_138_dialog_content = "สิ่งที่ \"น่าสนใจ\"?",
  ui_story_5043_50430101_139_dialog_content = "ใช่. ฉันเพิ่งได้รับคำเอง คนทั่วไปจะไม่ได้ยินเรื่องนี้จนกว่าจะถึงวันพรุ่งนี้",
  ui_story_5043_50430101_140_dialog_content = "ถึงเวลาแล้วล่ะครับ",
  ui_story_5043_50430101_141_dialog_content = "มันเป็นแบบนี้ ศาลมีคดีที่ผิดปกติมากที่จะรับฟัง ตอนนี้ยังไม่ได้กำหนด แต่...",
  ui_story_5043_50430101_142_dialog_content = "มันดีเหมือนของฉัน",
  ui_story_5043_50430101_143_dialog_content = "สิ่งที่เขาหมายถึงคือเขาขอร้องและอ้อนวอนหัวหน้าผู้พิพากษาอย่างสิ้นหวังจนกว่าเขาจะได้",
  ui_story_5043_50430101_144_dialog_content = "เฮ้! หยุดรบกวน",
  ui_story_5043_50430101_145_dialog_content = "ยังไงก็เกี่ยวเนื่องกับ Mooncrown Day...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>สวนลุมโมโปลิส เขตที่อยู่อาศัย</color>",
  ui_story_5043_50430101_147_dialog_content = "ลาลา... ลาลาลา... ลาลา♪...",
  ui_story_5043_50430101_148_dialog_content = "(สิ่งแรกที่ต้องทำเมื่อกลับถึงบ้าน: ตรวจหาจดหมายหรือพัสดุ...)",
  ui_story_5043_50430101_149_dialog_content = "โอ๊ะ...",
  ui_story_5043_50430101_150_dialog_content = "ยังคงไม่มีอะไร.",
  ui_story_5043_50430101_151_dialog_content = "(ฉันยังมีใบและถั่ว <color=#FFB400>เขา</color> ส่งมาเมื่อเดือนที่แล้ว)",
  ui_story_5043_50430101_152_dialog_content = "(ถึงเวลาผมส่งของตอบแทนแต่ <color=#FFB400>เขา</color> ยังไม่ได้ให้ที่อยู่ใหม่)",
  ui_story_5043_50430101_153_dialog_content = "(พอมาคิดดูก็เกือบเดือนแล้วที่ได้ยินมา <color=#FFB400>เขา</color>.)",
  ui_story_5043_50430101_154_dialog_content = "(ค่อนข้างกังวล...จะส่งคุ้กกี้ที่ทำไปให้ได้เมื่อไหร่ <color=#FFB400>เขา</color>?)",
  ui_story_5043_50430101_155_dialog_content = "(บางทีฉันควรจะ... เป็นฝ่ายรุกมากกว่านี้หน่อย?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>วันถัดไป</color>",
  ui_story_5043_50430201_2_dialog_content = "นั่นคือสิ่งที่เป็น",
  ui_story_5043_50430201_3_dialog_content = "เจ้าเมืองตัดสินใจตั้งศาลชั่วคราวภายในสวนลูโมโพลิส",
  ui_story_5043_50430201_4_dialog_content = "ฉันตัดสินใจเรียกมันว่า <color=#FFB400>กองโรแมนติก</color>.",
  ui_story_5043_50430201_5_dialog_content = "ฉันเข้าใจ. และฉันจะทำให้ดีที่สุดต่อไป",
  ui_story_5043_50430201_6_dialog_content = "แต่ถ้าข้าพเจ้าถามว่าใครจะเป็นผู้พิพากษาหัวหน้าศาล? คุณจะรับภาระนั้นด้วยหรือไม่?",
  ui_story_5043_50430201_7_dialog_content = "ไม่ เราได้รับคำแนะนำจากเจ้าเมืองในเรื่องนั้นแล้ว เขาได้แนะนำผู้พิพากษา <color=#FFB400>ชวาบ</color>.",
  ui_story_5043_50430201_8_dialog_content = "การตัดสินใจที่ฉันไม่เข้าใจเลย แม้ว่าเขาจะสร้างความประทับใจให้กับเจ้าเมืองเมื่อวานนี้...",
  ui_story_5043_50430201_9_dialog_content = "และบางทีสไตล์ของเขาอาจเหมาะสมอย่างยิ่งสำหรับการรับมือกับเรื่องรักๆ ใคร่ๆ",
  ui_story_5043_50430201_10_dialog_content = "ดีมาก. Schwab มีวิธีแก้ไขความยุ่งเหยิงที่ไม่เหมือนใครของเขาเองเมื่อวานนี้ ฉันประทับใจ.",
  ui_story_5043_50430201_11_dialog_content = "แน่นอนว่าเขารู้วิธีใช้... เสน่ห์ของเขา",
  ui_story_5043_50430201_12_dialog_content = "คุณต้องไม่ผิดหวังแน่ เลย์",
  ui_story_5043_50430201_13_dialog_content = "คุณเพิ่งกลายเป็นผู้พิพากษาอย่างเป็นทางการ แต่ City Lord ชื่นชมความสามารถของคุณ",
  ui_story_5043_50430201_14_dialog_content = "และเมื่อคุณกลับมาจากแผนก Romance คุณจะอยู่ในตำแหน่งที่ดีสำหรับการเลื่อนขั้น",
  ui_story_5043_50430201_15_dialog_content = "ใช่. ขอบคุณ หัวหน้าผู้พิพากษา",
  ui_story_5043_50430201_16_dialog_content = "นอกจากนี้ ฉันยังมีงานอื่นให้คุณทำ",
  ui_story_5043_50430201_17_dialog_content = "ในความเป็นจริง มันอาจเป็นกรณีที่ยุ่งยากที่สุดที่แผนก Romance ต้องจัดการในตอนนี้",
  ui_story_5043_50430201_18_dialog_content = "คุณอาจเคยได้ยินเกี่ยวกับมัน? <color=#FFB400>กรณีรูปปั้นหัวขาด</color>?",
  ui_story_5043_50430201_19_dialog_content = "ฉันได้รับคดีแรกเร็วขนาดนั้นเลยเหรอ?",
  ui_story_5043_50430201_20_dialog_content = "อา รู้สึกโล่งใจที่ได้ยินว่าคุณกระตือรือร้นมาก ฉันมีห้าหรือหกคนปฏิเสธคดีนี้แล้ว",
  ui_story_5043_50430201_21_dialog_content = "และทำไมพวกเขาถึงทำเช่นนั้น?",
  ui_story_5043_50430201_22_dialog_content = "นอกเหนือจากข้อเท็จจริงที่ว่ามันแปลก... พวกเขาส่วนใหญ่บอกว่าพวกเขายุ่งกับการออกเดตกับคนรัก",
  ui_story_5043_50430201_23_dialog_content = "อ่า เข้าใจแล้ว...",
  ui_story_5043_50430201_24_dialog_content = "(ขุนนางเหล่านั้นไม่เคยเปลี่ยน...)",
  ui_story_5043_50430201_25_dialog_content = "โจทก์ในคดีนี้เป็นขุนนางจาก Lumopolis Courtyard, Mr. <color=#FFB400>ไบรอน</color>.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>สี่วันที่แล้ว</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>ดิง ดิง—ดิง—</color>",
  ui_story_5043_50430201_28_dialog_content = "ฉันกำลังมา ฉันกำลังมา หยุดบ่น!",
  ui_story_5043_50430201_29_dialog_content = "นายโทรมาหรอ? คุณสั่นกระดิ่งแห่งความยุติธรรม?",
  ui_story_5043_50430201_30_dialog_content = "ฉันทำ. อยากฟ้องใคร! มันเป็นเพื่อนบ้านของฉัน",
  ui_story_5043_50430201_31_dialog_content = "เขาเสียหาย <color=#FFB400>กาลาเทีย</color>รูปปั้นที่ตั้งตระหง่านอยู่นอกหอธรรม ฉันเห็นด้วยตาของฉันเอง!",
  ui_story_5043_50430201_32_dialog_content = "รอก่อน. ฉันรู้ว่ารูปปั้นนั่นเป็นสัญลักษณ์ของความยุติธรรม แต่ชื่อ Galatea ตั้งแต่เมื่อไหร่?",
  ui_story_5043_50430201_33_dialog_content = "และใช่ มันพังเมื่อสองสามวันก่อน แต่พูดตามตรง เราคิดว่ามันเก่าแล้ว...",
  ui_story_5043_50430201_34_dialog_content = "นางสาวโปรดระวังภาษาของคุณ กาลาเตอาเป็น <color=#FFB400>\"เธอ\"</color>!!! ฉันเป็นคนตั้งชื่อให้เธอเอง",
  ui_story_5043_50430201_35_dialog_content = "เอ่อ ก็ได้ ถ้าอย่างนั้นคุณช่วยส่งคำร้องของคุณให้ฉันได้ไหม",
  ui_story_5043_50430201_36_dialog_content = "ขอเช็กดูก่อนนะครับ...",
  ui_story_5043_50430201_37_dialog_content = "หืม? คุณไบรอน อาชญากรรมที่คุณกล่าวหาเพื่อนบ้านของคุณ ถูกต้องไหม",
  ui_story_5043_50430201_38_dialog_content = "คุณเพิ่งบอกว่าเขาทำลายรูปปั้น แต่นี่คุณเขียน <color=#FFB400>\"อุปสรรคความรัก</color>\"",
  ui_story_5043_50430201_39_dialog_content = "ถูกต้อง. เพราะ...",
  ui_story_5043_50430201_40_dialog_content = "Galatea เป็นของฉัน <color=#FFB400>คนรัก</color>!",
  ui_story_5043_50430201_41_dialog_content = "เขาจึงหลงรักรูปปั้น...และตอนนี้อยากจะฟ้องคนที่ทำลายมัน?",
  ui_story_5043_50430201_42_dialog_content = "ใช่. เนื่องจากรูปปั้นถูกจัดให้เป็นสถานที่สาธารณะ เราจึงไม่สามารถห้ามไม่ให้ใครตกหลุมรักรูปปั้นได้",
  ui_story_5043_50430201_42X1_dialog_content = "พูดกันตามตรงแล้ว นี่เป็นกรณีของ Romance Division",
  ui_story_5043_50430201_43_dialog_content = "ฉันยังส่งคนไปพูดกับจำเลย",
  ui_story_5043_50430201_44_dialog_content = "มีช่องโหว่ในเรื่องราวของมิสเตอร์ไบรอน จำเลยในคดีนี้อาจไม่ใช่ผู้ต้องสงสัย",
  ui_story_5043_50430201_45_dialog_content = "อย่างที่คุณทราบ ที่นี่ใน Hall of Justice เราตรวจสอบเท่าที่เราตัดสิน ลีน เราต้องหาให้ได้ว่าเกิดอะไรขึ้น ก่อนที่คดีจะได้รับการพิจารณา",
  ui_story_5043_50430201_46_dialog_content = "มิฉะนั้น เราจะสิ้นสุดการเลื่อนคดีออกไปจนกว่าจะมีการพิจารณาคดีในอนาคต และแผนกโรมานซ์ไม่ใช่ข้อตกลงถาวรด้วยซ้ำ ดังนั้นนั่นจึงไม่ใช่ทางเลือก",
  ui_story_5043_50430201_47_dialog_content = "ใช่ฉันเข้าใจแล้ว. ฉันจะไขคดีให้ได้ก่อนที่แผนกโรแมนซ์จะปิด ฉันรับรอง",
  ui_story_5043_50430201_48_dialog_content = "ฉันดีใจที่ได้ยินเช่นนั้น. และเพื่อนร่วมงานของคุณสองคนจะคอยช่วยเหลือคุณ",
  ui_story_5043_50430201_49_dialog_content = "คนหนึ่งคือทีน่าเพื่อนเก่าของคุณ เธอตกลงที่จะช่วยเมื่อเช้านี้",
  ui_story_5043_50430201_50_dialog_content = "ฉันขอให้เธอตรวจเอกสาร แม้ว่าตอนนี้ฉันสงสัยว่าเธอคงหลับไปแล้ว",
  ui_story_5043_50430201_51_dialog_content = "อีกคน...ก็ปวดหัวแต่ช่างเถอะ <color=#FFB400>มีประสบการณ์มากขึ้น</color> กว่าที่คุณ. ฉันแน่ใจว่าเขาจะให้คำแนะนำที่เป็นประโยชน์แก่คุณ",
  ui_story_5043_50430201_52_dialog_content = "คุณสามารถพบเขาตอนนี้ที่หน้ารูปปั้นนั้น",
  ui_story_5043_50430201_53_dialog_content = "เปรียบเทียบบันทึกกับ Tina เมื่อคุณเสร็จสิ้นการสืบสวน",
  ui_story_5043_50430201_54_dialog_content = "ฉันจะไปทันที",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>สวน Lumopolis ข้างรูปปั้น</color>",
  ui_story_5043_50430201_56_dialog_content = "(ฉันสงสัยว่าคนที่ \"มีประสบการณ์มากกว่า\" คนนี้ที่หัวหน้าผู้พิพากษาคลุมเครือคือใคร...)",
  ui_story_5043_50430201_57_dialog_content = "โอ้ โถงยุติธรรมปล่อยให้คนธรรมดาเข้าประตูเดี๋ยวนี้เลยเหรอ?",
  ui_story_5043_50430201_58_dialog_content = "(น่าจะเดาได้...)",
  ui_story_5043_50430201_59_dialog_content = "ฉันคิดว่าเลย์นดูเหมือนผู้ตัดสินที่เหมาะสมมากกว่าคุณ แมทติเยอ",
  ui_story_5043_50430201_60_dialog_content = "สวัสดีกัปตันคาร์ลีนและความปรารถนาดีของฉัน",
  ui_story_5043_50430201_61_dialog_content = "กรุณาอย่ายืนอยู่บนพิธี นี่คือ PlayerName. มัทติเยอขอให้เราทั้งคู่มีส่วนร่วมในการสอบสวน",
  ui_story_5043_50430201_62_dialog_content = "คุณคือ Caeleste ในตำนาน! คุณเป็นคนที่เข้าถึงได้มากขึ้น!",
  ui_story_5043_50430201_63_dialog_content = "คุณใจดีมาก ฉันหวังว่าฉันสามารถช่วยได้บ้าง",
  ui_story_5043_50430201_64_dialog_content = "<size=32>ข่าวลือในโลกนี้พูดถึงฉันว่าอย่างไร...</size>",
  ui_story_5043_50430201_65_dialog_content = "คุณควรขอบคุณพระเจ้าแห่งแสงสว่าง คนธรรมดา ด้วยความช่วยเหลือของเรา งานของคุณจะดำเนินไปอย่างรวดเร็ว",
  ui_story_5043_50430201_66_dialog_content = "ฉันจะประหลาดใจถ้ามันไม่เลวร้าย",
  ui_story_5043_50430201_67_dialog_content = "เกิดอะไรขึ้นมือใหม่? คุณดูไม่ตื่นเต้น",
  ui_story_5043_50430201_68_dialog_content = "นี่เป็นหนึ่งในคดีที่แปลกประหลาดที่สุดในประวัติศาสตร์ของ Hall of Justice แสดงความกระตือรือร้นเล็กน้อย!",
  ui_story_5043_50430201_69_dialog_content = "ใช่. รูปปั้นแปลกๆ อาชญากรรมแปลกๆ โจทก์แปลกๆ และพี่เลี้ยงสุดแปลก",
  ui_story_5043_50430201_70_dialog_content = "ดูมันเด็ก! ให้เกียรติกันหน่อยดีกว่า",
  ui_story_5043_50430201_71_dialog_content = "ดีมาก. ฉันไม่ได้มาที่นี่เพื่อทะเลาะกับคุณ ฉันถือว่าคุณได้ตรวจสอบรูปปั้นแล้ว?",
  ui_story_5043_50430201_72_dialog_content = "ฮะ? อ๋อ คุณหมายถึงกล่องเงินเหรอ",
  ui_story_5043_50430201_73_dialog_content = "ขอโทษนะ มันไม่มีหัว มันทำให้ฉันนึกถึงบางอย่างที่คุณอาจเก็บเหรียญไว้ได้ มันทำให้ฉันอยากจะโยน Nightium เข้าไป",
  ui_story_5043_50430201_74_dialog_content = "โอ้ได้โปรด. ลองทำสิ่งนี้อย่างจริงจัง ...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>สแนป—</color>",
  ui_story_5043_50430201_76_dialog_content = "ว่าไงนะ?",
  ui_story_5043_50430201_77_dialog_content = "กราาาาาา! คำราม!",
  ui_story_5043_50430201_78_dialog_content = "อะไรของมันวะ?! Eclipsites เข้าไปในสวน Lumopolis ได้อย่างไร?",
  ui_story_5043_50430201_79_dialog_content = "มันเป็นไปไม่ได้! Lumopolis ได้รับการคุ้มกันทั้งกลางวันและกลางคืน ไม่มีทางที่ Eclipsite จะเข้ามาได้...",
  ui_story_5043_50430201_80_dialog_content = "ยาม!",
  ui_story_5043_50430201_81_dialog_content = "คุณกรอนรู!",
  ui_story_5043_50430201_82_dialog_content = "ฉันจะตรวจสอบบันทึกการเข้าและออกทั้งหมด และบอก Nightwatch ว่าฉันต้องการรายงานเกี่ยวกับกิจกรรมล่าสุดทั้งหมด!",
  ui_story_5043_50430201_83_dialog_content = "สำหรับ Eclipsites ... PlayerNameฉันคิดว่าคุณทั้งสี่สามารถจัดการกับพวกเขา?",
  ui_story_5043_50430201_84_dialog_content = "แน่นอน. ไปเถอะ คาร์ลีน",
  ui_story_5043_50430201_85_dialog_content = "ตกลงแล้ว ถึงเวลาที่ Eclipsites จะได้รับการตัดสินขั้นสุดท้ายแล้ว",
  ui_story_5043_50430202_1_dialog_content = "มันจบแล้ว! ไม่มีใครได้รับบาดเจ็บใช่ไหม",
  ui_story_5043_50430202_2_dialog_content = "ฉันสบายดี. รังเกียจเพียงเล็กน้อย",
  ui_story_5043_50430202_3_dialog_content = "ฉันเพิ่งไปทำงาน ตอนนี้ฉันต้องการอาบน้ำอีกครั้ง",
  ui_story_5043_50430202_4_dialog_content = "เฮ้ สามัญชน คุณสบายดีไหม",
  ui_story_5043_50430202_5_dialog_content = "ขอบคุณที่ถาม. เมื่อมันเกิดขึ้น ฉันไม่มีความสุขเหมือนกันกับการอาบน้ำตลอดเวลาที่พวกขุนนางชอบ",
  ui_story_5043_50430202_6_dialog_content = "ฉันรู้สึกเสียใจสำหรับคุณ แม้ว่าฉันคิดว่านั่นหมายความว่า Loewe เป็นโรคกลัวเชื้อโรคที่ใหญ่ที่สุดที่นี่",
  ui_story_5043_50430202_7_dialog_content = "คุณมักจะปกปิดตัวเองให้มิดชิดอยู่เสมอ Loewe ฉันสงสัยว่าคุณพบว่าอากาศสกปรก",
  ui_story_5043_50430202_8_dialog_content = "พวกคุณน่าจะลงไปได้ถ้ารูปปั้นพัง",
  ui_story_5043_50430202_9_dialog_content = "อย่าละเลยฉัน!",
  ui_story_5043_50430202_10_dialog_content = "โอเค คุณเห็นมามากพอแล้ว Hall of Justice สามารถจัดการกับมันได้ในขณะนี้",
  ui_story_5043_50430202_11_dialog_content = "สำคัญ <color=#FFB400>หลักฐาน</color> ไม่ควรปล่อยให้นั่งกลางแจ้งแบบนี้",
  ui_story_5043_50430202_12_dialog_content = "ตามที่โจทก์กล่าวคือ <color=#FFB400>เหยื่อ</color>.",
  ui_story_5043_50430202_13_dialog_content = "เดี๋ยวขอผมดูใกล้ๆ...",
  ui_story_5043_50430202_14_dialog_content = "อืม. ส่วนแตกหักสะอาดกว่า ดูไม่เหมือนรอยร้าวเก่าที่แตกออกในที่สุด",
  ui_story_5043_50430202_15_dialog_content = "เหมือนมีคนจงใจหักหัวมากกว่า",
  ui_story_5043_50430202_16_dialog_content = "PlayerNameคุณมีคำแนะนำใด ๆ ?",
  ui_story_5043_50430202_17_dialog_content = "มีสิ่งหนึ่งที่แปลก",
  ui_story_5043_50430202_18_option_content = "หัวขาด",
  ui_story_5043_50430202_19_dialog_content = "ดูไม่เหมือนการก่อกวนโดยธรรมชาติ การหยุดพักนั้นสะอาดเกินไป",
  ui_story_5043_50430202_20_dialog_content = "นอกจากนี้ยังไม่มีความเสียหายอื่นใด แค่หัวขาด..",
  ui_story_5043_50430202_21_option_content = "เศษรูปปั้น",
  ui_story_5043_50430202_22_dialog_content = "สภาพแวดล้อมที่สะอาดเกินไป ไม่ควรมีเศษรูปปั้นวางอยู่รอบ ๆ ?",
  ui_story_5043_50430202_23_dialog_content = "คนที่ส่งไปเก็บหลักฐานคงกวาดล้างพวกนั้นไปแล้ว",
  ui_story_5043_50430202_24_dialog_content = "T- นั่นสมเหตุสมผลแล้ว! ในกรณีนั้น ฉันคิดว่าสิ่งที่แปลกคือ—หัวที่ขาดหายไป",
  ui_story_5043_50430202_25_dialog_content = "ฉันคิดว่าคุณพูดถูก ดูเหมือนว่ามีคนหักหัวของรูปปั้นเพื่อให้พวกเขาทำได้ <color=#FFB400>ขโมยมัน</color>...",
  ui_story_5043_50430202_26_dialog_content = "เดี๋ยวก่อน เดี๋ยวก่อน ท่านใดเห็น <color=#FFB400>ที่</color>? ฉันเพิ่งโผล่มาจากไหนก็ไม่รู้",
  ui_story_5043_50430202_27_dialog_content = "ดูสิ ข้างหน้าต่างนั่น บนท้องฟ้าเหนือลูโมโปลิส...",
  ui_story_5043_50430202_28_dialog_content = "มันคือ <color=#FFB400>ดวงจันทร์</color>.",
  ui_story_5043_50430202_29_dialog_content = "ฉันเห็นมัน!",
  ui_story_5043_50430202_30_dialog_content = "เรื่องแปลกๆ ก็เกิดขึ้นเรื่อยๆ เกิดอะไรขึ้นในโลกนี้?",
  ui_story_5043_50430202_31_dialog_content = "ช่างน่าสนใจ เราควรจะดูหรือไม่?",
  ui_story_5043_50430202_32_dialog_content = "รอก่อน... เรายังมีงานต้องทำ!",
  ui_story_5043_50430202_33_dialog_content = "อ้าว หมดแล้วเหรอ",
  ui_story_5043_50430202_34_dialog_content = "เฮ้ ทีน่า นี่คือ PlayerName. คาเลสไทต์.",
  ui_story_5043_50430202_35_dialog_content = "หึหึ จริง ๆ แล้วเราเจอกันเมื่อเดือนก่อน ในวันมูนคราวน์",
  ui_story_5043_50430202_36_dialog_content = "สวัสดีตอนเช้า, PlayerName. ดีใจที่ได้พบคุณอีกครั้ง",
  ui_story_5043_50430202_37_dialog_content = "สวัสดีทีน่า แม้จะไม่ใช่ตอนเช้าอีกต่อไป...",
  ui_story_5043_50430202_38_dialog_content = "ทีน่ามักจะคิดว่าเป็นเวลาเช้าเมื่อตื่นขึ้น",
  ui_story_5043_50430202_39_dialog_content = "คุณมีเวลาที่สมบูรณ์แบบ ทีน่า มาแบ่งปันบันทึกการสอบสวนกัน",
  ui_story_5043_50430202_40_dialog_content = "ถ้าอย่างนั้น...ให้ทั้งคู่พูดในสิ่งที่เรามีพร้อมกัน จนถึงตอนนี้ ฉันได้ค้นพบ—",
  ui_story_5043_50430202_41_dialog_content = "เปล่า",
  ui_story_5043_50430202_42_dialog_content = "ถอนหายใจ คุณก็ยังไม่มีความคืบหน้าเช่นกัน?",
  ui_story_5043_50430202_43_dialog_content = "ฉันอ่านเอกสารคดีที่หัวหน้าผู้พิพากษาให้ฉันซ้ำแล้วซ้ำเล่า",
  ui_story_5043_50430202_44_dialog_content = "แต่ทั้งหมดนี้ไร้เหตุผลและไม่สอดคล้องกัน ฉันไม่สามารถเข้าใจอะไรได้เลย",
  ui_story_5043_50430202_45_dialog_content = "อย่างน้อยเราก็มีทฤษฎีหนึ่งที่เป็นไปได้",
  ui_story_5043_50430202_46_dialog_content = "PlayerName และฉันสงสัยว่าศีรษะของรูปปั้นถูกขโมยไป",
  ui_story_5043_50430202_47_dialog_content = "ใช่... ทำไมใคร ๆ ถึงทำอย่างนั้น?",
  ui_story_5043_50430202_48_dialog_content = "ใครจะรู้! บางที Judge Jr. อาจจะตัดสินใจหาหมวกใหม่ให้ตัวเอง",
  ui_story_5043_50430202_49_dialog_content = "หากเราไม่ดำเนินการใด ๆ เราอาจจะเลิกใช้มันในวันนี้?",
  ui_story_5043_50430202_50_dialog_content = "รอ! อันที่จริง ฉัน... เอิ่ม...",
  ui_story_5043_50430202_51_dialog_content = "คือผมอยากจะขอคำแนะนำจากพวกคุณทุกคนในเรื่องส่วนตัว",
  ui_story_5043_50430202_52_dialog_content = "เอ่อ เรื่องส่วนตัวแบบไหนกันแน่? ฉันไม่แน่ใจว่าฉันต้องการมีส่วนร่วม ...",
  ui_story_5043_50430202_53_dialog_content = "F-สบายดี เมื่อเร็ว ๆ นี้ฉันพบปัญหาเล็กน้อยและต้องการความคิดเห็นที่สอง",
  ui_story_5043_50430202_54_dialog_content = "โอ้ เรื่องส่วนตัวในเวลาเช่นนี้?",
  ui_story_5043_50430202_55_dialog_content = "ให้ฉันเสี่ยงทาย มันเป็นปัญหาที่โรแมนติกใช่ไหม?",
  ui_story_5043_50430202_56_dialog_content = "คุณตื่นเต้นกับเรื่องนี้มากเกินไป",
  ui_story_5043_50430202_57_dialog_content = "อืม อย่างไรก็ตาม ฉันขอเชิญทุกท่านมาที่สถานที่ของฉันได้ไหม ฉันเตรียมชาและเค้กแล้ว",
  ui_story_5043_50430202_58_dialog_content = "PlayerName, ฉันอยากให้คุณมาด้วย",
  ui_story_5043_50430202_59_dialog_content = "ฉันได้ยินมาว่าพวกคาเลสไทต์เข้าใจอารมณ์ของผู้คนได้ดีมาก ดังนั้นคุณต้องช่วยฉัน",
  ui_story_5043_50430202_60_dialog_content = "มันจะเป็นเกียรติ แม้ว่าฉันจะไม่แน่ใจว่าเรามีความสามารถพิเศษนั้น...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>สวนลุมโปลิส บ้านของทีน่า</color>",
  ui_story_5043_50430301_2_dialog_content = "โอเค นี่คือสิ่งที่เกิดขึ้น",
  ui_story_5043_50430301_3_dialog_content = "ในวัน Mooncrown เมื่อเดือนที่แล้ว ฉันได้รับของขวัญจาก <color=#FFB400>เขา</color>.",
  ui_story_5043_50430301_4_dialog_content = "มันเป็นแค่เรื่องธรรมดา แต่ฉันสามารถบอกได้ <color=#FFB400>เขา</color> ห่วงใยฉันจริงๆ",
  ui_story_5043_50430301_5_dialog_content = "W-ว้าว! เดี๋ยวก่อนทีน่า คุณกำลังมีความรักหรือเปล่า?",
  ui_story_5043_50430301_6_dialog_content = "ฮะ? ไม่ ฉันไม่คิดอย่างนั้น...",
  ui_story_5043_50430301_7_dialog_content = "ฟังดูเหมือนสิ่งที่คู่รักทำกัน",
  ui_story_5043_50430301_8_dialog_content = "ถ้าคิดเหมือนกัน...",
  ui_story_5043_50430301_9_dialog_content = "โอ้ ไม่เป็นไร! ขอจบเรื่องราว",
  ui_story_5043_50430301_10_dialog_content = "เกือบหนึ่งเดือนแล้วตั้งแต่วัน Mooncrown และตามธรรมเนียมแล้ว ฉันควรจะส่ง <color=#FFB400>เขา</color> เป็นของขวัญตอบแทน",
  ui_story_5043_50430301_11_dialog_content = "ก็เลยทำคุ้กกี้ให้ <color=#FFB400>เขา</color>. ฉันยังทำคุกกี้แต่ละชิ้นในรูปทรงที่แตกต่างกัน",
  ui_story_5043_50430301_12_dialog_content = "ดังนั้นคุกกี้จึงพร้อมที่จะส่ง แต่...",
  ui_story_5043_50430301_13_dialog_content = "แต่ <color=#FFB400>เขา</color> ไม่ตอบจดหมายฉันอีกเลย",
  ui_story_5043_50430301_14_dialog_content = "ฉันไม่มีโอกาสแอบไปประชุมด้วย <color=#FFB400>เขา</color>. และตอนนี้ฉันไม่ได้รับจดหมายเลยด้วยซ้ำ",
  ui_story_5043_50430301_15_dialog_content = "ฉันกังวลมาก มันทำให้ฉันตื่น ฉันนอนคืนละ 16 ชั่วโมงเท่านั้น!",
  ui_story_5043_50430301_16_dialog_content = "ช่างเป็นคนที่น่ารังเกียจ!",
  ui_story_5043_50430301_17_dialog_content = "ใช่. เขาฟังดูแย่กว่ามาติเยอ",
  ui_story_5043_50430301_18_dialog_content = "ฉันขอแนะนำให้คุณเลิกกับเขา",
  ui_story_5043_50430301_19_dialog_content = "ไม่ ฉันยังทำอย่างนั้นไม่ได้ ฉันแน่ใจว่าเขามีเหตุผลของเขา",
  ui_story_5043_50430301_20_dialog_content = "หลังจากนั้น, <color=#FFB400>เขา</color> มีลักษณะค่อนข้างเฉพาะ ผู้คนสังเกตเห็น <color=#FFB400>เขา</color> ไม่ว่าเขาจะไปที่ไหน ดังนั้นบางทีเขาอาจจะไม่สามารถติดต่อได้มากเท่าที่ต้องการ",
  ui_story_5043_50430301_21_dialog_content = "เอ่อโอ้. ทีน่ามีปัญหาความรัก",
  ui_story_5043_50430301_22_dialog_content = "หืม...",
  ui_story_5043_50430301_23_dialog_content = "<size=32>เฮ้, PlayerName, มาติเยอ, โลเว่. ฉันมีทฤษฎี...</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>นี้ <color=#FFB400>ผู้ชาย</color> ทีน่าพูดถึงฟังดูคุ้นๆ นะ!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>จริง! ใครไปใครมาก็สะดุดตา...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>และใช้ความพยายามเพียงน้อยนิดเพื่อให้ผู้ชื่นชมมีความสุข...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>และโหดร้าย ตื้นเขิน หลงตัวเอง ถือตัว...</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>ฟังดูเหมือนเขาอาจเป็นแฝดของคุณ</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>ยังไงก็ต้องคนนี้ทีน่าพูดถึง <color=#FFB400>ชวาบ</color>, ขวา?</size>",
  ui_story_5043_50430301_30_dialog_content = "เฮ้ พวกเธอกระซิบอะไรกันอยู่เหรอ?",
  ui_story_5043_50430301_31_dialog_content = "อะแฮ่ม. โอเค ทีน่า เรารู้ว่าใครที่คุณชอบ",
  ui_story_5043_50430301_32_dialog_content = "อะไร คุณเดาแล้ว? ฉันหวังว่าจะเก็บมันไว้เป็นความลับ...",
  ui_story_5043_50430301_33_dialog_content = "(ดูเหมือนทีน่าไม่มีทางเลือกนอกจากต้องยอมรับ...)",
  ui_story_5043_50430301_34_dialog_content = "ครั้งแรกที่ฉันเห็นเขาคือคฤหาสน์ซาลาร์",
  ui_story_5043_50430301_35_dialog_content = "ฉันได้รับเชิญไปงานเต้นรำที่นั่น",
  ui_story_5043_50430301_36_dialog_content = "แต่ฉันมาถึงก่อนเวลาเล็กน้อยและฉันถูกพาไปที่สวนเพื่อรอ",
  ui_story_5043_50430301_37_dialog_content = "แต่แน่นอนว่า Salars มีสวนที่น่าทึ่ง และฉันก็หลงเข้าไปในเขาวงกตพุ่มไม้",
  ui_story_5043_50430301_38_dialog_content = "สวรรค์รู้ดีว่าฉันอยู่ในนั้นนานแค่ไหน ทันใดนั้นข้าพเจ้าก็พบศาลาหลังหนึ่งและท่านนั่งอยู่ในนั้น",
  ui_story_5043_50430301_39_dialog_content = "เขาประหลาดใจที่เห็นใครที่นั่น และเราใช้เวลาจ้องตากันภายใต้ท้องฟ้าสีครามที่สวยงามนั้น...",
  ui_story_5043_50430301_40_dialog_content = "นี่เป็นครั้งแรกที่ฉันสังเกตเห็นว่าเขาอ่อนโยนและใจดีเพียงใด ดูเหมือนเขาจะเป็นหนึ่งเดียวกับต้นไม้และดอกไม้รอบตัวเขา",
  ui_story_5043_50430301_41_dialog_content = "สุดท้ายเขาก็จากไปก่อนฉัน แต่วันนั้นฉันไม่สนใจใครเลย",
  ui_story_5043_50430301_42_dialog_content = "หึหึ ช่างโรแมนติก",
  ui_story_5043_50430301_43_dialog_content = "(คฤหาสน์ซาลาร์ ถ้าอย่างนั้นก็ต้องเป็นชวาบ ซาลาร์)",
  ui_story_5043_50430301_44_dialog_content = "(\"อ่อนโยน\"? \"ใจดี\"?! ผู้ชายคนนั้นน่ะเหรอ?...)",
  ui_story_5043_50430301_45_dialog_content = "เนื่องจากท่านทราบอยู่แล้วว่าเขาคือใคร ข้าพเจ้ามีเรื่องจะขอร้องท่านทุกคน",
  ui_story_5043_50430301_46_dialog_content = "ฉันต้องการให้คุณช่วยฉันด้วย <color=#FFB400>ปฏิบัติการ Acci-Meet</color>.",
  ui_story_5043_50430301_47_dialog_content = "Acci-Meet คืออะไรในโลกนี้",
  ui_story_5043_50430301_48_dialog_content = "ฉันต้องการวิศวกรเป็นจำนวนมาก <color=#FFB400>การพบกันโดยบังเอิญ</color> กับเขาให้ได้มากที่สุด ถูกต้อง ฉลาดเหรอ?",
  ui_story_5043_50430301_49_dialog_content = "คุณจะไม่ยอมแพ้ใช่ไหม แม้ว่าเราจะไม่ช่วยคุณ",
  ui_story_5043_50430301_50_dialog_content = "ไม่ล่ะขอบคุณ...",
  ui_story_5043_50430301_51_dialog_content = "ดีมาก. ฉันยินดีช่วยเหลือเพื่อนร่วมงานเสมอ",
  ui_story_5043_50430301_52_dialog_content = "ฉันก็เหมือนกัน",
  ui_story_5043_50430301_53_dialog_content = "กรรร... กรรรร...",
  ui_story_5043_50430301_54_dialog_content = "อิคลิพไซท์!",
  ui_story_5043_50430301_55_dialog_content = "โอ้จริงเหรอ! บ่าว! บ่าว!",
  ui_story_5043_50430301_56_dialog_content = "ช่างเถอะ. เป็นเวลานานแล้วที่ฉันได้ฝึกฝนหัตถ์ศักดิ์สิทธิ์",
  ui_story_5043_50430301_57_dialog_content = "ฉันจะล้างมลทินนี้ด้วยตัวเอง",
  ui_story_5043_50430301_58_dialog_content = "นี่ไม่ใช่บ้านของเธอเองเหรอ? คุณกำลังทำตัวเหมือนแมลงสาบสองสามตัว!",
  ui_story_5043_50430302_1_dialog_content = "ช่างเป็นการต่อสู้ที่น่าตื่นเต้น... *หาว*",
  ui_story_5043_50430302_2_dialog_content = "ฉันไม่ได้สังเกตมาก่อน แต่คุณถนัดซ้ายหรือเปล่า",
  ui_story_5043_50430302_3_dialog_content = "ฮ่าๆ ใช่ฉันเป็น ฉันได้รับการฝึกฝนด้วยวิธีนี้เพื่อจัดการกับพลังของหัตถ์ศักดิ์สิทธิ์",
  ui_story_5043_50430302_4_dialog_content = "แต่ฉันมักจะรู้สึกเหนื่อยมากหลังจากการต่อสู้...",
  ui_story_5043_50430302_5_dialog_content = "ถ้าคุณไปนอนตอนนี้ เราก็ไปกันเถอะ",
  ui_story_5043_50430302_6_dialog_content = "เตียง? เลขที่! ฉันเต็มไปด้วยพลังงาน",
  ui_story_5043_50430302_7_dialog_content = "กลับไปทำธุรกิจกันเถอะ ฉันต้องการให้ทุกคนช่วยฉันเกี่ยวกับ Operation Accimeet",
  ui_story_5043_50430302_8_dialog_content = "โอเค แต่... ยังไง?",
  ui_story_5043_50430302_9_dialog_content = "ก็... พูดตามตรง ฉันไม่เคยไล่ตามใครมาก่อน นั่นเป็นเหตุผลที่ฉันต้องการความช่วยเหลือจากคุณ",
  ui_story_5043_50430302_10_dialog_content = "ฉันต้องทำอย่างไร?",
  ui_story_5043_50430302_11_dialog_content = "ขอคิดดูก่อน...เคยอ่านเจอในหนังสือว่าก้าวแรกของการเปลี่ยนแปลงคือการยอมรับข้อบกพร่องของตัวเอง",
  ui_story_5043_50430302_12_dialog_content = "ฉันคิดว่าวิธีที่ดีที่สุดในการเอาชนะใจเขาคือ—<color=#FFB400> เพื่อสารภาพรักของคุณ</color>.",
  ui_story_5043_50430302_13_dialog_content = "ไปในที่ที่เขาน่าจะปรากฏตัวและรอเขาอยู่",
  ui_story_5043_50430302_14_dialog_content = "และเมื่อเขาปรากฏตัวขึ้น คุณก็โจมตี! ทำให้เขาประหลาดใจ!",
  ui_story_5043_50430302_15_dialog_content = "โอ้. ฉันเห็น...",
  ui_story_5043_50430302_16_dialog_content = "ผิดอีกแล้ว คนธรรมดา ทีน่าไม่สามารถพึ่งพาการริเริ่มเพียงอย่างเดียว เธอยังต้องเรียนรู้ <color=#FFB400>ศิลปะแห่งการปกปิด</color>.",
  ui_story_5043_50430302_17_dialog_content = "เธอจำเป็นต้องซ่อนความรู้สึกที่แท้จริงของเธอ เขาไม่ได้รับอนุญาตให้เห็นว่าเธอกังวลแค่ไหน",
  ui_story_5043_50430302_18_dialog_content = "หากคุณมีความกล้าที่จะเข้าหาเขาแต่ยังประหม่าเกินกว่าจะสบตาเขา ก็แค่แสร้งทำเป็นเขินอาย",
  ui_story_5043_50430302_19_dialog_content = "อ้อเข้าใจแล้ว! ฉันเข้าใจ.",
  ui_story_5043_50430302_20_dialog_content = "และนอกจากนี้ยังมี-<color=#FFB400>การลาดตระเวน</color>.",
  ui_story_5043_50430302_21_dialog_content = "คุณต้องดูทัศนคติของเขาในขณะที่พูดคุยหัวข้อที่ดูไม่มีพิษมีภัย",
  ui_story_5043_50430302_22_dialog_content = "คุณจะสามารถเข้าใจความรู้สึกที่แท้จริงของเขาได้ในการสนทนาสองหรือสามครั้ง",
  ui_story_5043_50430302_23_dialog_content = "นั่นฟังดูยาก แต่ฉันจะทำให้ดีที่สุด...",
  ui_story_5043_50430302_24_dialog_content = "หลังจากพิจารณาอย่างถี่ถ้วนแล้ว ฉันคิดว่าเป็นการดีที่สุดที่จะ <color=#FFB400>ซื่อสัตย์</color>.",
  ui_story_5043_50430302_25_dialog_content = "ตลอดความสัมพันธ์ นิสัยและข้อบกพร่องทั้งหมดของคุณจะถูกเปิดเผยให้อีกฝ่ายเห็น",
  ui_story_5043_50430302_26_dialog_content = "คุณจะไม่สามารถปกปิดสิ่งเหล่านั้นได้ตลอดไป ดังนั้น ความซื่อสัตย์เป็นสิ่งสำคัญที่สุด",
  ui_story_5043_50430302_27_dialog_content = "คุณถูก! แม้ว่าฉันหวังว่าเราจะไปถึงขั้นนั้นได้...",
  ui_story_5043_50430302_28_dialog_content = "ขอบคุณทุกคน! ฉันจะจำคำแนะนำทั้งหมดของคุณ",
  ui_story_5043_50430302_29_dialog_content = "ว่าแต่... พวกคุณพูดจากประสบการณ์จริงเหรอ?",
  ui_story_5043_50430302_30_dialog_content = "อะแฮ่ม...",
  ui_story_5043_50430302_31_dialog_content = "ฉันเกรงว่าฉันไม่มีประสบการณ์จริง ไม่...",
  ui_story_5043_50430302_32_dialog_content = "ฉันไม่ได้ตั้งใจจะวิจารณ์ใคร ก็แค่... ฉันว่าฉันคงต้องลองดูเอง",
  ui_story_5043_50430302_33_dialog_content = "แต่ฉันจะหาเขาได้ที่ไหน",
  ui_story_5043_50430302_34_dialog_content = "หากเป็นเขา ก็น่าจะเป็นที่ที่พลุกพล่าน เต็มไปด้วยผู้คน",
  ui_story_5043_50430302_35_dialog_content = "โอ้. ตกลง...",
  ui_story_5043_50430302_36_dialog_content = "เมื่อพูดถึงสถานที่ที่มีผู้คนพลุกพล่าน มีตัวเลือกที่ชัดเจน",
  ui_story_5043_50430302_37_dialog_content = "สถานที่ซึ่งขุนนางและสามัญชนมาชุมนุมกัน โดยตรงภายใต้ \"ดวงจันทร์\"",
  ui_story_5043_50430302_38_dialog_content = "ว-ทำไม!?",
  ui_story_5043_50430302_39_dialog_content = "ก่อนหน้านี้ฉันได้ยินข่าวเกี่ยวกับ \"ดวงจันทร์\" มาบ้างแล้ว ฉันคิดว่าเราควรไปตรวจสอบ",
  ui_story_5043_50430302_40_dialog_content = "คุณแค่ต้องการไปดูมัน",
  ui_story_5043_50430302_41_dialog_content = "ไม่เป็นไร ฉันก็อยากรู้เหมือนกัน ไปกันเลย!",
  ui_story_5043_50430302_42_dialog_content = "ไม่นะ. รอสักครู่!",
  ui_story_5043_50430302_43_dialog_content = "อยากใส่ <color=#FFB400>ถุงมือ</color> ฉันสวมเมื่อเราพบกันครั้งแรกและจับมือกัน",
  ui_story_5043_50430302_44_dialog_content = "และฉันต้องเอาคุกกี้ที่ฉันทำไว้ให้เขาด้วย",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>สวนลุมโมโปลิส เขตที่อยู่อาศัย</color>",
  ui_story_5043_50430401_2_dialog_content = "บอลลูนลมร้อนที่ดูเหมือนดวงจันทร์ลอยอยู่รอบ ๆ ที่นั่นเป็นเวลาหลายวัน?",
  ui_story_5043_50430401_3_dialog_content = "ฉันไม่ได้สังเกตเลยด้วยซ้ำ...",
  ui_story_5043_50430401_4_dialog_content = "ฉันนึกไม่ถึงว่าจะมีอะไรอยู่บนนั้น ยกเว้นสวนลูโมโพลิสและดวงอาทิตย์",
  ui_story_5043_50430401_5_dialog_content = "เป็นเรื่องปกติที่คุณจะพลาด สามัญชนเช่นคุณไม่เคยคิดที่จะเงยหน้าขึ้นชื่นชมความงามของท้องฟ้า",
  ui_story_5043_50430401_6_dialog_content = "เฮ้ พูดอีกครั้งสิ!",
  ui_story_5043_50430401_7_dialog_content = "ตกลงตกลง. ได้โปรดเดินให้มากขึ้น ต่อสู้ให้น้อยลง",
  ui_story_5043_50430401_8_dialog_content = "ฉันจำได้ว่าตอนที่ฉันยังเด็ก แม่พาฉันไปที่ Stairway to the Skies และบอกว่านั่นเป็นที่เดียวที่เราสามารถเห็นดาวได้",
  ui_story_5043_50430401_9_dialog_content = "ในแต่ละขั้นตอน คุณจะเห็นดาวหนึ่งดวง ขึ้นทุกขั้นก็เห็นเป็นพัน",
  ui_story_5043_50430401_10_dialog_content = "ฉันตื่นเต้นมาก! ฉันวิ่งไปจนสุดทาง",
  ui_story_5043_50430401_11_dialog_content = "คุณเห็นดาวกี่ดวง?",
  ui_story_5043_50430401_12_dialog_content = "ไม่มี. เพียงแค่ดวงอาทิตย์ มันเป็นช่วงเที่ยง",
  ui_story_5043_50430401_13_dialog_content = "อย่างน้อยคุณก็รอจนถึงเย็นได้!",
  ui_story_5043_50430401_14_dialog_content = "แต่คือตอนนอน...",
  ui_story_5043_50430401_15_dialog_content = "...",
  ui_story_5043_50430401_16_dialog_content = "อีกอย่าง Matthieu คุณได้ยินอะไรเกี่ยวกับ \"ดวงจันทร์\" บ้าง?",
  ui_story_5043_50430401_17_dialog_content = "โอ้ เป็นแค่งานอีเวนต์ที่เหล่าผู้คลั่งไคล้ Mooncrown Day ปรุงแต่งขึ้นมา",
  ui_story_5043_50430401_18_dialog_content = "พวกเขาส่งบอลลูนอากาศร้อนที่มีลักษณะเหมือนดวงจันทร์ขึ้นสู่ท้องฟ้าเหนือลูโมโปลิส เพื่อประกาศการครองราชย์ของความรักอิสระ",
  ui_story_5043_50430401_19_dialog_content = "และเมื่อบอลลูนลอยขึ้น ทุกคนรู้ว่าต้องรวมตัวกันใต้บอลลูนเพื่อทำร้านเสริมสวยอย่างกะทันหัน",
  ui_story_5043_50430401_20_dialog_content = "ขุนนางที่ติดตามเทรนด์ทุกคนรักมัน",
  ui_story_5043_50430401_21_dialog_content = "ฉันเห็น. ฉันจำได้ว่าคาร์ลีนพูดบางอย่างเกี่ยวกับผู้ที่ชื่นชอบ Mooncrown Day",
  ui_story_5043_50430401_22_dialog_content = "นั่นเป็นเหตุผลที่พวกเขาใช้บอลลูนที่ดูเหมือนดวงจันทร์ ... เพราะเป็นวัน Mooncrown",
  ui_story_5043_50430401_23_dialog_content = "พวกขุนนางฉลาดแค่ไหน",
  ui_story_5043_50430401_24_dialog_content = "ฉันคิดว่ามันสมเหตุสมผลเพราะพระจันทร์และความรักต่างก็เป็นสิ่งที่บริสุทธิ์และสวยงาม",
  ui_story_5043_50430401_25_dialog_content = "ฉันแน่ใจว่านั่นคือสิ่งที่ใครก็ตามที่วางแผนงานเหล่านี้กำลังคิดอยู่",
  ui_story_5043_50430401_26_dialog_content = "มีอะไรจะบอก. สาวๆ เป็นแบบนี้หรือเปล่าเวลามีความรัก?",
  ui_story_5043_50430401_27_dialog_content = "บอกว่าไม่รัก! อะไรก็ได้ แค่หยุดแกล้งฉัน โอเค?",
  ui_story_5043_50430401_28_dialog_content = "อย่างไรก็ตาม ดูเหมือนว่าบอลลูนจะอยู่เหนือลาน Lumopolis ดังนั้นจะต้องเป็นสถานที่จัดปาร์ตี้",
  ui_story_5043_50430401_29_dialog_content = "ฮึ. ทำไมเราต้องเดินให้ไกลกว่านี้? เมื่อไหร่พวกการ์เดี้ยนจะนำเกวียนขึ้นบันไดสู่ฟากฟ้า?",
  ui_story_5043_50430401_30_dialog_content = "ไม่ใช่ทุกคนที่จะสามารถนั่งรถม้าได้",
  ui_story_5043_50430401_31_dialog_content = "Stairway to the Skies เป็นเส้นทางหลักจากลาน Lumopolis ไปยังสวน Lumopolis",
  ui_story_5043_50430401_32_dialog_content = "คุณพร้อมที่จะดำดิ่งสู่โลกของสามัญชนหรือไม่ Matthieu?",
  ui_story_5043_50430401_33_dialog_content = "จุ๊จุ๊!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>ลาน Lumopolis, Meadow Square</color>",
  ui_story_5043_50430401_35_dialog_content = "โอ้โห!",
  ui_story_5043_50430401_36_dialog_content = "ฉันไม่รู้มาก่อนว่า Lumopolis Courtyard จะมีพื้นที่สีเขียวที่สวยงามขนาดนี้ มันงดงามมาก",
  ui_story_5043_50430401_37_dialog_content = "ฉันคิดว่ามันเพิ่งสร้างในฤดูใบไม้ผลินี้ พวกเขาใช้ Luminatics เพื่อบำรุงรักษา",
  ui_story_5043_50430401_38_dialog_content = "เฮ้ ได้ยินไหม?",
  ui_story_5043_50430401_39_dialog_content = "ดูเหมือนว่าพวกเขากำลังเล่นดนตรีอยู่กลางจัตุรัสใต้บอลลูน",
  ui_story_5043_50430401_39X1_dialog_content = "ตามที่ฉันได้ยินมา ร้านเสริมสวยมีสามส่วน: การชุมนุม การเต้นรำ และช่วงชื่นชมบทกวี",
  ui_story_5043_50430401_40_dialog_content = "อืม...เพลงแดนซ์มันๆ รสชาติที่ยอมรับได้อย่างน่าประหลาดใจ",
  ui_story_5043_50430401_40X1_dialog_content = "เด็ก ๆ นี่เป็นครั้งแรกที่คุณเข้าร่วม Moonlight Salon หรือไม่?",
  ui_story_5043_50430401_40X2_dialog_content = "อย่าเพิ่งยืนเฉย! มา มา!",
  ui_story_5043_50430401_40X3_dialog_content = "เฮ้! เดี๋ยวก่อน อย่าดึงฉัน... บัดซบ ฉันทนไม่ไหวแล้ว!",
  ui_story_5043_50430401_41_dialog_content = "เรามาทันเวลาเต้นรำพอดี!",
  ui_story_5043_50430401_42_dialog_content = "มันไม่สุภาพที่จะยืนเพียงด้านเดียวโดยให้หลังพิงกำแพง เข้าร่วมกับพวกเขาและสังเกตฝูงชนในขณะที่เราทำ!",
  ui_story_5043_50430401_43_dialog_content = "B-แต่... ฉันไม่รู้อะไรเลยเกี่ยวกับการเต้นรำหรือขนบธรรมเนียมอันสูงส่ง!",
  ui_story_5043_50430401_44_dialog_content = "และฉันมีสองเท้าซ้าย",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5043_50430401_46_dialog_content = "แล้ว... ทำไมฉันถึงเต้นอยู่กับคนธรรมดา? ฉันรู้สึกไม่สบาย!",
  ui_story_5043_50430401_47_dialog_content = "คิดว่าฉันจะสนุกกับมันเหรอ?!",
  ui_story_5043_50430401_48_dialog_content = "โอ๊ย!",
  ui_story_5043_50430401_49_dialog_content = "ดูว่าคุณวางเท้าไว้ที่ไหน เจ้าโง่—อุ๊ย!",
  ui_story_5043_50430401_50_dialog_content = "คุณกำลังทำอย่างนั้นโดยเจตนา!",
  ui_story_5043_50430401_51_dialog_content = "เฮ้ ทำอะไรของเธอเนี่ย",
  ui_story_5043_50430401_52_dialog_content = "หยุดนะ! อย่าดึงผม!",
  ui_story_5043_50430401_53_dialog_content = "ฮ่าฮ่าฮ่า! พวกเขาดูเหมือนกำลังสนุก",
  ui_story_5043_50430401_54_dialog_content = "PlayerName, คุณประหม่าไหม?",
  ui_story_5043_50430401_55_dialog_content = "ไม่ ไม่ ฉันสบายดี",
  ui_story_5043_50430401_56_dialog_content = "ไปทางซ้าย ยกเท้า กลับไปทางขวา เลี้ยว...",
  ui_story_5043_50430401_57_dialog_content = "HHH-มือฉันไปโดนเธอได้ยังไง!?",
  ui_story_5043_50430401_58_dialog_content = "ไม่ต้องกังวล มันเป็นเพียงการเต้นรำที่เป็นมิตร",
  ui_story_5043_50430401_59_dialog_content = "ทำไมเราไม่ลองอีกครั้งล่ะ",
  ui_story_5043_50430401_60_dialog_content = "ตกลง. ฉันจะทำให้ดีขึ้นในครั้งนี้",
  ui_story_5043_50430401_61_dialog_content = "ฮ่าๆ เห็นไหม คุณทำได้",
  ui_story_5043_50430401_62_dialog_content = "คุณเป็นคนเรียนรู้เร็ว",
  ui_story_5043_50430401_63_dialog_content = "วุ้ย การเต้นเป็นการออกกำลังกายอย่างแท้จริง",
  ui_story_5043_50430401_64_dialog_content = "ไม่อยากทำแบบนี้อีกแล้ว...",
  ui_story_5043_50430401_65_dialog_content = "ชิ ถ้าฉันไม่ใจดี ฉันจะฟ้องคุณ",
  ui_story_5043_50430401_66_dialog_content = "ลอว์หายไปไหน?",
  ui_story_5043_50430401_67_dialog_content = "ดูเหมือนว่าฉันจะพลาดความสนุกทั้งหมด",
  ui_story_5043_50430401_68_dialog_content = "ฉันพบตัวละครที่น่าสงสัยข้างนอกก่อนหน้านี้ ไม่ใช่ผู้เข้าร่วมร้านเสริมสวยอย่างแน่นอน",
  ui_story_5043_50430401_69_dialog_content = "ฉันไปตรวจสอบและพบกับเลดี้คาร์ลีน",
  ui_story_5043_50430401_70_dialog_content = "ขอบคุณที่แสดงวิธี และตัวละครที่น่าสงสัยเหล่านั้นก็อยู่กับฉันจริงๆ",
  ui_story_5043_50430401_71_dialog_content = "ว้าว! เลดี้คาร์ลีน คุณมาด้วย!",
  ui_story_5043_50430401_72_dialog_content = "มีอะไรล่าสุด คาร์ลีน? ความคืบหน้าใด ๆ เกี่ยวกับการบุกรุกของ Eclipsite?",
