  ui_story_5043_50430401_74_dialog_content = "บัตรเดินทางทั้งหมดเป็นระเบียบ ดังนั้นพวกเขาจึงไม่สามารถแอบเข้าไปในลูโมโพลิสโดยปลอมตัวได้",
