  ui_story_5043_50430401_76_dialog_content = "ช่วงนี้มีการเคลื่อนย้ายสินค้าและทหารรับจ้างมากขึ้น เนื่องจากเทศกาลทั้งหมด",
  ui_story_5043_50430401_77_dialog_content = "ดังนั้นจึงเป็นไปได้ว่าผู้คุมไม่ได้ค้นหาการขนส่งสินค้าอย่างถูกต้อง และ Eclipsites ก็แอบเข้ามาทางนั้น",
