  ui_story_5043_50430401_84_dialog_content = "ฉันยังไม่อนุญาตการค้นหาทั้งหมด เนื่องจากฉันไม่ต้องการสร้างความตื่นตระหนก",
  ui_story_5043_50430401_85_dialog_content = "ฉันเพิ่งให้ยามสวมเสื้อผ้าธรรมดาและบอกให้พวกเขาคอยดูพื้นที่ที่มีคนพลุกพล่านเผื่อไว้",
  ui_story_5043_50430401_86_dialog_content = "คุณรู้ไหม คาร์ลีน ฟังดูคล้ายกับสิ่งที่ City Lord ทำกับคดี Mooncrown Day",
