  ui_story_5043_50430401_137_dialog_content = "ฉันไม่แน่ใจว่าเนื้อเพลงของพวกเขามีเหตุผลมากแค่ไหน แต่พวกเขาเป็นนักร้องที่ดี...",
  ui_story_5043_50430401_138_dialog_content = "การฟังเพลงประสานเสียงทำให้ฉันอยากอธิษฐานอยู่เสมอ",
  ui_story_5043_50430401_139_dialog_content = "White Night up high, โอ้ เทพแห่งแสง โปรดให้ข้าพบเขา",
  ui_story_5043_50430401_140_dialog_content = "ฉันไม่แน่ใจว่า God of Light เป็นผู้รับผิดชอบเรื่องดังกล่าวทั้งหมด...",
  ui_story_5043_50430401_141_dialog_content = "ทุกคนใน Lumopolis สามารถสรรเสริญเทพเจ้าแห่งแสงได้ ♪",
  ui_story_5043_50430401_142_dialog_content = "แต่ขุนนางแต่งงานกับสามัญชน? ไม่ถูกต้อง! ♪",
  ui_story_5043_50430401_143_dialog_content = "โอ้ แม่ชีผู้มีเกียรติ แม่ชีผู้น่าสงสาร! ♪",
  ui_story_5043_50430401_144_dialog_content = "ภัยพิบัติกำลังจะมา คุณ! ควร! วิ่ง! ♪",
  ui_story_5043_50430401_145_dialog_content = "รออะไร?!",
  ui_story_5043_50430401_146_dialog_content = "เคลียร์พื้นที่! ฉันต้องการให้ทุกคนที่เข้าร่วมการชุมนุมที่ผิดกฎหมายนี้ถูกจับกุม",
  ui_story_5043_50430401_147_dialog_content = "และนำออแกไนเซอร์มาให้ฉัน!",
  ui_story_5043_50430401_148_dialog_content = "เอ๋!",
  ui_story_5043_50430401_149_dialog_content = "ผู้พิทักษ์จากสวนลุมโปลิส! วิ่ง!",
  ui_story_5043_50430401_150_dialog_content = "II'ma ขุนนางจากอัพทาวน์ พวกเขาคงไม่กล้า...",
  ui_story_5043_50430401_151_dialog_content = "หวาาา!?",
  ui_story_5043_50430401_152_dialog_content = "อา! ของฉัน <color=#FFB400>คุ้กกี้</color>!",
  ui_story_5043_50430401_153_dialog_content = "ฉัน <color=#FFB400>สูญหาย</color> คุกกี้ที่ฉันกำลังจะให้เขา!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5043_50430401_155_dialog_content = "(เป็นไปไม่ได้ นี่ไม่ใช่องครักษ์ของฉัน!)",
  ui_story_5043_50430401_156_dialog_content = "ฉันไม่มีคำสั่งเช่นนั้น! ใครกล้า...",
  ui_story_5043_50430401_157_dialog_content = "กัปตันคาร์ลีน!",
  ui_story_5043_50430401_158_dialog_content = "พวกเขาไม่ใช่ผู้พิทักษ์จากสวนลุมโปลิส",
  ui_story_5043_50430401_159_dialog_content = "แต่มีขุนนางเพียงไม่กี่คนเท่านั้นที่มีกองกำลังดังกล่าว",
  ui_story_5043_50430401_160_dialog_content = "ผู้เข้าร่วมปาร์ตี้จะถือว่าการโจมตีครั้งนี้ได้รับคำสั่งจากสวนลุมโปลิส!",
  ui_story_5043_50430401_161_dialog_content = "ฉันเห็นสิ่งที่คุณพูด แต่เราต้องเรียกคืนคำสั่งซื้อก่อน",
  ui_story_5043_50430401_162_dialog_content = "กรุณาอย่าตกใจ ปฏิบัติตามฉัน!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>ทุบ—!</color>",
  ui_story_5043_50430401_164_dialog_content = "(เสียงอะไรเนี่ย!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerNameWhirling Paladin ฉันต้องการความช่วยเหลือจากคุณ",
  ui_story_5043_50430401_166_dialog_content = "เข้าร่วมกองกำลังกับทหารยามธรรมดาของฉันและจัดการกับทหารเหล่านี้ ไม่ว่าพวกเขาจะเป็นใคร!",
  ui_story_5043_50430401_167_dialog_content = "ยินดีที่ได้ช่วย!",
  ui_story_5043_50430401_168_dialog_content = "ตามที่ขอ!",
  ui_story_5043_50430501_1_dialog_content = "ยามพวกนั้นวิ่งเร็วแน่!",
  ui_story_5043_50430501_2_dialog_content = "กัปตัน ฉันควรจะไล่ตามไหม?",
  ui_story_5043_50430501_3_dialog_content = "อย่ารำคาญ คุณมีงานอื่นที่ต้องทำ",
  ui_story_5043_50430501_4_dialog_content = "น่าเสียดายแม้ว่า Moonlight Salon ถูกทำลายและเราไม่พบคนที่เรากำลังมองหา",
  ui_story_5043_50430501_5_dialog_content = "โอ้? คุณกำลังมองหาใคร",
  ui_story_5043_50430501_6_dialog_content = "ทีน่าต้องการตามหาชวาบและมอบบางสิ่งตอบแทนสำหรับของขวัญวันไหว้พระจันทร์",
  ui_story_5043_50430501_7_dialog_content = "โอ้ ฉันไม่รู้ว่าทั้งสองคนมีความสัมพันธ์แบบนี้",
  ui_story_5043_50430501_8_dialog_content = "นั่นคือพลังของ Mooncrown Day หนุ่มสาวตกหลุมรักโดยที่ครอบครัวไม่ได้เตรียมการล่วงหน้า",
  ui_story_5043_50430501_9_dialog_content = "แต่... ถ้าพูดตรงๆ เธอเห็นอะไรในตัวเพลย์บอยคนนั้น?",
  ui_story_5043_50430501_10_dialog_content = "รู้แล้วใช่ไหม...?",
  ui_story_5043_50430501_11_dialog_content = "เฮ้ มีใครเห็น Loewe บ้างไหม?",
  ui_story_5043_50430501_12_dialog_content = "ฉันไม่เห็นเขาเลยตั้งแต่ยามพวกนั้นหนีไป",
  ui_story_5043_50430501_13_dialog_content = "ฉันส่งเขาออกไปเพื่อค้นหาว่าพวกเขามาจากไหน คุณควรดำเนินการสืบสวนคดีของคุณต่อไป",
  ui_story_5043_50430501_14_dialog_content = "ฉันมีความคิดที่ดีมากเกี่ยวกับสิ่งที่เกิดขึ้นแล้ว แต่ทางที่ดีควรตรวจสอบให้แน่ใจ",
  ui_story_5043_50430501_15_dialog_content = "T-นี้ไม่ดี.",
  ui_story_5043_50430501_16_dialog_content = "ฉันรู้ว่าฉันรู้ว่า. คุกกี้ของคุณหายไปใช่ไหม?",
  ui_story_5043_50430501_17_dialog_content = "ลองมองหาพวกเขา พวกเขาคงคลุกคลีอยู่กับความยุ่งเหยิงเหล่านี้",
  ui_story_5043_50430501_18_dialog_content = "โอ้ ฉันหวังว่านั่นจะเป็นปัญหาเดียว!",
  ui_story_5043_50430501_19_dialog_content = "เป็นรูปปั้นตรงทางเข้าจัตุรัส ของมัน...",
  ui_story_5043_50430501_20_dialog_content = "มันได้รับ <color=#FFB400>แตกหัก</color> ท่ามกลางความวุ่นวายทั้งปวง",
  ui_story_5043_50430501_21_dialog_content = "ว่าไงนะ!?",
  ui_story_5043_50430501_22_dialog_content = "ฉันได้ยินเสียงบางอย่างแตกในขณะที่ทุกคนกำลังเร่งรีบ",
  ui_story_5043_50430501_23_dialog_content = "สิ่งที่แปลกคือ มันพังแบบเดียวกับที่ Hall of Justice ทำ",
  ui_story_5043_50430501_24_dialog_content = "มันเหมือนกับว่ามีรูปปั้นหัวขาดในที่ทำงาน",
  ui_story_5043_50430501_25_dialog_content = "อืม... ฉันคิดว่าเราควรไปรายงานหัวหน้าผู้พิพากษาชั่วคราวของเรา",
  ui_story_5043_50430501_26_dialog_content = "ใช่. และถ้าเขาไม่ได้อยู่ที่นี่ที่ Moonlight Salon เขาก็ต้อง—",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>สวนลุมโมโพลิส สำนักงานชวาบ</color>",
  ui_story_5043_50430501_28_dialog_content = "อืม... โอเค เข้าใจแล้ว",
  ui_story_5043_50430501_29_dialog_content = "ฉันดีใจที่คุณกลับมา ฉันต้องการให้คุณเก็บรูปปั้นไว้ชั่วคราว จนกว่าโจทก์จะปรับปรุงคำขอของพวกเขา",
  ui_story_5043_50430501_30_dialog_content = "เรามีคดีรักครั้งใหม่กำลังจะเริ่มขึ้น เตรียมตัวให้พร้อม ผู้ใต้บังคับบัญชาที่รักของฉัน",
  ui_story_5043_50430501_31_dialog_content = "แค่นั้นเองเหรอ?",
  ui_story_5043_50430501_32_dialog_content = "นี่คือชีวิตในแผนกโรมานซ์ เคลื่อนที่ไปข้างหน้าอย่างต่อเนื่อง เหมือนกับรถม้าที่ขับเคลื่อนด้วยแสง",
  ui_story_5043_50430501_33_dialog_content = "มันยากสำหรับคุณที่จะเข้าใจ ดอกแดนดิไลอันน้อยของฉัน เนื่องจากคุณไม่ใช่หัวหน้าผู้พิพากษา",
  ui_story_5043_50430501_34_dialog_content = "L-ดอกแดนดิไลอันน้อย???",
  ui_story_5043_50430501_35_dialog_content = "(เขาเรียกฉันว่าดอกแดนดิไลอันน้อยเหรอ? น่ารังเกียจจริงๆ)",
  ui_story_5043_50430501_36_dialog_content = "คุณจะชินกับมัน PlayerName...",
  ui_story_5043_50430501_37_dialog_content = "จริงๆ แล้ว หัวหน้าผู้พิพากษาชวาบ ทีน่ามีบางอย่างที่เธอต้องการ—",
  ui_story_5043_50430501_38_dialog_content = "ฉันไม่แน่ใจว่านี่เป็นเวลาที่ดีที่สุดสำหรับสิ่งนั้น",
  ui_story_5043_50430501_39_dialog_content = "(ใช่ เลย์กำลังทำอะไรอยู่ ฉันไม่มีอะไรจะพูดกับชวาบ)",
  ui_story_5043_50430501_40_dialog_content = "อืม? ดูเหมือนว่าลูกน้องของฉันจะทำงานร่วมกันได้ดีจนพวกเขามีความลับกับฉันเล็กน้อย",
  ui_story_5043_50430501_41_dialog_content = "อย่างไรก็ตาม นี่คือคำฟ้องและเอกสารทั้งหมด ทุกอย่างตรงไปตรงมามาก เจอกันที่ศาล!",
  ui_story_5043_50430501_42_dialog_content = "เขาพูดถูก มันดูง่าย และเกี่ยวข้องกับร้านแสงจันทร์ที่เราอยู่ที่...",
  ui_story_5043_50430501_43_dialog_content = "ฮะ? รอสักครู่! ทุกคนดูเหตุผลของคดีสิ!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>ศาลาว่าการ แผนกโรมานซ์</color>",
  ui_story_5043_50430501_45_dialog_content = "City Lord ไม่ทำสิ่งต่าง ๆ ทีละครึ่ง ดูขนาดของสถานที่นี้สิ!",
  ui_story_5043_50430501_46_dialog_content = "และด้วยจำนวนเคสที่เราจัดการในวันแรก เขายังได้รับความคุ้มค่าอีกด้วย",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5043_50430501_48_dialog_content = "ศาลอยู่ในเซสชั่น!",
  ui_story_5043_50430501_49_dialog_content = "อันดับแรก ให้เราแนะนำบุคคลที่เกี่ยวข้องในการดำเนินคดีในวันนี้!",
  ui_story_5043_50430501_50_dialog_content = "โจทก์คือ... ชายจากลูโมโพลิสตอนล่าง ซึ่งไม่สามารถระบุชื่อได้ด้วยเหตุผลด้านความเป็นส่วนตัว",
  ui_story_5043_50430501_51_dialog_content = "จำเลยคือ... ผู้หญิงจากลูโมโพลิสตอนล่าง ซึ่งไม่สามารถระบุชื่อได้ด้วยเหตุผลด้านความเป็นส่วนตัว",
  ui_story_5043_50430501_52_dialog_content = "(ฉันไม่ได้ยินอะไรเลย!)",
  ui_story_5043_50430501_53_dialog_content = "ฉัน Schwab Salar จะเป็นประธานในการพิจารณาคดีในวันนี้",
  ui_story_5043_50430501_54_dialog_content = "คณะพิจารณาคดีประกอบด้วย Matthieu Sawyer, Tina Campbell และ Leyn...",
  ui_story_5043_50430501_55_dialog_content = "ตลอดจนสมาชิกศาลอีกหลายคน",
  ui_story_5043_50430501_56_dialog_content = "(ว้าว! Schwab ดูเหมือนจะมีความสามารถจริง ๆ เมื่อเขาใส่ใจกับมัน ... )",
  ui_story_5043_50430501_57_dialog_content = "หากไม่มีใครคัดค้านใดๆ เราสามารถดำเนินการต่อไปได้",
  ui_story_5043_50430501_58_dialog_content = "รอก่อน. ทำไมเราทุกคนเป็นเพียง \"สมาชิกคนอื่น ๆ ในศาล\"?",
  ui_story_5043_50430501_59_dialog_content = "ไม่มีการคัดค้าน? ดีมาก เรามาเริ่มกันเลย",
  ui_story_5043_50430501_60_dialog_content = "หากโจทก์สามารถเล่าข้อเท็จจริงในคดีให้เราฟังได้?",
  ui_story_5043_50430501_61_dialog_content = "*สะอื้น* นี่คือสิ่งที่เกิดขึ้น...",
  ui_story_5043_50430501_62_dialog_content = "คู่หมั้นของฉัน - จำเลย - และฉันไปที่ Meadow Square ใน Lumopolis Courtyard เพื่อไปที่ Moonlight Salon...",
  ui_story_5043_50430501_63_dialog_content = "ข-แต่เธอ...",
  ui_story_5043_50430501_64_dialog_content = "โปรดอย่าร้องไห้ เพียงแค่บอกเราว่าเกิดอะไรขึ้น",
  ui_story_5043_50430501_65_dialog_content = "ฉันรักเธอมาก เราอยู่ด้วยกันมาสี่ปีแล้ว! เธอชอบดื่มกาแฟกับช็อกโกแลตและ—",
  ui_story_5043_50430501_66_dialog_content = "หากคุณสามารถยึดติดกับเรื่องที่เกี่ยวข้องได้โปรด",
  ui_story_5043_50430501_67_dialog_content = "S-ขอโทษ โอ้ ฉันมักทำให้ทุกอย่างยุ่งเหยิงเสมอ...",
  ui_story_5043_50430501_68_dialog_content = "เราไปที่ร้าน Moonlight Salon และมีช่วงเวลาที่ดี แต่ทันใดนั้นเธอก็โกรธและบอกว่าเธอต้องการเลิกกับฉัน!",
  ui_story_5043_50430501_69_dialog_content = "ฉันหมายถึง... ฉันจะบอกครอบครัวว่าอย่างไร? *ที่ร้องไห้*",
  ui_story_5043_50430501_70_dialog_content = "ดีมาก. ต่อไปจำเลย.",
  ui_story_5043_50430501_71_dialog_content = "ฉันมีเหตุผลของฉัน",
  ui_story_5043_50430501_72_dialog_content = "โจทก์คนนี้พาฉันออกเดท",
  ui_story_5043_50430501_73_dialog_content = "ยังกล้ารับของขวัญจากคนอื่น!",
  ui_story_5043_50430501_74_dialog_content = "(เธอทำเหมือนว่าเธอเป็นโจทก์)",
  ui_story_5043_50430501_75_dialog_content = "ฉันไม่ได้...",
  ui_story_5043_50430501_76_dialog_content = "แล้วคุณช่วยอธิบายได้ไหมว่าตะกร้านั้นอยู่ที่ไหน <color=#FFB400>คุ้กกี้</color> มาจาก?",
  ui_story_5043_50430501_77_dialog_content = "(คุ้กกี้เหรอนั่น...)",
  ui_story_5043_50430501_78_dialog_content = "ที่นั่น! นั่นคือหลักฐาน!",
  ui_story_5043_50430501_79_dialog_content = "คุณวางไว้บนเก้าอี้ของคุณ และมีการ์ด",
  ui_story_5043_50430501_80_dialog_content = "และมันแย่ลงไปอีก ใครเขียนการ์ดก็ใช้เหมือนกัน <color=#FFB400>ชื่อสัตว์เลี้ยง</color> สำหรับคุณที่ฉันทำ!",
  ui_story_5043_50430501_81_dialog_content = "โอ้ฉันเสร็จแล้วสำหรับ",
  ui_story_5043_50430501_82_dialog_content = "เราพูดถูก สองคนนี้พบคุกกี้ที่ทีน่าทำหาย",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>ตุ๊ด ตุ๊ด ตุ๊ด ตุ๊ด!</color>",
  ui_story_5043_50430501_84_dialog_content = "คำสั่ง!",
  ui_story_5043_50430501_85_dialog_content = "พลเมืองของ Lumopolis ที่ถูกพบว่าละเมิดอำนาจศาลจะถูกตัดสินประหารชีวิต... ล้อเล่น!",
  ui_story_5043_50430501_86_dialog_content = "<size=32>เฮ้ ทีน่า นั่นคือตะกร้าคุกกี้ที่คุณทำหายใช่ไหม</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>เอ๊ะ? คือว่า PlayerName?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>คุณคุยกับฉันไม่ได้ตอนขึ้นศาล!</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>ในกรณีนั้น...</size>",
  ui_story_5043_50430501_90_option_content = "บูสต์พลัง!",
  ui_story_5043_50430501_91_dialog_content = "โอ้ว้าว! นี่เป็นความสามารถของ Caelesite ของคุณหรือไม่? ฉันเคยสงสัยเกี่ยวกับมัน",
  ui_story_5043_50430501_92_dialog_content = "ไม่เป็นไรตอนนี้ นั่นคือคุกกี้ของคุณใช่ไหม",
  ui_story_5043_50430501_93_dialog_content = "ใช่ พวกเขาเป็นของฉัน! ฉันไม่อยากเชื่อเลยว่าฉันสร้างปัญหาให้กับผู้บริสุทธิ์เหล่านี้มาก...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName, คุณคิดว่าฉันควรทำอย่างไร?",
  ui_story_5043_50430501_95_option_content = "ซื่อสัตย์",
  ui_story_5043_50430501_96_dialog_content = "ฉันคิดว่าคุณควรยอมรับสิ่งที่เกิดขึ้น คุกกี้เป็นของคุณแต่ตั้งใจมอบให้คนอื่น",
  ui_story_5043_50430501_97_dialog_content = "แต่ฉันเดาว่านี่ไม่ใช่เวลาที่ดีที่สุดสำหรับ Schwab ที่จะได้ยินความจริง",
  ui_story_5043_50430501_98_dialog_content = "ดังนั้นฉันจะเข้าใจถ้าคุณไม่กระตือรือร้นกับแนวคิดนี้มากเกินไป",
  ui_story_5043_50430501_99_dialog_content = "ฮะ? ชวาบ? ฟังความจริงอะไร?",
  ui_story_5043_50430501_100_option_content = "รอดู",
  ui_story_5043_50430501_101_dialog_content = "ฉันคิดว่าคุณควรรอดูว่าจะเกิดอะไรขึ้น",
  ui_story_5043_50430501_102_dialog_content = "หากคุณเริ่มพูดตอนนี้ คุณจะเสี่ยงต่อการถูกดูหมิ่นศาล",
  ui_story_5043_50430501_103_dialog_content = "แล้วศาลจะทำอย่างไรต่อไป?",
  ui_story_5043_50430501_104_dialog_content = "ต่อไปเราจะได้ยินข้อโต้แย้งจากทั้งสองฝ่าย",
  ui_story_5043_50430501_105_dialog_content = "ฉันไม่แน่ใจว่าทำไม PlayerName สนใจมาก แต่ฉันจะปล่อยให้ Schwab ทำคดีต่อไป",
  ui_story_5043_50430501_106_dialog_content = "เนื่องจากทั้งโจทก์และจำเลยดูเหมือนจะกระตือรือร้นที่จะดำเนินการต่อ ตอนนี้เราจะรับฟังข้อโต้แย้งเพิ่มเติม",
  ui_story_5043_50430501_107_dialog_content = "<size=32>ฟังนะ คนธรรมดา! นี่ไม่ใช่วิธีที่จะทำสิ่งต่างๆ</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>เราต้องทำอะไรบางอย่าง แต่เราไม่สามารถทำให้ทีน่าอับอายได้</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>ฉันเห็นด้วย. แต่เราไม่รู้ว่าทีน่าต้องการทำอะไร</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>เธอไม่ได้พูดเพื่อตัวเอง แล้ว... ถ้าเราช่วย Schwab คิดออกเองล่ะ?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>ไม่เลวนะลูก! ความคิดที่ดี.</size>",
  ui_story_5043_50430501_112_dialog_content = "ตอนนี้ผู้พิพากษาจะกรุณาเริ่มด้วยการถามค้าน",
  ui_story_5043_50430501_113_dialog_content = "อะแฮ่ม. โจทก์ คุณบอกว่าตะกร้าคุกกี้นี้ไม่ใช่ของคุณ ช่วยบอกเราทีว่ามันเป็นของใคร?",
  ui_story_5043_50430501_114_dialog_content = "ฉัน... ฉันไม่รู้ ทันใดนั้นมันก็ปรากฏขึ้นบนโต๊ะต่อหน้าฉัน",
  ui_story_5043_50430501_115_dialog_content = "ฉันสามารถสันนิษฐานได้เท่านั้น <color=#FFB400>มีคนทิ้งไว้ที่นั่น</color>.",
  ui_story_5043_50430501_116_dialog_content = "จะบอกว่าคนที่เข้าร่วม Moonlight Salon ทำตะกร้าคุกกี้หายงั้นเหรอ?",
  ui_story_5043_50430501_117_dialog_content = "และฉันแน่ใจว่าเราทุกคนสามารถจินตนาการได้ว่ามีไว้เพื่ออะไร",
  ui_story_5043_50430501_118_dialog_content = "ใช่. ฉันหมายความว่ามันต้องมีจุดประสงค์เป็น <color=#FFB400>ของขวัญ</color>.",
  ui_story_5043_50430501_119_dialog_content = "แต่ไม่ใช่ของขวัญสำหรับฉัน ฉันไม่มีส่วนเกี่ยวข้องกับมัน",
  ui_story_5043_50430501_120_dialog_content = "ข้าพเจ้าอยากถามจำเลยว่าเหตุใดท่านจึงแน่ใจนักว่าคนรักของท่านถูกหลอก?",
  ui_story_5043_50430501_121_dialog_content = "แน่นอนมันชัดเจน ใครๆ ก็เห็นว่าตระกร้าคุกกี้เป็นของขวัญจาก <color=#FFB400>ผู้หญิง</color>.",
  ui_story_5043_50430501_122_dialog_content = "เขาคงไม่กล้ารับของขวัญแบบนี้ นอกเสียจากว่าเขามีแผนจะเลิกกับฉัน",
  ui_story_5043_50430501_123_dialog_content = "และนี่คือหัวใจของเรื่อง โจทก์ยืนยันว่าเขาไม่ยอมรับของขวัญใด ๆ คุณเชื่อว่าเขาทำ",
  ui_story_5043_50430501_124_dialog_content = "แต่ข้อความบน <color=#FFB400>การ์ด</color> ชัดเจนจากคนรัก...",
  ui_story_5043_50430501_125_dialog_content = "ตกลง. บางทีฉันอาจจะรีบร้อนเกินไป แต่คุกกี้มีไว้เพื่อใคร?",
  ui_story_5043_50430501_126_dialog_content = "นั่นคือคำถามสำคัญ!",
  ui_story_5043_50430501_127_dialog_content = "และผู้รับที่ต้องการอยู่ที่นี่!",
  ui_story_5043_50430501_128_dialog_content = "ที่นี่...?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>ตุ๊ด ตุ๊ด ตุ๊ด ตุ๊ด!</color>",
  ui_story_5043_50430501_130_dialog_content = "ผู้พิพากษาเลย์น ผู้พิพากษามาติเยอ โปรดอย่ากล่าวถ้อยคำที่เป็นการชี้นำต่อจำเลย",
  ui_story_5043_50430501_131_dialog_content = "นี่คือศาล Guilty ความหมายคือ มีความผิด",
  ui_story_5043_50430501_132_dialog_content = "โอ้ แต่หัวหน้าผู้พิพากษา Schwab... คุณหล่อมาก เป็นที่นิยมในหมู่สาวๆ เจ้าจะทนขัดจังหวะสาวใช้ผู้งดงามเช่นนี้ได้อย่างไร?",
  ui_story_5043_50430501_133_dialog_content = "และหลักฐานความรักของผู้หญิงที่มีต่อคุณอยู่ที่นี่ แต่คุณกลับไม่รู้ว่าผู้หญิงคนนั้นเป็นใคร",
  ui_story_5043_50430501_134_dialog_content = "โอ้! ฉันคิดว่าฉันเข้าใจ. คุณหมายความว่าจริงๆ แล้ว คุกกี้มีไว้สำหรับ—",
  ui_story_5043_50430501_135_dialog_content = "หา?",
  ui_story_5043_50430501_136_dialog_content = "คำสั่ง!",
  ui_story_5043_50430501_137_dialog_content = "ศาลเงียบ! ฉันต้องการที่จะพูด",
  ui_story_5043_50430501_138_dialog_content = "ผู้พิพากษาทีน่า คุณไม่สามารถขัดขวางธุรกิจของศาลแบบนี้ได้!",
  ui_story_5043_50430501_139_dialog_content = "หัวหน้าผู้พิพากษาชวาบ ในฐานะเจ้าของคุกกี้หลักฐาน ฉันต้องการจะทำ <color=#FFB400>คำให้การของพยาน</color>.",
  ui_story_5043_50430501_140_dialog_content = "(Attagirl, Tina! นั่นคือวิญญาณ!)",
  ui_story_5043_50430501_141_dialog_content = "โอเค ศาลเห็นด้วย คุณอาจพูดเป็นพยาน",
  ui_story_5043_50430501_142_dialog_content = "ฉันทำคุกกี้",
  ui_story_5043_50430501_143_dialog_content = "ฉันทำมันเองด้วยมือที่เปี่ยมด้วยความรักและหัวใจที่กระพือปีก",
  ui_story_5043_50430501_144_dialog_content = "ฉันตีเนย ฉันวางท่อการออกแบบที่สวยงาม ฉันอบมันจนเป็นสีเหลืองทองและเลือกอันที่ดูดีที่สุดออกมา",
  ui_story_5043_50430501_145_dialog_content = "ทั้งหมดก็เพื่อที่ฉันจะได้ให้ของขวัญที่สมบูรณ์แบบแก่เขา",
  ui_story_5043_50430501_146_dialog_content = "แต่แล้วฉันก็ทำมันหายทั้งหมดที่ร้านแสงจันทร์",
  ui_story_5043_50430501_147_dialog_content = "และการ์ดใบนี้เป็นหลักฐาน!",
  ui_story_5043_50430501_148_dialog_content = "ฉันทำการ์ดนั้นด้วยตัวเอง ฉันสามารถบอกคุณได้ว่าชื่อบนการ์ดและทุกสิ่งที่เขียนบนการ์ด",
  ui_story_5043_50430501_149_dialog_content = "โอ้! จริงหรือ แปลกมากที่เจอแบบนี้...",
  ui_story_5043_50430501_150_dialog_content = "มันเหมือนกับเรื่องราวความรักที่สวยงาม",
  ui_story_5043_50430501_151_dialog_content = "ฉันไม่รู้จะทำอย่างไรกับคุณ ที่รักของฉัน คุณช่างเป็นภาระอันน่าหลงใหลสำหรับฉันที่ต้องแบกรับ",
  ui_story_5043_50430501_152_dialog_content = "บางทีพยานและจำเลยสามารถยืนยันสิ่งที่เขียนบนบัตร? จากนั้นเราจะสามารถสรุปกรณีนี้ได้",
  ui_story_5043_50430501_153_dialog_content = "ตกลง. ลองอ่านกันดูนะครับ",
  ui_story_5043_50430501_154_dialog_content = "ความคิดที่ดี. สาม. สอง. หนึ่ง!",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>โตโต้</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "ฮา?",
  ui_story_5043_50430501_156_dialog_content = "ว่าไงนะ!?",
  ui_story_5043_50430501_157_dialog_content = "ทำไม หัวหน้าผู้พิพากษาชวาบ ฉันได้ยินมาตลอดว่าคุณมีชื่อเสียงและทันสมัยแค่ไหน",
  ui_story_5043_50430501_158_dialog_content = "ฉันไม่เคยคิดเลยว่าคุณจะมีชื่อเล่นเล็กๆ น่ารักๆ แบบนี้",
  ui_story_5043_50430501_159_dialog_content = "มันทำให้คุณดูน่ากลัวน้อยลงสำหรับพวกเราชาวลูโมโพลิสตอนล่าง",
  ui_story_5043_50430501_160_dialog_content = "ที่รัก ในที่สุดฉันก็ได้รับความไว้วางใจของคุณคืนมา *ที่ร้องไห้*",
  ui_story_5043_50430501_161_dialog_content = "โตโต้. ฮิฮิ. ชื่อน่ารักจัง",
  ui_story_5043_50430501_162_dialog_content = "Schwab นั่นคือชื่อเล่นในวัยเด็กหรือไม่? แม่ของคุณเรียกคุณว่าอะไร",
  ui_story_5043_50430501_163_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า",
  ui_story_5043_50430501_164_dialog_content = "แต่นี่...",
  ui_story_5043_50430501_165_dialog_content = "หยุด! เกิดอะไรขึ้นกันแน่!?",
  ui_story_5043_50430501_166_dialog_content = "ใช่เกิดอะไรขึ้น?",
  ui_story_5043_50430501_167_dialog_content = "การ์ดและคุกกี้เกี่ยวข้องอะไรกับหัวหน้าผู้พิพากษา Schwab?",
  ui_story_5043_50430601_1_dialog_content = "ดังนั้น... ฉันเดาว่านั่นคือสิ่งที่เกิดขึ้น",
  ui_story_5043_50430601_2_dialog_content = "ฉันทำคุกกี้ให้โตโต้ แต่ดูเหมือนจำเลยจะเข้าใจผิด...",
  ui_story_5043_50430601_3_dialog_content = "ฉันไม่เคยคิดเลยว่าเรื่องแบบนี้จะเกิดขึ้น อย่างน้อยเราก็ได้เคลียร์ความเข้าใจผิดระหว่างคู่รักทั้งสอง",
  ui_story_5043_50430601_4_dialog_content = "ฮา?",
  ui_story_5043_50430601_5_dialog_content = "ไม่ใช่พวกเขาคนเดียวที่เข้าใจผิด",
  ui_story_5043_50430601_6_dialog_content = "แล้วโตโต้นี่ใคร? เราคิดว่าคุณชอบหัวหน้าผู้พิพากษางี่เง่าของเรา!",
  ui_story_5043_50430601_7_dialog_content = "ใช่ แม้ว่านั่นจะไม่สมเหตุสมผลเลยก็ตาม แต่เราผิดตรงไหน?",
  ui_story_5043_50430601_8_dialog_content = "มันเป็นความผิดของฉัน มันเป็นสถานการณ์ที่น่าอาย ดังนั้นฉันจึงคลุมเครือมาก",
  ui_story_5043_50430601_9_dialog_content = "ฉันควรจะอธิบายสิ่งต่าง ๆ ให้ดีกว่านี้ก่อนที่จะขอให้คุณช่วย",
  ui_story_5043_50430601_10_dialog_content = "แม้ว่าฉันไม่เข้าใจว่าคุณเข้าใจผิดได้อย่างไร Schwab",
  ui_story_5043_50430601_11_dialog_content = "เราแทบไม่ได้คุยกันเลยนอกจากเรื่องงานและโซเชียลทั่วไป",
  ui_story_5043_50430601_12_dialog_content = "ฉันหมายความว่ามันชัดเจนเมื่อมีคนชอบคุณใช่ไหม นั่นเป็นเพียงสิ่งที่ผู้คนสามารถบอกได้",
  ui_story_5043_50430601_13_dialog_content = "เพียงพอ. กรุณาอย่าพูดอะไรอีก",
  ui_story_5043_50430601_14_dialog_content = "ทั้งหมดนี้...ไม่เกี่ยว เรื่องสำคัญอยู่ที่...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>ทุกคนใน Hall of Justice คิดว่าชื่อเล่นของฉันคือ Toto!!!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>Jr. Jr. และเหล่าผู้ช่วยกรรมการบนแผงต้องบอกทุกคนอยู่แล้ว!!!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>และในไม่ช้าขุนนางทุกคนในสังคมสวนลุมโปลิสจะได้ทราบข่าว!!!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>และทั้งหมดก็เป็นเพราะเธอและคุกกี้โง่ๆ และการ์ดโง่ๆ นั่น!!!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>คุณเป็นพวกปัญญาอ่อนที่รักใคร่! และเกาะติดผู้หญิงลำบาก...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>คุณเหมือนกันหมด!</size>",
  ui_story_5043_50430601_21_dialog_content = "ฉันเสียใจมาก!",
  ui_story_5043_50430601_22_dialog_content = "เฮ้. ทีน่าอาจทำผิดพลาด แต่คุณรุนแรงกับเธอเกินไป ชวาบ",
  ui_story_5043_50430601_23_dialog_content = "ฉันไม่แน่ใจว่าเกิดอะไรขึ้น ฉันโล่งใจทีน่าไม่ได้สนใจชวาบ",
  ui_story_5043_50430601_24_dialog_content = "...",
  ui_story_5043_50430601_25_dialog_content = "เฮ้อ...",
  ui_story_5043_50430601_26_dialog_content = "เอาล่ะ กลับไปทำธุรกิจกันเถอะ",
  ui_story_5043_50430601_27_dialog_content = "รูปปั้นหักที่ Lumopolis Courtyard ไม่เกี่ยวอะไรกับมิสเตอร์ไบรอน",
  ui_story_5043_50430601_28_dialog_content = "ซึ่งเป็นโชคดีสำหรับคุณ ฉันไม่อยากเห็นเขาปรากฎตัวด้วยข้อกล่าวหาใหม่ๆ",
  ui_story_5043_50430601_29_dialog_content = "ตอนนี้ไปและเตรียมพร้อมสำหรับการพิจารณาคดี ออกไป!",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>ด้านนอก Hall of Justice สวน Lumopolis</color>",
  ui_story_5043_50430601_31_dialog_content = "อุ๊บ! หุหุ",
  ui_story_5043_50430601_32_dialog_content = "เฮ้ คุณสังเกตเห็นการแสดงออกของ Schwab มากไหม?",
  ui_story_5043_50430601_33_dialog_content = "คุณเยี่ยมมาก ทีน่า สุดเหี้ยม!",
  ui_story_5043_50430601_34_dialog_content = "หึหึ ฉันพนันได้เลยว่าเขาไม่เคยมีผู้หญิงคนไหนพูดกับเขาแบบนี้มาก่อน",
  ui_story_5043_50430601_35_dialog_content = "โอ้ ได้โปรดอย่าแกล้งฉัน...",
  ui_story_5043_50430601_36_dialog_content = "ฉันเสียใจ. ฉันทำให้เราทุกคนมีปัญหา",
  ui_story_5043_50430601_37_dialog_content = "นั่นไม่สำคัญ แต่ที่ฉันอยากรู้ก็คือ—",
  ui_story_5043_50430601_38_dialog_content = "ทีน่า คุณบอกเราว่าพบชายคนนี้ในสวนที่คฤหาสน์ชวาบ?",
  ui_story_5043_50430601_39_dialog_content = "ถ้าไม่ใช่ Schwab แล้วใครล่ะ?",
  ui_story_5043_50430601_40_dialog_content = "โอ้ ความเข้าใจผิดอย่างมหันต์นี้เป็นความผิดของฉันทั้งหมด",
  ui_story_5043_50430601_41_dialog_content = "ลองอธิบายให้ถูกนะครับ...",
  ui_story_5043_50430601_42_dialog_content = "ฉันอยู่ในสวนที่ Salar Manor และฉันก็บังเอิญเจอชวาบ เขานั่งอยู่คนเดียว อ่านหนังสือและดื่มชา",
  ui_story_5043_50430601_43_dialog_content = "เขาสังเกตเห็นฉันทันทีและแปลกใจที่ไม่มีใครมาพบฉันในที่เปลี่ยวเช่นนี้",
  ui_story_5043_50430601_44_dialog_content = "แต่ในขณะที่เขาสังเกตเห็นฉัน เขากลับไม่เห็นว่ามีแขกอีกคนที่คาดไม่ถึงอยู่ใกล้ๆ",
  ui_story_5043_50430601_45_dialog_content = "ในพุ่มไม้หลัง Schwab ฉันเห็นหัวเล็กๆ ขนปุกปุยของ Toto ยื่นออกมาจากใบไม้ เขาตัวสั่นเมื่อเขาจ้องมองมาที่ฉัน",
  ui_story_5043_50430601_46_dialog_content = "ฉันคิดว่าเขากังวลว่าฉันจะให้ที่ซ่อนของเขาไป ท้ายที่สุด ไม่มีใครต้องการ Eclipsite ในการป้องกันความเสี่ยง",
  ui_story_5043_50430601_47_dialog_content = "แต่เขาน่ารักมากและไม่มีพิษมีภัยอย่างเห็นได้ชัด สิ่งที่น่าสงสารหายไปในสวนขนาดใหญ่นั้น",
  ui_story_5043_50430601_48_dialog_content = "อันที่จริง ฉันเคยเห็นเขาปัดแมลงวันออกจากถ้วยชาของชวาบด้วยซ้ำ นั่นคือก่อนที่ Schwab จะสังเกตเห็นฉัน",
  ui_story_5043_50430601_49_dialog_content = "หลังจากงาน Moonlight Salon ฉันรีบกลับไปที่สวน ฉันจับมือเขาและพาเขาออกจากคฤหาสน์ซาลาร์อย่างปลอดภัย",
  ui_story_5043_50430601_50_dialog_content = "ฉันต้องสวมถุงมือใหม่เพื่อให้แน่ใจว่า Lumina และ Darkflow ของเขาไม่ชนกัน",
  ui_story_5043_50430601_51_dialog_content = "เขาสามารถเข้าใจจักรวาลได้ แม้ว่าเขาจะพูดได้เพียงไม่กี่คำพื้นฐาน และในวัน Mooncrown Day หลังจากที่เราพบกันได้ไม่นาน ฉันได้รับของขวัญจากเขา",
  ui_story_5043_50430601_52_dialog_content = "แค่นั้นแหละ. นั่นคือเรื่องราวทั้งหมด",
  ui_story_5043_50430601_53_dialog_content = "(ว้าว แม้แต่ Eclipsite ตัวเล็ก ๆ ธรรมดา ๆ ก็มีชื่อ...)",
  ui_story_5043_50430601_54_dialog_content = "รอก่อน. คุณไม่ได้พูดเรื่องที่เขาไม่ตอบจดหมายของคุณเหรอ?",
  ui_story_5043_50430601_55_dialog_content = "เขาจะไม่มีที่อยู่ใน Lumopolis ใช่ไหม ฉันเขียนกลับไปยังที่อยู่ผู้ส่งในปัจจุบัน แต่ไม่เคยได้ยินอะไรกลับมาเลย",
  ui_story_5043_50430601_56_dialog_content = "และคุณบอกว่าคุณไม่มีโอกาสแอบพบกับเขา?",
  ui_story_5043_50430601_57_dialog_content = "ใช่. เราไม่ได้บังเอิญเจอกันเลย ฉันไม่สามารถหาเขาได้ทุกที่",
  ui_story_5043_50430601_58_dialog_content = "และเมื่อคุณบอกว่าเขาจะสังเกตเห็นทุกที่ที่เขาไป...",
  ui_story_5043_50430601_59_dialog_content = "แน่นอนคุณสามารถเข้าใจได้ Eclipsite ใน Lumopolis จะต้องสร้างความตื่นตระหนก",
