  ui_story_5043_50430601_62_dialog_content = "หากมีฉันชอบที่จะเห็นด้วยตัวเอง",
  ui_story_5043_50430601_63_dialog_content = "ฉันคิดว่ามันเป็นความรู้สึกที่ไม่จำเป็น ใช่ แต่มันแปลกเกินไปที่จะเรียกมันว่าความรัก",
  ui_story_5043_50430601_64_dialog_content = "ฉันจะไม่พูดถึงมันในแง่โรแมนติก ฉันแค่อยากดูแลเขา",
  ui_story_5043_50430601_64X1_dialog_content = "แต่ยังไงก็ตาม ฉันก็ทน Eclipsites ไม่ได้เหมือนกัน",
  ui_story_5043_50430601_64X2_dialog_content = "*ดม ดม*",
  ui_story_5043_50430601_64X3_dialog_content = "คุณทีน่า ฉันไม่ได้พยายามปลุกใคร แต่ดูเหมือนคุณจะมีกลิ่นเหม็นของ Eclipsite ในตัวคุณ",
