  ui_story_5043_50430601_69X2_dialog_content = "ไม่ใช่ว่าสิ่งที่คุณนำมาคือปัญหา ไม่มีอะไรน่าสนใจเกิดขึ้นจากทั้งหมดนี้เหรอ?",
