  ui_story_5043_50430702_31_dialog_content = "(และเธอมีออร่าที่ทรงพลังมาก อาจเป็นเพราะความเชื่อของเธอ?)",
  ui_story_5043_50430702_32_dialog_content = "(สัญชาตญาณของฉันบอกว่าเธอไม่ได้เกี่ยวข้องอะไรกับคดีของเรา)",
  ui_story_5043_50430702_33_dialog_content = "ทุ. ทางตันอีกแล้ว และฉันคิดว่าเราไม่สามารถไปจับกุมผู้คนด้วยลางสังหรณ์ของเราได้",
  ui_story_5043_50430702_34_dialog_content = "พี่สาว ถ้าสิ่งที่เธอพูดเป็นความจริง...",
  ui_story_5043_50430702_35_dialog_content = "คุณอาจเต็มใจเข้าร่วมการพิจารณาคดีในฐานะพยานหรือไม่?",
  ui_story_5043_50430702_36_dialog_content = "ฉันรีบเร่งที่จะจัดงาน Moonlight Salons แต่ถ้านั่นเป็นสิ่งที่ Hall of Justice ต้องการก็ใช่",
  ui_story_5043_50430702_37_dialog_content = "ฉันจะทำทุกอย่างเท่าที่ทำได้เพื่อช่วย",
  ui_story_5043_50430702_38_dialog_content = "แต่...",
  ui_story_5043_50430702_39_dialog_content = "(จะเกิดอะไรขึ้นถ้าการพาเธอไปที่ Hall of Justice ทำให้เธอมีปัญหามากกว่านี้...)",
  ui_story_5043_50430702_40_dialog_content = "ใช่? หญิงสาว คุณมีอะไรจะพูดไหม",
  ui_story_5043_50430702_41_dialog_content = "ฉันแค่อยากรู้ว่าคุณสงบสติอารมณ์ได้อย่างไร",
  ui_story_5043_50430702_42_dialog_content = "ฉันไม่คัดค้านร้านแสงจันทร์ ฉันชอบพวกเขา—พวกเขาทำให้ลูโมโพลิสดูเหมือนเป็นสถานที่ที่แตกต่างออกไป",
  ui_story_5043_50430702_43_dialog_content = "แต่ประเพณีของ Lumopolis ไม่ยอมรับแม้กระทั่งการหย่าร้าง รักอิสระน้อยลงมาก",
  ui_story_5043_50430702_44_dialog_content = "และในฐานะสตรีแห่งศรัทธา ผู้ซึ่งเห็นได้ชัดว่ามีศรัทธามาก...",
  ui_story_5043_50430702_45_dialog_content = "คุณตัดสินใจจัดร้านเสริมสวยเหล่านี้ให้กับชาว Lumopolis ได้อย่างไร?",
  ui_story_5043_50430702_46_dialog_content = "และคุณไม่กลัวที่จะก้าวเข้าไปใน Hall of Justice เหรอ? มันช่าง...น่าชื่นชมยิ่งนัก",
  ui_story_5043_50430702_47_dialog_content = "ทีน่า...",
  ui_story_5043_50430702_48_dialog_content = "เฮ่เฮ่... ลูกเอ๋ย เจ้าอาจจะถามถึงความกังวลของตัวเองงั้นหรือ?",
  ui_story_5043_50430702_49_dialog_content = "ประเด็นก็คือ เมื่อคุณอายุเท่าฉัน คุณก็แค่เลิกวิตกกังวลและคิดมากไปเอง",
  ui_story_5043_50430702_50_dialog_content = "ทั้งหมดที่ฉันทำคือฟังพระประสงค์ของเทพเจ้าแห่งแสงสว่าง",
  ui_story_5043_50430702_51_dialog_content = "ตลอดประวัติศาสตร์อันยาวนาน Lumopolis ได้พัฒนาระบบมารยาทที่ซับซ้อนเพื่อควบคุมความปรารถนาของเรา",
  ui_story_5043_50430702_52_dialog_content = "แต่เดิมก่อตั้งโดยชายและหญิงธรรมดา ชาวออโรเรียนที่เรียบง่ายและบริสุทธิ์",
  ui_story_5043_50430702_53_dialog_content = "ในช่วงหลายปีที่ผ่านมา คำสอนของเทพเจ้าแห่งแสงสว่างถูกตีความซ้ำแล้วซ้ำเล่า",
  ui_story_5043_50430702_54_dialog_content = "แต่ในใจของพวกเขา คำสอนเหล่านั้นทั้งเรียบง่ายและใจดี",
  ui_story_5043_50430702_55_dialog_content = "และนั่นคือพรที่แท้จริงของเทพเจ้าแห่งแสงสว่าง บทเรียนที่แท้จริงของเขา",
  ui_story_5043_50430702_56_dialog_content = "ทั้งหมดที่ฉันทำคือนำชาว Aurorian กลับสู่ต้นกำเนิด ไปสู่ความปรารถนาที่แท้จริง",
  ui_story_5043_50430702_57_dialog_content = "ไม่มีบาปในเรื่องนี้ เป็นเพียงบางสิ่งที่กฎและขนบธรรมเนียมของเราไม่เข้าใจ",
  ui_story_5043_50430702_58_dialog_content = "ความศรัทธาและความรัก...ที่รากเหง้าพวกเขาเป็นหนึ่งเดียว",
  ui_story_5043_50430702_59_dialog_content = "ฉันคิดว่าฉันเข้าใจ ขอบคุณมาก.",
  ui_story_5043_50430702_60_dialog_content = "แล้วฉันจะลาไป",
  ui_story_5043_50430702_61_dialog_content = "และแจ้งให้เราทราบหากเราสามารถช่วยเพิ่มเติมในการตรวจสอบของคุณ",
  ui_story_5043_50430702_62_dialog_content = "แม้ว่าฉันจะเสนอข้อเสนอแนะเล็กน้อยต่อ Hall of Justice ได้หรือไม่?",
  ui_story_5043_50430702_63_dialog_content = "โอ๊ะ...?",
  ui_story_5043_50430702_64_dialog_content = "หากคุณต้องการเรียนรู้เพิ่มเติมจริงๆ ก่อนที่การพิจารณาคดีของศาลจะเริ่มต้นขึ้น แทนที่จะเพียงแค่ต้องผ่านกระบวนการต่างๆ ของคุณ...",
  ui_story_5043_50430702_65_dialog_content = "จากนั้นคุณจะต้องหยุดทำงานแบบกลไก คิดเกี่ยวกับสิ่งที่โจทก์ต้องการจริงๆ",
  ui_story_5043_50430702_66_dialog_content = "ขอบคุณสำหรับคำแนะนำ. เราจะคิดเรื่องนี้...",
  ui_story_5043_50430702_67_dialog_content = "แน่นอน. นั้นคือทั้งหมด. จนกว่าจะถึงครั้งต่อไป.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>วันต่อมา</color>",
  ui_story_5043_50430801_2_dialog_content = "อะไรนะ นี่คือทั้งหมดที่คุณพบเหรอ?",
  ui_story_5043_50430801_3_dialog_content = "ดังนั้นคุณจึงไขคดีเดิมไม่ได้ แต่คุณก็หารูปปั้นหัวขาดอีกจนได้!?",
  ui_story_5043_50430801_4_dialog_content = "ฉันขอโทษ. เรากำลังตรวจสอบอยู่แต่ยังไม่มีความคืบหน้าใดๆ...",
  ui_story_5043_50430801_5_dialog_content = "ไม่มีความก้าวหน้า!? คุณไม่มีความคืบหน้าเลย!",
  ui_story_5043_50430801_6_dialog_content = "นี่เป็นสิ่งที่ดีที่สุดที่ Hall of Justice จะทำได้หรือไม่?",
  ui_story_5043_50430801_7_dialog_content = "ฉันอาจจะมอบคดีนี้ให้กับสุนัขตาบอด บางทีมันอาจดมกลิ่นอาชญากร!",
  ui_story_5043_50430801_8_dialog_content = "ฉันเสียใจ. เราจะพยายามให้มากขึ้น...",
  ui_story_5043_50430801_9_dialog_content = "ตอนนี้ฉันเห็นแล้วว่า Hall of Justice ไม่มีความสนใจในปัญหาความรักของพลเมือง",
  ui_story_5043_50430801_10_dialog_content = "และ \"Romance Division\" นี้เป็นเพียงบ้านสำหรับผู้โหลดฟรี!",
  ui_story_5043_50430801_11_dialog_content = "ทุกคนต่างรับภาระหนักอึ้งและทำงานหนัก—ตอนหลับ!",
