  ui_story_5043_50430801_15_dialog_content = "ฉันจะไม่พูดอะไรอีกแล้ว ถ้าพรุ่งนี้คุณหาอะไรใหม่ไม่ได้ ฉันคงไม่มีทางเลือกนอกจากฟ้องเพื่อนบ้านต่อไป",
