  ui_story_5043_50430801_17_dialog_content = "จะมีประโยชน์อะไรที่จะจ่ายเงินให้คุณมากมายหากคุณไม่สามารถแก้ปัญหาของเราได้? ทำไม Lumopolis จะดีกว่าถ้าเราทำลายทั้งอาคาร!",
  ui_story_5043_50430801_18_dialog_content = "รื้อถอน?",
  ui_story_5043_50430801_19_dialog_content = "เฮ้ รุนแรงไปหน่อยมั้ย?",
