  ui_story_5043_50430801_31_dialog_content = "ตกงาน!?",
  ui_story_5043_50430801_32_dialog_content = "ที่ไม่สามารถเกิดขึ้นได้ และสิ่งต่าง ๆ ก็ไม่ได้แย่ขนาดนั้น!",
  ui_story_5043_50430801_33_dialog_content = "P-กรุณาอย่าแม้แต่จะแนะนำมัน",
  ui_story_5043_50430801_34_dialog_content = "ถ้าฉันตกงาน ฉันคงเบื่อที่จะอยู่บ้านทั้งวัน ฉันออกไปสนุกไม่ได้!",
  ui_story_5043_50430801_35_dialog_content = "เดี๋ยวก่อน นั่นคือทั้งหมดที่คุณกังวลเกี่ยวกับ? ขอให้สนุก?",
  ui_story_5043_50430801_36_dialog_content = "ฉันจะหาที่ไหนสักแห่งที่เงียบสงบพอที่จะนอนกลางวันได้?",
