  ui_story_5043_50430801_38_dialog_content = "และถ้าฉันไม่มีงานทำ พวกเขาจะให้ฉันกลับบ้าน",
  ui_story_5043_50430801_39_dialog_content = "พวกเขาจะบังคับให้ฉันเข้าร่วมธุรกิจของครอบครัว",
  ui_story_5043_50430801_40_dialog_content = "ใช่. นั่นคือครอบครัว ไม่มีอะไรนอกจากกลุ่มหมอกเก่าที่น่าเบื่อ",
  ui_story_5043_50430801_41_dialog_content = "ใครในโลกนี้อยากจะนั่งอยู่ที่นั่นเพื่อช่วยพวกเขานับไนเทียม?",
  ui_story_5043_50430801_42_dialog_content = "ฉันเห็นคุณขุนนางไม่ต้องการให้ฉันกังวลเกี่ยวกับคุณ...",
