  ui_story_5043_50430801_44_dialog_content = "ใช่. ถึงเราจะตกงานแต่ชีวิตก็ต้องดำเนินต่อไป",
  ui_story_5043_50430801_45_dialog_content = "แม้ว่าจะไม่มีเงินเดือน... ฉันจะต้องตุนมันฝรั่งและผัก",
  ui_story_5043_50430801_46_dialog_content = "และลดลงเหลือวันละมื้อ",
  ui_story_5043_50430801_47_dialog_content = "เดี๋ยวก่อน ทำไมเรื่องถึงดูน่ากลัวเมื่อเรามาหาคุณ?",
  ui_story_5043_50430801_48_dialog_content = "เนื่องจากชีวิตใน Lumopolis นั้นเลวร้าย นั่นเป็นเหตุผลว่าทำไม",
  ui_story_5043_50430801_49_dialog_content = "ซื้อกิน รักษาสังคม. การใช้ชีวิตไม่อิสระ คุณก็รู้",
  ui_story_5043_50430801_50_dialog_content = "ถ้าฉันสูญเสียเงินเดือน ฉันต้องเริ่มนับเงินทุกบาททุกสตางค์",
  ui_story_5043_50430801_51_dialog_content = "ว้าว. ชีวิตมันยาก...",
  ui_story_5043_50430801_52_dialog_content = "แต่ยังไม่ถึงเวลายอมแพ้! เรายังมีวัน มาใช้ประโยชน์กันเถอะ!",
  ui_story_5043_50430801_53_dialog_content = "ใช่. ถ้าเราทำอะไรสักอย่างจริง ๆ เราอาจจะก้าวหน้าขึ้นบ้าง",
  ui_story_5043_50430801_54_dialog_content = "แต่ปัญหาคือ—เราไม่มีลีดเดียวที่ต้องติดตาม",
  ui_story_5043_50430801_55_dialog_content = "เราควรสอบสายอะไรดี?",
  ui_story_5043_50430801_56_dialog_content = "ท่านสุภาพบุรุษและสุภาพสตรี... ฉันมีไอเดีย!",
  ui_story_5043_50430801_57_dialog_content = "ฉันคิดทบทวนแล้ว วิธีการของเราแคบเกินไป",
  ui_story_5043_50430801_58_dialog_content = "คดีตัดหัวรูปปั้นต่อเนื่องไม่ใช่อาชญากรรมธรรมดา",
  ui_story_5043_50430801_59_dialog_content = "เหยื่อคือรูปปั้น นั่นหมายความว่าเราไม่สามารถดูแวดวงสังคมของพวกเขาเพื่อหาคนที่มีแรงจูงใจได้",
  ui_story_5043_50430801_60_dialog_content = "ในทำนองเดียวกัน ไม่มีโอกาสที่จะพบผู้กระทำความผิดในหมู่สมาชิกในครอบครัวของเหยื่อ",
  ui_story_5043_50430801_61_dialog_content = "จริง. ปัจจัยเหล่านี้ขัดขวางการตรวจสอบของเรา",
  ui_story_5043_50430801_62_dialog_content = "แต่ลองคิดนอกกรอบสักครู่",
  ui_story_5043_50430801_63_dialog_content = "มีปัจจัยสำคัญประการหนึ่งที่ทำให้รูปปั้นเสียหายกลายเป็นคดีความในศาล—",
