  ui_story_5043_50430801_65_dialog_content = "ใช่. มันคือความรักที่ทำให้เรื่องนี้เป็นคดีความของ Romance Division",
  ui_story_5043_50430801_66_dialog_content = "และเมื่อความรักเข้ามาเกี่ยวข้อง มันเป็นไปไม่ได้อีกต่อไปที่จะใช้แนวทางที่เป็นเหตุเป็นผลอย่างหมดจด",
  ui_story_5043_50430801_67_dialog_content = "เราไม่ได้เผชิญกับกรณีปกติใดๆ เรื่องนี้เป็นเรื่องของหัวใจ",
  ui_story_5043_50430801_68_dialog_content = "โอ้! โอ้! สิ่งนี้ทำให้ทุกอย่างชัดเจนขึ้น!",
