  ui_story_5043_50430801_70_dialog_content = "... คุณได้ยินเสียงตัวเองไหม?",
  ui_story_5043_50430801_71_dialog_content = "เราไม่มีเบาะแสใดๆ แต่บางทีเราอาจไม่ต้องการโอกาสในการขาย",
  ui_story_5043_50430801_72_dialog_content = "เพื่อนรัก เมื่อพูดถึงความรัก ไม่จำเป็นต้องเข้าใจทุกอย่าง",
  ui_story_5043_50430801_73_dialog_content = "สิ่งสำคัญคือหัวใจ",
  ui_story_5043_50430801_74_dialog_content = "ลองคิดดูว่าแม่ชีคนนั้นพูดอะไร",
  ui_story_5043_50430801_75_dialog_content = "\"ถ้าคุณต้องการเรียนรู้เพิ่มเติมจริงๆ ก่อนที่การพิจารณาคดีของศาลจะเริ่มขึ้น แทนที่จะเพียงแค่ต้องผ่านกระบวนการต่างๆ ของคุณ...",
  ui_story_5043_50430801_76_dialog_content = "จากนั้นคุณจะต้องหยุดทำงานแบบกลไก คิดเกี่ยวกับสิ่งที่โจทก์ต้องการจริงๆ \"",
  ui_story_5043_50430801_77_dialog_content = "และเราจะไขคดีได้ด้วย...หัวใจ?",
  ui_story_5043_50430801_78_dialog_content = "ไปทำงานเพื่อน!",
  ui_story_5043_50430801_79_dialog_content = "เราจะหาคำตอบที่โจทก์ต้องการด้วยความรัก!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>วันถัดไป</color>",
  ui_story_5043_50430801_81_dialog_content = "เฮ้ ขวางทางทำไม",
  ui_story_5043_50430801_82_dialog_content = "ให้ฉันเข้าไป!",
  ui_story_5043_50430801_83_dialog_content = "โปรดรอสักครู่ คุณไบรอน",
  ui_story_5043_50430801_84_dialog_content = "ขณะนี้ผู้พิพากษากำลังยุ่งอยู่ในห้องพิจารณาคดี",
  ui_story_5043_50430801_85_dialog_content = "เราจะแจ้งให้คุณทราบทันทีที่มีเวลาพูดคุยกับคุณ",
  ui_story_5043_50430801_86_dialog_content = "ยุ่ง? อย่าไร้สาระ พวกมันยุ่งกับคดีของฉัน!",
  ui_story_5043_50430801_87_dialog_content = "ถ้าพวกเขาต้องการซ่อนตัวจากฉัน อย่างน้อยพวกเขาก็สามารถหาข้อแก้ตัวที่ดีกว่านี้ได้!",
  ui_story_5043_50430801_88_dialog_content = "คุณไบรอน กรรมการจริงๆ...",
  ui_story_5043_50430801_89_dialog_content = "ฉันไม่สนใจสิ่งที่พวกเขากำลังทำ นี่คือเวลาทำการของศาล",
  ui_story_5043_50430801_90_dialog_content = "S-Sir โปรดรอสักครู่!",
  ui_story_5043_50430801_91_dialog_content = "หลบไป!",
  ui_story_5043_50430801_92_dialog_content = "อา แต่...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>ผู้พิพากษามาติเยอ! เขาเข้าไปแล้ว!!!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>โผล่! โผล่! โผล่!</color>",
  ui_story_5043_50430801_95_dialog_content = "ขอแสดงความยินดี คุณไบรอน!",
  ui_story_5043_50430801_96_dialog_content = "ฉันมีความสุขมากสำหรับคุณทั้งคู่!",
  ui_story_5043_50430801_97_dialog_content = "ช่างวิเศษเหลือเกินที่คุณได้พบกับรักแท้อีกครั้งในวันธรรมดาๆ แบบนี้!",
  ui_story_5043_50430801_98_dialog_content = "เอ๋? นี่มัน...",
  ui_story_5043_50430801_99_dialog_content = "เราใช้เวลาทั้งวัน แต่เราสร้างรูปปั้นของคุณขึ้นใหม่",
  ui_story_5043_50430801_100_dialog_content = "ถ้าเรามีเวลาอีกหน่อย เราจะทำให้มันดูดีกว่านี้!",
  ui_story_5043_50430801_101_dialog_content = "ใช่. เราตระหนักว่าเราต้องใช้วิธีการที่โรแมนติกมากขึ้น และนี่คือวิธีแก้ปัญหาของเรา",
  ui_story_5043_50430801_102_dialog_content = "คำถามไม่ใช่สิ่งที่คุณสูญเสียไป เป็นสิ่งที่คุณยังสามารถได้รับ",
  ui_story_5043_50430801_103_dialog_content = "ท้ายที่สุด การสูญเสียเพียงศีรษะจะไม่ขวางทางความรักของคุณอย่างแน่นอน?",
  ui_story_5043_50430801_104_dialog_content = "ไม่ คุณยังต้องรัก แต่ก็เป็นที่เข้าใจได้ว่าความไม่สมบูรณ์ของเธอทำให้คุณเสียใจ",
  ui_story_5043_50430801_105_dialog_content = "และเพื่อขจัดความเศร้านั้นออกจากใจ เราต้องทำให้เธอสมบูรณ์อีกครั้ง",
  ui_story_5043_50430801_106_dialog_content = "หึหึ เรื่องราวที่สวยงามของการสูญเสียและการฟื้นตัว...",
  ui_story_5043_50430801_107_dialog_content = "ค-คุณ...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>ทำอะไรลงไปเนี่ย!?</size>",
  ui_story_5043_50430801_109_dialog_content = "ก้อนที่น่ากลัวที่คอของ Galatea คืออะไร? คุณพยายามที่จะดูถูกฉัน?",
  ui_story_5043_50430801_110_dialog_content = "นี้? น่าเกลียด?",
  ui_story_5043_50430801_111_dialog_content = "ดูไม่ค่อยพอใจ...",
  ui_story_5043_50430801_112_dialog_content = "ทุ. ฉันรู้ว่าเราไม่ควรไว้ใจคนธรรมดาในเรื่องของความสวยงาม",
  ui_story_5043_50430801_113_dialog_content = "หากคุณไม่พอใจกับรูปลักษณ์ใหม่ของเธอ เราสร้างใหม่ได้...",
  ui_story_5043_50430801_114_dialog_content = "หยุดนะ! เจ้าปัญญาอ่อนเยาะเย้ยความรักของข้า!",
