  ui_story_5043_50430801_116_dialog_content = "ความรักนั้นไม่เหมือนใครและเป็นความจริง! รักคือทางเลือกที่ไม่มีวันเปลี่ยน!",
  ui_story_5043_50430801_117_dialog_content = "และเมื่อ Galatea หายหัวไป ความรักของฉันก็ตาย!",
  ui_story_5043_50430801_118_dialog_content = "แม้ว่าคุณจะสร้างแบบจำลองศีรษะของเธอได้ แต่เธอก็ไม่ใช่ Galatea ของฉัน!",
  ui_story_5043_50430801_119_dialog_content = "เธอคงไม่ใช่คนที่ฉันรัก!",
