  ui_story_5043_50430901_12_dialog_content = "เราต้องหาวิธีหยุดขบวนพาเหรด",
  ui_story_5043_50430901_13_dialog_content = "หยุดขบวนพาเหรด? ทำไมเราทำอะไรผิดหรือเปล่า?",
  ui_story_5043_50430901_14_dialog_content = "สิ่งนี้ต้องใช้การจัดระเบียบอย่างมาก คุณไม่สามารถหยุดมันไม่ให้ดำเนินต่อไปได้โดยไม่มีเหตุผลที่ดี",
  ui_story_5043_50430901_15_dialog_content = "พวกมันเคลื่อนไหวอย่างรวดเร็ว เรามีเวลาไม่นาน",
  ui_story_5043_50430901_16_dialog_content = "ฉันจะพยายามหยุดพวกเขา คุณอธิบายให้แม่ชีฟัง!",
  ui_story_5043_50430901_17_dialog_content = "โอ้ ทำไมสามัญชนมักเร่งรีบ...",
  ui_story_5043_50430901_18_dialog_content = "น้องสาว ฟังนะ เราไม่ต้องการหยุดขบวนพาเหรด",
  ui_story_5043_50430901_19_dialog_content = "แต่เราต้อง เพื่อความรัก.",
  ui_story_5043_50430901_20_dialog_content = "รัก?",
  ui_story_5043_50430901_21_dialog_content = "มีคนจะใช้ขบวนพาเหรดเป็นที่กำบังในการก่ออาชญากรรม",
  ui_story_5043_50430901_22_dialog_content = "และฉันแน่ใจว่าคุณคงไม่อยากให้งานของคุณมีชื่อเสียงว่าทำให้คนอกหักใช่ไหม?",
  ui_story_5043_50430901_23_dialog_content = "เรา! ชื่นชม! รัก!",
  ui_story_5043_50430901_24_dialog_content = "ฟรี! รัก!",
  ui_story_5043_50430901_25_dialog_content = "ว้าว! เดี๋ยวก่อนทุกคน!",
  ui_story_5043_50430901_26_dialog_content = "ฉันคิดว่าเรากำลังไปผิดทาง",
  ui_story_5043_50430901_27_dialog_content = "เราตั้งใจจะไปที่ย่านที่อยู่อาศัยในลาน Lumopolis!",
  ui_story_5043_50430901_28_dialog_content = "เราต้องหันหลังกลับไป",
  ui_story_5043_50430901_29_dialog_content = "ใช่! กลับไป!",
  ui_story_5043_50430901_30_dialog_content = "ฮะ? เรากำลังไปผิดทาง?",
  ui_story_5043_50430901_31_dialog_content = "นั่นไม่ถูกต้อง เราได้รับคำสั่งให้ปีนบันไดสู่ท้องฟ้าด้วยกัน",
  ui_story_5043_50430901_32_dialog_content = "เราคงเข้าใจผิดไปแล้ว อาจมีคนฟังคำแนะนำผิด",
  ui_story_5043_50430901_33_dialog_content = "ย่านที่อยู่อาศัย?",
  ui_story_5043_50430901_34_dialog_content = "ฉันได้ยินมาว่ามันคือจัตุรัสใน Lumopolis Courtyard!",
  ui_story_5043_50430901_35_dialog_content = "ห่างออกไปหลายไมล์! รีบกลับกันเถอะ!",
  ui_story_5043_50430901_36_dialog_content = "อย่างแน่นอน! หันหลังกลับแล้วไปกันเลย!",
  ui_story_5043_50430901_37_dialog_content = "กลับไป? แต่เรามาไกลแล้ว...",
  ui_story_5043_50430901_38_dialog_content = "ใช่แล้ว!",
  ui_story_5043_50430901_39_dialog_content = "แต่เรากำลังจะไปย่านที่พักอาศัย",
  ui_story_5043_50430901_40_dialog_content = "เลขที่! มันคือจัตุรัส!",
  ui_story_5043_50430901_41_dialog_content = "เดี๋ยว. ฉันจำได้อย่างชัดเจนว่ามีคนบอกเราว่าจะไปปีน Stairway to the Skies",
  ui_story_5043_50430901_42_dialog_content = "ขวา! ถ้าไม่ ทำไมเราถึงมาเจอกันที่ด้านล่างสุดของบันได?",
  ui_story_5043_50430901_43_dialog_content = "คุณเป็นคนที่ต้องการไปย่านที่พักอาศัยหรือจัตุรัส คุณได้ข้อมูลของคุณมาจากไหน?",
  ui_story_5043_50430901_44_dialog_content = "ผู้ชายผมสีขาวมัดหางม้า เขาดูน่าเชื่อถือ",
  ui_story_5043_50430901_45_dialog_content = "ผู้ชายที่ดูน่าเชื่อถือผมสีขาวมัดหางม้า",
  ui_story_5043_50430901_46_dialog_content = "เฮ้ย คนเดียวกันนี่หว่า คุณถูกหลอกแล้ว!",
  ui_story_5043_50430901_47_dialog_content = "อะไรนะ!",
  ui_story_5043_50430901_48_dialog_content = "เฮ้ นั่นเขาเอง! ดูสิ เขามีผมสีขาวและหางม้า!",
  ui_story_5043_50430901_49_dialog_content = "อะไร ฉัน? ไม่ ฉันแค่ผ่านมา...",
  ui_story_5043_50430901_50_dialog_content = "นั่นคือเขา!",
  ui_story_5043_50430901_51_dialog_content = "เขาเป็นคนบอกฉันเอง!",
  ui_story_5043_50430901_52_dialog_content = "แล้วใครคือคนแปลกหน้าที่พยายามจะทำลาย Love Parade ของเรา?",
  ui_story_5043_50430901_53_dialog_content = "พาเขาไปที่ Romance Division!",
  ui_story_5043_50430901_54_dialog_content = "ท-ไม่มีความจำเป็น ฉันจะไปที่นั่นอยู่แล้ว...",
  ui_story_5043_50430901_55_dialog_content = "มาเร็ว! เดินขบวนต่อไป!",
  ui_story_5043_50430901_56_dialog_content = "และอย่าให้ผู้ชายคนนั้นหนีไปได้",
  ui_story_5043_50430901_57_dialog_content = "(ยี้ ความคิดที่ยอดเยี่ยมของฉันไม่ดีเท่าที่ฉันหวังไว้)",
  ui_story_5043_50430901_58_dialog_content = "(แล้วคนก็ออกเดินทางอีกแล้ว ทำไงดี?)",
  ui_story_5043_50430901_59_dialog_content = "โอ้ที่รัก โอ้ที่รัก! ฉันทำถังนมและน้ำผึ้งแตกไปแล้ว!",
  ui_story_5043_50430901_60_dialog_content = "โอ้ ฉันช่างเป็นคนซุ่มซ่ามเสียนี่กระไร",
  ui_story_5043_50430901_61_dialog_content = "อะไร ดูนมที่ไหลลงมาตามบันได",
  ui_story_5043_50430901_62_dialog_content = "มันมาจากไหนในโลก?",
  ui_story_5043_50430901_63_dialog_content = "แล้วทำไมนมถึงมีน้ำผึ้งผสมอยู่!?",
  ui_story_5043_50430901_64_dialog_content = "(T- นั่นดูเหมือนเป็นกลยุทธ์ที่ตรงประเด็นกว่าของ Matthieu!)",
  ui_story_5043_50430901_65_dialog_content = "(เป็นความคิดที่แปลกแต่ดูเหมือนว่าจะได้ผล ผู้คนหยุดแล้ว)",
  ui_story_5043_50430901_66_dialog_content = "ว้าว. ทุกอย่างดูเหมือนจะผิดพลาดในวันนี้",
  ui_story_5043_50430901_67_dialog_content = "เรายอมแพ้ไม่ได้ ดังที่พระเจ้าแห่งแสงสว่างตรัสไว้ ถนนสู่ดินแดนแห่งพรนั้นเป็นหนึ่งในการทดลองและความยากลำบาก!",
  ui_story_5043_50430901_68_dialog_content = "อย่างแน่นอน! แค่นมกับน้ำผึ้งแสดงว่าเรามาถูกทางแล้ว!",
  ui_story_5043_50430901_69_dialog_content = "เดินหน้าต่อไปนะทุกคน แต่ระวังอย่าให้ลื่น",
  ui_story_5043_50430901_70_dialog_content = "(พวกเขาได้เริ่มต้นอีกครั้ง?)",
  ui_story_5043_50430901_71_dialog_content = "(พวกเขาแน่ใจว่าเป็นกลุ่มที่แน่วแน่...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>อ๊ะ!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>บันไดลื่นมาก!!!</size>",
  ui_story_5043_50430901_74_dialog_content = "เกิดอะไรขึ้นน่ะ",
  ui_story_5043_50430901_75_dialog_content = "ฉันคิดว่ามีคนล้มลง",
  ui_story_5043_50430901_76_dialog_content = "บู้ฮู้...มันเจ็บจริงๆ...",
  ui_story_5043_50430901_77_dialog_content = "ฉันเห็นดวงดาวแม้ว่าจะเป็นเวลากลางวันก็ตาม",
  ui_story_5043_50430901_78_dialog_content = "S-ดูเหมือนเธอจะบาดเจ็บสาหัส",
  ui_story_5043_50430901_79_dialog_content = "ขั้นตอนเหล่านี้ค่อนข้างอันตรายในตอนนี้...",
  ui_story_5043_50430901_80_dialog_content = "บางที... เราควรจะเลิกทำวันนี้ดีไหม?",
  ui_story_5043_50430901_81_dialog_content = "ใช่. เราสามารถแห่ไปที่อื่นได้",
  ui_story_5043_50430901_82_dialog_content = "อย่าเอาแต่ยืนขวางทาง หาคนพาผู้หญิงน่าสงสารคนนี้ไปหาหมอ",
  ui_story_5043_50430901_83_dialog_content = "พวกเขาถอยกลับ!",
  ui_story_5043_50430901_84_dialog_content = "การแสดงที่ยอดเยี่ยม Tina!",
  ui_story_5043_50430901_85_dialog_content = "ใช่ น่าเชื่อมาก!",
  ui_story_5043_50430901_86_dialog_content = "ฮิฮิ. ถ้าฉันตกงานที่ Hall of Justice ฉันอาจจะขึ้นเวที",
  ui_story_5043_50430901_87_dialog_content = "แล้วเคล็ดลับของฉันล่ะ? ฉลาดเหรอ?",
  ui_story_5043_50430901_88_dialog_content = "มันยอดเยี่ยมมาก สมบูรณ์แบบ",
  ui_story_5043_50430901_89_dialog_content = "ลูก ๆ ของคุณ ... นั่นเป็นอย่างอื่น",
  ui_story_5043_50430901_90_dialog_content = "แต่เนื่องจากทั้งหมดเป็นไปเพื่อปกป้องชื่อเสียงของเหตุการณ์เหล่านี้ ก็ช่างมันเถอะ",
  ui_story_5043_50430901_91_dialog_content = "ความรักทั้งหมดมีค่าควรแก่การปกป้อง แม้แต่ความรักต่อรูปปั้น",
  ui_story_5043_50430901_92_dialog_content = "ฉันเข้าใจแล้วว่าทำไมคุณถึงเปิดร้านเสริมสวย ขอบคุณที่เข้าใจพี่สาว",
  ui_story_5043_50430901_93_dialog_content = "ฉันต้องไป. ฉันจะนำขบวนพาเหรดไปในทิศทางอื่น",
  ui_story_5043_50430901_94_dialog_content = "และเราจะทำหน้าที่ของเราให้ดีที่สุดเช่นกัน",
  ui_story_5043_50430901_95_dialog_content = "ไม่นะ! ทุกคน หยุด!",
  ui_story_5043_50430901_96_dialog_content = "เราต้องกลับไปที่บันได!",
  ui_story_5043_50430901_97_dialog_content = "เกิดอะไรขึ้น? มีความโกลาหลบางอย่าง!",
