  ui_story_5043_50430901_103_dialog_content = "ไปช่วยเขากันเถอะ สถิติ!",
  ui_story_5043_50430901_104_dialog_content = "อย่าลืมรูปปั้น! ฝูงนั้นกำลังจะแตกตื่นผ่านไป",
  ui_story_5043_50430901_105_dialog_content = "มันเป็นเพียงไม่กี่ Eclipsites เสริมหนึ่งคนน่าจะเพียงพอ",
  ui_story_5043_50430901_106_dialog_content = "ทีน่า คุณไปช่วยเลย์นะ ทุกคนอยู่ที่นี่กับรูปปั้น",
  ui_story_5043_50430901_107_dialog_content = "ฉันจะใช้ความสามารถทางจิตของฉันเพื่อช่วยเธอต่อสู้กับ Eclipsites ทีน่า",
  ui_story_5043_50430901_108_dialog_content = "โอเคฟังดูดี.",
