  ui_story_5043_50431001_6_dialog_content = "เฮ้! ทุกคนระวัง!",
  ui_story_5043_50431001_7_dialog_content = "มีรูปปั้นที่มีค่ามากอยู่ที่นี่ คุณทำลายมัน คุณซื้อมัน!",
  ui_story_5043_50431001_8_dialog_content = "สุริยุปราคา! คุณกำลังรออะไรอยู่!? วิ่ง!",
