  ui_story_5043_50431201_28_dialog_content = "หากเขาเต็มใจที่จะฝ่าฝืนกฎหมายต่อหน้าศาลยุติธรรมทั้งหมด ใครจะรู้ว่าเขาสามารถกระทำการอันเลวร้ายใดได้บ้างในความเป็นส่วนตัวในบ้านของเขาเอง...",
  ui_story_5043_50431201_29_dialog_content = "โอเค ตอนนี้คุณเริ่มทำให้ฉันกลัวแล้ว",
  ui_story_5043_50431201_30_dialog_content = "ดี. ความกลัวของคุณจะทำให้คุณไม่หยุดนิ่ง",
  ui_story_5043_50431201_31_dialog_content = "มาเถิดอย่าละสายตาจากเขา",
  ui_story_5043_50431201_32_dialog_content = "ชาของคุณเจ้านายของฉัน",
  ui_story_5043_50431201_33_dialog_content = "ดี ให้มันที่นี่",
  ui_story_5043_50431201_34_dialog_content = "ห้องครัวกำลังเตรียมของหวาน ให้ฉันเอาจานมาให้นายไหม?",
  ui_story_5043_50431201_35_dialog_content = "นั่นไม่จำเป็น ฉันมีเรื่องอื่นที่ต้องจัดการในตอนนี้",
  ui_story_5043_50431201_36_dialog_content = "อย่ารบกวนฉันจนกว่าฉันจะจัดการกับพวกเขาเสร็จ",
  ui_story_5043_50431201_37_dialog_content = "ครับ อาจารย์ชวาบ!",
  ui_story_5043_50431201_38_dialog_content = "เขาส่งคนรับใช้ของเขาไป",
  ui_story_5043_50431201_39_dialog_content = "จุ๊ๆ... เรื่องพวกนี้จะชั่วร้ายขนาดที่แม้แต่คนของเขาเองก็ไม่สามารถเป็นองคมนตรีได้หรือไม่?",
  ui_story_5043_50431201_40_dialog_content = "เอ่อ... ม-บางทีเขาอาจจะอยากอยู่คนเดียวสักพัก?",
  ui_story_5043_50431201_41_dialog_content = "สุจริต, PlayerName... คุณไม่มีจินตนาการ?",
  ui_story_5043_50431201_42_dialog_content = "ฉันหรือฉันไม่ได้แค่พูดว่า Schwab ไม่ใช่คนที่สามารถเข้าใจได้ง่าย?",
  ui_story_5043_50431201_43_dialog_content = "สบายดี ฉันเข้าใจแล้ว",
  ui_story_5043_50431201_44_dialog_content = "ถึงกระนั้นมันจะแย่แค่ไหน? ผู้ชายที่ซับซ้อนอย่างเขาจะทำอะไรได้บ้างในสวนของเขาเอง?",
  ui_story_5043_50431201_45_dialog_content = "ดู! เขายกมือขึ้นแล้ว!",
  ui_story_5043_50431201_46_dialog_content = "ดูเหมือนว่าเขากำลังถืออะไรบางอย่างอยู่",
  ui_story_5043_50431201_47_dialog_content = "มันคือเข็ม! เขามีเข็มอยู่ในมือ!",
  ui_story_5043_50431201_48_dialog_content = "เข็ม?!",
  ui_story_5043_50431201_49_dialog_content = "เพื่อจุดประสงค์อะไร? เขาหมายถึงใช้มันกับตัวเอง?!",
  ui_story_5043_50431201_50_dialog_content = "ไม่ ไม่เข้าข้างตัวเอง...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>แทง!</color>",
  ui_story_5043_50431201_52_dialog_content = "เขาใช้มันกับตุ๊กตาตัวนั้นในมืออีกข้าง...",
