  ui_story_5043_50431201_54_dialog_content = "ฉันเคยได้ยินเรื่องนี้มาก่อน... คำสาปประเภทหนึ่งเกี่ยวกับการใช้ตุ๊กตา",
  ui_story_5043_50431201_55_dialog_content = "คำสาป?",
  ui_story_5043_50431201_56_dialog_content = "มันทำงานโดยนำบางสิ่งออกจากร่างกายคน ซึ่งมักจะเป็นเส้นผมหรือเลือด แล้ววางไว้ในตุ๊กตา",
  ui_story_5043_50431201_57_dialog_content = "เมื่อทำเช่นนั้น ตุ๊กตาจะเชื่อมโยงทางวิญญาณกับบุคคลนั้น",
  ui_story_5043_50431201_58_dialog_content = "การทิ่มแทงหรือทำร้ายตุ๊กตาจะสร้างความเจ็บปวดและการบาดเจ็บแบบเดียวกันกับเป้าหมายของคำสาป",
  ui_story_5043_50431201_59_dialog_content = "และในที่สุด คนๆ นั้นจะต้องตายอย่างเจ็บปวดแสนสาหัส!",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>แทง!</color>",
  ui_story_5043_50431201_61_dialog_content = "Tsk เขาทำอีกแล้ว!",
  ui_story_5043_50431201_62_dialog_content = "ฉันคิดว่าฉันเคยได้ยินคำสาปแบบนั้น แต่ฉันไม่เคยคาดคิดมาก่อนว่าคนอย่างชวาบจะหลงใหลในศาสตร์มืด...",
  ui_story_5043_50431201_63_dialog_content = "ฉันไม่คิดว่ามันน่าแปลกใจเลย ฉันเห็นท่าทางที่อ่อนโยนและสูงส่งของเขามานานแล้ว!",
  ui_story_5043_50431201_64_dialog_content = "ไม่รู้สิ... คำสาปแบบนี้มักจะเป็นแค่ความเชื่อทางไสยศาสตร์ใช่ไหม?",
  ui_story_5043_50431201_65_dialog_content = "นอกจากนี้ นี่จะเป็นการละเมิดศรัทธาของลูโมโปลิสอย่างร้ายแรง...",
  ui_story_5043_50431201_66_dialog_content = "ฉันเห็น. ไม่สำคัญว่าคำสาปนั้นจะมีจริงหรือไม่ สิ่งสำคัญคือผู้คนจะเชื่อหรือไม่",
  ui_story_5043_50431201_67_dialog_content = "และชัดเจนสำหรับฉันว่า Schwab เชื่อในสิ่งนี้",
  ui_story_5043_50431201_68_dialog_content = "ซึ่งหมายความว่าที่ไหนสักแห่งในโลก... มีคนคนหนึ่งที่ Schwab เกลียดชังจนอยากจะฆ่าพวกเขา...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>แทง!</color>",
  ui_story_5043_50431201_70_dialog_content = "แต่ใคร? จะเป็นใครได้ล่ะ!",
  ui_story_5043_50431201_71_dialog_content = "ใครกันที่ทำผิดต่อเขาอย่างร้ายแรงถึงขนาดปรารถนาให้พวกเขาตาย?",
  ui_story_5043_50431201_72_dialog_content = "ฉันไม่รู้... แต่มันทำให้คุณสงสัยจริงๆ ใช่ไหม",
  ui_story_5043_50431201_73_dialog_content = "ตามบัญชีส่วนใหญ่ Schwab มีชีวิตที่เกือบจะสมบูรณ์แบบ ... ฉันนึกไม่ออกว่าใครจะทำลายสิ่งนั้นให้เขาได้",
  ui_story_5043_50431201_74_dialog_content = "นอกเสียจากว่า...ความเกลียดชังของเขาจะมาจากที่ที่ไม่มีใครมองเห็นได้ง่ายๆ",
  ui_story_5043_50431201_75_dialog_content = "เมื่อคุณพูดแบบนั้น... ใช่ มันสมเหตุสมผลแล้วในตอนนี้!",
  ui_story_5043_50431201_76_dialog_content = "เห็นได้ชัดว่าความโกรธของเขามีสาเหตุมาจากการสูญเสียไปนานแต่ยังยากจะลืมเลือน <color=#FFB400>รัก</color>!",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>แทง!</color>",
  ui_story_5043_50431201_78_dialog_content = "หากเป็นเช่นนั้นจริง เราต้องทำอะไรสักอย่างโดยด่วน! อาจหมายถึงความแตกต่างระหว่างชีวิตและความตายสำหรับใครบางคนที่นั่น!",
  ui_story_5043_50431201_79_dialog_content = "อย่าเพิ่งรีบร้อน เราต้องรอให้เขาแสดงหลักฐานการกระทำผิดที่ชัดเจนและปฏิเสธไม่ได้ก่อนเราจึงจะเข้าไปแทรกแซงได้",
  ui_story_5043_50431201_80_dialog_content = "เราจะทำอะไรได้บ้างในตอนนี้ จากความรู้ปัจจุบันของเรา หยุดเขาจากการทิ่มตุ๊กตาที่น่าสงสาร?",
  ui_story_5043_50431201_81_dialog_content = "เฮ้ คุณไม่คิดว่าความเชื่องมงายพวกนั้นมีจริงเหรอ...",
