  ui_story_5043_50431201_105_dialog_content = "เฮ้อ ดูเหมือนการทดลองเล็กๆ น้อยๆ ของฉันจะยังไม่สมบูรณ์ บางทีฉันอาจจะก้าวหน้ามากขึ้นในวันนี้ ... ?",
