  ui_story_5043_50431201_110_dialog_content = "อย่าข้ามไปยังข้อสรุปที่บ้าๆ บอๆ อีกเลย ไม่ใช่หลังจากครั้งสุดท้าย",
  ui_story_5043_50431201_111_dialog_content = "อาจเป็นเพียงการทดลองเล็ก ๆ ที่บ้าน? อาจเป็นงานอดิเรกของเขา...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5043_50431201_113_dialog_content = "ว้าว!",
  ui_story_5043_50431201_114_dialog_content = "ระเบิดงั้นเหรอ?! เขากำลังทำอะไรอยู่ในนั้น!",
  ui_story_5043_50431201_115_dialog_content = "ฉันไม่รู้ เราควรเข้าไปใกล้อีกหน่อยแล้วดูไหม?",
  ui_story_5043_50431201_116_dialog_content = "ยังไง? ไม่มีที่ให้ซ่อนในห้องนั้น!",
  ui_story_5043_50431201_117_dialog_content = "ถ้าเราเข้าไปใกล้กว่านี้ ปกของเราจะปลิว...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5043_50431201_119_dialog_content = "ระเบิดอีก! เป็นไปได้ไหมว่าเขากำลังทำระเบิดอยู่?!",
  ui_story_5043_50431201_120_dialog_content = "ระเบิด?! W-เดี๋ยวก่อน เรากำลังกระโดดไปสู่ข้อสรุปอีกครั้ง!",
  ui_story_5043_50431201_121_dialog_content = "และทำไมไม่? นี่คือธุรกิจของครอบครัว Salars ไม่มากก็น้อย!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5043_50431201_123_dialog_content = "แต่ทำไมเขาถึงวิจัยวัตถุระเบิด?",
  ui_story_5043_50431201_124_dialog_content = "ยิ่งสถานที่ได้รับการออกแบบอย่างประณีตมากเท่าใด ก็ยิ่งเสี่ยงต่อการเกิดระเบิดมากขึ้นเท่านั้น Lumopolis ก็ไม่มีข้อยกเว้น",
  ui_story_5043_50431201_125_dialog_content = "ลองคิดดู: ใครบางคนจะมาขึ้นศาลในข้อหาทำลายรูปปั้น",
  ui_story_5043_50431201_126_dialog_content = "แล้วถ้าเป็นหอนาฬิกาหรือโบสถ์ล่ะ? ผลที่ตามมาจะยิ่งเป็นไปไม่ได้",
  ui_story_5043_50431201_127_dialog_content = "ด้วยการใช้พลังทำลายล้างของระเบิด พวกเขาสามารถใช้ความกลัวบังคับให้คนอื่นเชื่อฟัง!",
  ui_story_5043_50431201_128_dialog_content = "ไม่รู้สิ... \"ระเบิด\" ของเขาไม่ได้สร้างความเสียหายให้กับบ้านของเขามากนัก",
  ui_story_5043_50431201_129_dialog_content = "ด้วยเหตุนี้เขาจึงเรียกมันว่า \"การทดลองเล็กน้อย\"!",
  ui_story_5043_50431201_130_dialog_content = "เมื่อเขาเข้าใจวิทยาศาสตร์ที่อยู่เบื้องหลังอย่างถ่องแท้แล้ว เขาก็สามารถใช้ Luminatics เพื่อทำให้ระเบิดของเขามีพลังมากขึ้นเป็นร้อยเท่า!",
  ui_story_5043_50431201_131_dialog_content = "หากเขาทำสำเร็จ Schwab สามารถยกระดับสังคมทั้งหมดของเราอย่างที่เรารู้!",
  ui_story_5043_50431201_132_dialog_content = "Lumopolis ทั้งหมดอาจตกอยู่ภายใต้การควบคุมของเขา...",
  ui_story_5043_50431201_133_dialog_content = "ฉัน-มันรุนแรงขนาดนั้นเลยเหรอ?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5043_50431201_135_dialog_content = "แค่ก แค่ก...",
  ui_story_5043_50431201_136_dialog_content = "อา ความพยายามที่ล้มเหลวอีกครั้ง",
  ui_story_5043_50431201_137_dialog_content = "ใครจะรู้ว่าการทำ <color=#FFB400>คาราเมลพุดดิ้ง</color> อาจเป็นเรื่องยาก?",
  ui_story_5043_50431201_138_dialog_content = "...",
  ui_story_5043_50431201_139_dialog_content = "คุณกำลังจะบอกว่าเขาจะยึดครองลูโมโพลิส...ด้วยพุดดิ้งงั้นเหรอ!?",
  ui_story_5043_50431201_140_dialog_content = "ฉัน-เขาเป็นคนงี่เง่าอย่างนั้นเหรอ?! เขาสร้างระเบิดขณะอบขนมได้อย่างไร!",
  ui_story_5043_50431201_141_dialog_content = "ต่อไปนี้เป็นคำถามที่ดีกว่า: การเดาของคุณทั้งคู่จะผิดพลาดโดยสิ้นเชิงได้อย่างไร!",
  ui_story_5043_50431201_142_dialog_content = "จุ๊ๆ! เขากำลังจะกลับออกมาข้างนอก! รีบซ่อน!",
  ui_story_5043_50431201_143_dialog_content = "เฮ้อ...เสียเวลาเสียแรงอีก",
  ui_story_5043_50431201_144_dialog_content = "อาจถึงเวลาที่ต้องทำสิ่งที่มีประสิทธิผลมากขึ้น? นี่ฉันเอากุญแจห้องใต้ดินไปไว้ที่ไหนเนี่ย...",
  ui_story_5043_50431201_145_dialog_content = "ฉันควรเช็คของครั้งสุดท้ายก่อนการพิจารณาคดีในวันพรุ่งนี้...",
  ui_story_5043_50431201_146_dialog_content = "ขออภัย อาจารย์ชวาบ แต่อาหารเย็นพร้อมแล้ว",
  ui_story_5043_50431201_147_dialog_content = "ฉันไม่ได้พูดให้ชัดเจนไปเลยใช่ไหมว่าตอนนี้ฉันไม่อยากถูกรบกวน?!",
  ui_story_5043_50431201_148_dialog_content = "F-ยกโทษให้ด้วย อาจารย์! ฉันไม่ได้ตั้งใจ... แต่อาหารอยู่บนโต๊ะแล้ว...",
  ui_story_5043_50431201_149_dialog_content = "อืม... ดีมาก แต่ขอให้ครั้งนี้เป็นครั้งสุดท้ายที่เธอขัดจังหวะฉัน!",
  ui_story_5043_50431201_150_dialog_content = "Schwab ไปทานอาหารเย็น ฉันไม่คิดว่าเราจะตามเขาไปที่นั่นไม่ได้ ไม่ใช่กับคนรับใช้ทั้งหมดที่อยู่รอบๆ",
  ui_story_5043_50431201_151_dialog_content = "คุณได้ยินสิ่งที่เขาพูดก่อนที่เขาจะจากไปหรือไม่?",
  ui_story_5043_50431201_152_dialog_content = "ให้ฉันเดาว่ามันเกี่ยวข้องกับการที่เขา \"เข้าใจยาก\" หรือไม่?",
  ui_story_5043_50431201_153_dialog_content = "ตลกมาก แต่ไม่เลย—เขาพูดถึงบางอย่างเกี่ยวกับห้องใต้ดิน",
  ui_story_5043_50431201_154_dialog_content = "ใช้สมองของคุณสักครั้งใช่ไหม? ก่อนที่เขาจะถูกเรียกไปทานอาหารเย็น เขาดึงกุญแจห้องใต้ดินของคฤหาสน์ออกมา",
  ui_story_5043_50431201_155_dialog_content = "และมอง! เขาทิ้งกุญแจนั่นไว้ในล็อคนั่น!",
  ui_story_5043_50431201_156_dialog_content = "เราไปดูข้างในกันไหม? ใครจะไปรู้ว่าเราจะพบความลับอะไรหลังประตูบานนั้น!",
  ui_story_5043_50431201_157_dialog_content = "ดูเหมือนจะเป็นโอกาสที่สมบูรณ์แบบและทั้งหมด แต่...",
  ui_story_5043_50431201_158_dialog_content = "เรายังไม่พบสิ่งใดที่จะช่วยเราพิสูจน์ความบริสุทธิ์ของทีน่าได้! ฉันไม่รู้ว่าการบุกเข้าไปในห้องใต้ดินของ Schwab เป็นความคิดที่ถูกต้องหรือไม่",
  ui_story_5043_50431201_159_dialog_content = "ถ้าคุณเชื่อว่าเธอบริสุทธิ์จริง ๆ ความจริงก็ต้องอยู่ที่นี่ในบ้านของชวาบที่ไหนสักแห่ง",
  ui_story_5043_50431201_160_dialog_content = "แม้ว่าเขาจะเป็นเพียงเบี้ยตัวหนึ่งในเรื่องทั้งหมดนี้ มันต้องมีเงื่อนงำบางอย่างหลงเหลืออยู่",
  ui_story_5043_50431201_161_dialog_content = "ถ้ายังไม่เจอ ก็เพราะเรายังขุดไม่ลึกพอ!",
  ui_story_5043_50431201_162_dialog_content = "... คุณถูก. กลับไปไม่ได้แล้ว... ไปดูกันว่ามีอะไรอยู่ในห้องใต้ดินนั้น!",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5043_50431201_164_dialog_content = "มันดำทะมึนอยู่ในนั้น... ฉันมองไม่เห็นอะไรเลย!",
  ui_story_5043_50431201_165_dialog_content = "ดูเหมือนมีบันไดทอดลงไป เราสามารถลองคลำทางไปข้างหน้า...",
  ui_story_5043_50431201_166_dialog_content = "ทีน่า? ทีน่า! คุณอยู่ในนี้ไหม",
  ui_story_5043_50431201_167_dialog_content = "เดี๋ยวก่อน... ฉันคิด PlayerName มีพลังจิตบ้างไหม?",
  ui_story_5043_50431201_168_dialog_content = "คุณสามารถใช้มันเพื่อรับรู้สิ่งที่อยู่ข้างหน้าได้หรือไม่?",
  ui_story_5043_50431201_169_dialog_content = "ฉันสามารถลองใช่",
  ui_story_5043_50431201_170_option_content = "บูสต์พลัง",
  ui_story_5043_50431201_171_dialog_content = "การมี Caelestite อยู่ข้างกายสามารถพิสูจน์ได้ว่ามีประโยชน์ในบางครั้งใช่หรือไม่?",
  ui_story_5043_50431201_172_dialog_content = "ดี? คุณเห็นอะไร?",
  ui_story_5043_50431201_173_dialog_content = "มีแหล่งกำเนิดแสงที่เราสามารถใช้ เช่น เทียนหรือคบไฟไหม?",
  ui_story_5043_50431201_174_dialog_content = "ห้องใต้ดินนี้ดูเหมือนจะลงไปได้ไกลจริงๆ...",
  ui_story_5043_50431201_175_dialog_content = "...ห๊ะ? มีบางอย่างกำลังมาทางเรา!",
  ui_story_5043_50431201_176_dialog_content = "นั่น...",
  ui_story_5043_50431201_177_dialog_content = "เกรอะ—",
  ui_story_5043_50431201_178_dialog_content = "วะฮะฮะฮะฮะ—",
  ui_story_5043_50431201_179_dialog_content = "มันคืออะไร? คุณเห็นอะไร?!",
  ui_story_5043_50431201_180_dialog_content = "วิ่ง! กลับไปที่ทางเข้า!",
  ui_story_5043_50431201_181_dialog_content = "ฝูง Eclipsites กำลังพุ่งเข้าหาเรา!",
  ui_story_5043_50431202_1_dialog_content = "กรร...",
  ui_story_5043_50431202_2_dialog_content = "สุริยุปราคา? สิ่งมีชีวิตสกปรกเหล่านี้กำลังทำอะไรในห้องใต้ดินของ Schwab!",
  ui_story_5043_50431202_3_dialog_content = "เห็นได้ชัดว่าพวกขุนนางชอบมากกว่าสิ่งที่ดีกว่าในชีวิต!",
  ui_story_5043_50431202_4_dialog_content = "อย่ารวมพวกเราทั้งหมดด้วยการใส่ร้ายชั่วช้าของคุณ! ฉันจะให้คุณรู้ว่าครอบครัวของฉันจะไม่มีวันเอาสัตว์ประหลาดที่น่าขยะแขยงแบบนี้มาไว้ในบ้านของเรา!",
  ui_story_5043_50431202_5_dialog_content = "พอเถอะพวกนาย! พวกเขาใกล้เข้ามาแล้ว!",
  ui_story_5043_50431202_6_dialog_content = "ฉันจะระงับ Eclipsites! คุณสองคนออกไปจากที่นี่ให้เร็วที่สุดเท่าที่จะทำได้!",
  ui_story_5043_50431202_7_dialog_content = "A-คุณแน่ใจเหรอ?",
  ui_story_5043_50431202_8_dialog_content = "แน่นอนฉัน! อย่าประเมินผู้ตัดสินของ Lumopolis ต่ำไป!",
  ui_story_5043_50431202_9_dialog_content = "เอาล่ะ ไอ้พวก Eclipsite... รับนี่ไป!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>ชน-!</color>",
  ui_story_5043_50431202_11_dialog_content = "โอ้ที่รัก! คุณเพิ่งทำโคมระย้าของพวกเขาพัง!",
  ui_story_5043_50431202_12_dialog_content = "ดูเหมือนว่าจะทำมาจากผลึกแห่งนอร์ธแลนด์? หมายความว่ามันเป็นการแข่งขันที่ค่อนข้างแพง",
  ui_story_5043_50431202_13_dialog_content = "อ๊ะ! คิดว่าเค้าจะขอจ่ายไหม...?",
  ui_story_5043_50431202_14_dialog_content = "ช่วงนี้กลุ้มใจเรื่องเงิน?! มุ่งเน้นไปที่ Eclipsites!",
  ui_story_5043_50431202_15_dialog_content = "พวกเขามาอีกแล้ว...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>ชน-!</color>",
  ui_story_5043_50431202_17_dialog_content = "ยอดเยี่ยม! ตอนนี้โต๊ะน้ำชาของพวกเขาก็พังเช่นกัน!",
  ui_story_5043_50431202_18_dialog_content = "และตัดสินจากฝีมืออันประณีตของมัน ฉันแน่ใจว่า Schwab กำลังจะนอนไม่หลับเช่นกัน",
  ui_story_5043_50431202_19_dialog_content = "ฉันขอโทษจริงๆ! แต่ฉันไม่คิดว่าฉันเป็นคนจ่าย เพราะมันเป็นความผิดของ Eclipsites ตั้งแต่แรก...",
  ui_story_5043_50431202_20_dialog_content = "นี่ไม่ใช่เวลานะ คุณสองคน! ดูนั่นสิ ประตู!",
  ui_story_5043_50431202_21_dialog_content = "เราต้องออกไปเดี๋ยวนี้!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>10 นาทีให้หลัง...</color>",
  ui_story_5043_50431202_23_dialog_content = "เราค้นหาทั่วบริเวณที่ดินแล้ว อาจารย์ชวาบ... แต่ก็ยังไม่มีวี่แววของผู้บุกรุก",
  ui_story_5043_50431202_24_dialog_content = "วุ่นวายอะไรอย่างนี้... ใครหรืออะไรทำให้เกิดเรื่องทั้งหมดนี้ขึ้นได้?",
  ui_story_5043_50431202_25_dialog_content = "... คุณแน่ใจนะว่าไม่เห็นผู้บุกรุก?",
  ui_story_5043_50431202_26_dialog_content = "ใช่หัวหน้า. ทุกอย่างดูเหมือนจะปลอดภัย อย่างน้อยก็ในตอนนี้",
  ui_story_5043_50431202_27_dialog_content = "เป็นไปได้ค่อนข้างมากที่ผู้ร้ายหรือผู้กระทำผิดเป็นผู้เชี่ยวชาญ... หากพวกเขาทิ้งเงื่อนงำใด ๆ ไว้เบื้องหลัง เรายังหาพวกเขาไม่พบ",
  ui_story_5043_50431202_28_dialog_content = "บางทีมันอาจจะเป็นการดีที่สุดที่จะ... ปล่อยสิ่งนี้ไว้ที่ Hall of Justice?",
  ui_story_5043_50431202_29_dialog_content = "แน่นอน พวกเขาจะสอบสวนเรื่องนี้ด้วยความจริงจังเนื่องจากสถานะของคุณ?",
  ui_story_5043_50431202_30_dialog_content = "การสืบสวน...",
  ui_story_5043_50431202_31_dialog_content = "ไม่ นั่นไม่จำเป็น",
  ui_story_5043_50431202_32_dialog_content = "มันเป็นเพียงแค่เฟอร์นิเจอร์ไม่กี่ชิ้นเท่านั้น สิ่งที่เสียไปสามารถทดแทนได้ง่าย",
  ui_story_5043_50431202_33_dialog_content = "สำหรับตอนนี้ ให้ใครสักคนมาสะสางความยุ่งเหยิงนี้ทันที",
  ui_story_5043_50431202_34_dialog_content = "ใช่ ท่านชวาบ!",
  ui_story_5043_50431202_35_dialog_content = "(ประตูห้องใต้ดินเปิดอยู่...)",
  ui_story_5043_50431202_36_dialog_content = "(ฉันปลดล็อคก่อนออกไปทานอาหารเย็นหรือเปล่า?)",
  ui_story_5043_50431202_37_dialog_content = "(สำหรับฉันที่ทำผิดพลาดโง่เขลาเช่นนี้... มันแทบจะหยั่งไม่ถึงเลย)",
  ui_story_5043_50431202_38_dialog_content = "(คืนนี้ฉันควรเข้านอนแต่หัวค่ำ ฉันต้องสมองปลอดโปร่งสำหรับการพิจารณาคดีในวันพรุ่งนี้)",
  ui_story_5043_50431202_39_dialog_content = "เฮ้อ เกิดอะไรขึ้นบนโลกนี้?",
  ui_story_5043_50431202_40_dialog_content = "วายร้ายประเภทไหนที่บุกเข้าไปในบ้านของใครบางคนเพียงเพื่อทำลายโคมระย้าและโต๊ะน้ำชาของพวกเขา?",
  ui_story_5043_50431202_41_dialog_content = "ถึงกระนั้น... เศษที่แตกเหล่านี้อาจได้ราคาที่ดีกับตัวแทนจำหน่ายขยะที่เหมาะสม",
  ui_story_5043_50431202_42_dialog_content = "แฮ่ก แฮ่ก...",
  ui_story_5043_50431202_43_dialog_content = "(ในที่สุด...ในที่สุดก็ออก!)",
  ui_story_5043_50431202_44_dialog_content = "มีใครตามเราทันไหม?",
  ui_story_5043_50431202_45_dialog_content = "ฉันไม่คิดอย่างนั้น ดูเหมือนว่าชายฝั่งจะชัดเจน",
  ui_story_5043_50431202_46_dialog_content = "ทสค. ช่างน่าอายเสียนี่กระไร เสียเวลาทั้งวันไปกับเรื่องไร้สาระ",
  ui_story_5043_50431202_47_dialog_content = "ที่แย่กว่านั้นก็คือ เราหาทีน่าไม่เจอ หรือแม้แต่ร่องรอยเล็กๆ น้อยๆ ที่จะช่วยเธอได้",
  ui_story_5043_50431202_48_dialog_content = "ตอนนี้เธอควรจะผ่านการทดลองนี้ไปได้อย่างไร?",
  ui_story_5043_50431202_49_dialog_content = "เราทำสุดความสามารถแล้ว... สิ่งที่เหลืออยู่คือให้เราทำหน้าที่ตัดสินให้สำเร็จ",
  ui_story_5043_50431202_50_dialog_content = "ก่อนที่การพิจารณาคดีจะเริ่มขึ้น เราจำเป็นต้องคำนึงถึงทุกสิ่งที่เกิดขึ้นในวันนี้",
  ui_story_5043_50431202_51_dialog_content = "เป็นไปได้ว่าเบาะแสที่เรากำลังมองหาซ่อนอยู่ในรายละเอียดที่ไหนสักแห่ง",
  ui_story_5043_50431202_52_dialog_content = "เป็นไปโดยไม่ได้บอกว่าเราจะทำหน้าที่ของเราให้ดีที่สุด อย่างไรก็ตาม...",
  ui_story_5043_50431202_53_dialog_content = "หากปราศจากการพิสูจน์ที่แน่ชัด เราก็ไม่มีอำนาจเหมือนใคร ๆ ในการเปลี่ยนแปลงผลการพิจารณาคดี",
  ui_story_5043_50431202_54_dialog_content = "ไม่ต้องพูดถึง เราไม่รู้เลยว่า Schwab ยังมีลูกเล่นอะไรอีกบ้าง",
  ui_story_5043_50431202_55_dialog_content = "การไปพิจารณาคดีกับเขาเช่นนี้คงสิ้นหวัง พูดน้อย",
  ui_story_5043_50431202_56_dialog_content = "มีทางชนะมากกว่าหนึ่งทาง มาติเยอ",
  ui_story_5043_50431202_57_dialog_content = "เราอาจไม่มีการ์ดทั้งหมดที่เราต้องการในมือ แต่นั่นไม่ได้หมายความว่าเรายังออกจากเกม",
  ui_story_5043_50431202_58_dialog_content = "มาย มาย รู้สึกมั่นใจในตัวเองมากเลยใช่ไหม?",
