  ui_story_5043_50431301_93_dialog_content = "คุณเห็นไหมว่าทีน่าต้องทนทุกข์ทรมานจากอาการนอนไม่หลับมากเกินไป โรงพยาบาลทุกแห่งใน Lumopolis สามารถรับรองสิ่งนี้ได้เช่นกัน",
  ui_story_5043_50431301_94_dialog_content = "เป็นผลให้เธอสามารถตื่นได้นานที่สุดในแต่ละวันคือประมาณสี่ชั่วโมง!",
