  ui_story_5043_50431301_108_dialog_content = "เช่นเดียวกับเหตุการณ์แรก มีหลักฐานเพียงพอที่พิสูจน์ว่า Tina Campbell ไม่ได้อยู่ในที่เกิดเหตุ",
