  ui_story_5043_50431301_111_dialog_content = "ข้าพเจ้า ข้าพเจ้าในฐานะผู้พิพากษาที่เคารพนับถือของศาลยุติธรรม เราทุกคนไม่ได้อยู่ข้างเดียวกัน ผู้ทรงเกียรติใช่หรือไม่?",
