  ui_story_5043_50431302_12_dialog_content = "ในที่สุดเมื่อฉันไปถึงรูปปั้น ฉันถูกซุ่มโจมตีโดย Eclipsites อีกกลุ่มหนึ่ง",
  ui_story_5043_50431302_13_dialog_content = "ในขณะที่เรากำลังต่อสู้กับ Eclipsites ผู้ร้ายก็มีโอกาสที่ดีที่จะโจมตี",
  ui_story_5043_50431302_14_dialog_content = "ฉวยโอกาสจากความโกลาหลโดยรอบ พวกเขายื่นมือที่สวมถุงมือออกมาและทุบศีรษะของรูปปั้นแตก",
  ui_story_5043_50431302_15_dialog_content = "ฉันสามารถจับมือพวกเขาได้ แต่ผู้ร้ายซ่อนตัวอยู่ใน Eclipsites ซึ่งทำให้ฉันไม่สามารถมองเห็นใบหน้าหรือร่างกายของพวกเขาได้อย่างชัดเจน",
  ui_story_5043_50431302_16_dialog_content = "ในที่สุดคนร้ายก็ดิ้นหลุดจากการเกาะกุมของฉันและหนีไปได้ โดยทิ้งถุงมือไว้เพียงข้างเดียว...",
  ui_story_5043_50431302_17_dialog_content = "ถุงมือที่ให้ไว้เป็นหลักฐานสำคัญในคดีครับ",
  ui_story_5043_50431302_18_dialog_content = "เลดี้คาร์ลีนและผู้พิพากษามาติเยอทำงานสั้น ๆ เกี่ยวกับสุริยุปราคาหลังจากนั้นไม่นาน แต่ผู้ร้ายไม่ปรากฏให้เห็น",
  ui_story_5043_50431302_19_dialog_content = "เมื่อฝุ่นสงบลง ในที่สุดผู้พิพากษา Tina ก็ปรากฏตัวอีกครั้งและเข้าร่วมกับเรา",
  ui_story_5043_50431302_20_dialog_content = "และนั่น ท่านสุภาพบุรุษและสุภาพสตรีในราชสำนัก คือเรื่องราวทั้งหมดของเหตุการณ์ที่เกี่ยวข้องกับการตัดศีรษะของรูปปั้น",
  ui_story_5043_50431302_21_dialog_content = "และบัญชีที่ใช้ถ้อยคำดีมากในตอนนั้น ขอบคุณสำหรับการมีส่วนร่วมของคุณ ผู้พิพากษาลีน",
  ui_story_5043_50431302_22_dialog_content = "ด้วยเหตุนี้ จึงมีเหตุผลว่าเจ้าของถุงมือเป็นผู้กระทำความผิด",
  ui_story_5043_50431302_23_dialog_content = "ในที่สุดก็เป็นเหตุผลที่ทำให้เราจับกุมจำเลย Tina Campbell",
  ui_story_5043_50431302_24_dialog_content = "ขออภัย ท่านผู้มีเกียรติ... แต่คุณกำลังด่วนสรุป",
  ui_story_5043_50431302_25_dialog_content = "ว่าไงนะ",
  ui_story_5043_50431302_26_dialog_content = "จากข้อมูลที่เรารวบรวมในที่เกิดเหตุเกี่ยวกับผู้กระทำความผิด—",
  ui_story_5043_50431302_27_dialog_content = "เรารู้ว่าผู้ร้ายสามารถทุบหัวของรูปปั้นด้วยมือเปล่าในขณะที่สวมถุงมือนั้น",
  ui_story_5043_50431302_28_dialog_content = "คนที่คุณจับ ในทางกลับกัน...",
  ui_story_5043_50431302_29_dialog_content = "เป็นเพียงหญิงสาวผู้เป็นเจ้าของถุงมือโดยชอบธรรม",
  ui_story_5043_50431302_30_dialog_content = "หากคุณเปรียบเทียบทั้งสองอย่างใกล้ชิดมากขึ้น คุณจะพบความไม่สอดคล้องกันมากกว่าสิ่งอื่นใด",
  ui_story_5043_50431302_31_dialog_content = "ฉันรู้สึกว่าคุณคิดมากไปเอง ผู้พิพากษาลีน",
  ui_story_5043_50431302_32_dialog_content = "มันไม่สมเหตุสมผลหรือไม่ที่เจ้าของถุงมือคือบุคคลที่มีแนวโน้มมากที่สุดที่จะสวมมันในที่เกิดเหตุ?",
