  ui_story_5043_50431302_34_dialog_content = "ผู้พิพากษาทีน่าดูเหมือนว่าเธอสามารถบดหัวของรูปปั้นด้วยมือเปล่าได้หรือไม่?",
  ui_story_5043_50431302_35_dialog_content = "โอ้? มุมใหม่?",
  ui_story_5043_50431302_36_dialog_content = "เมื่อคุณลองคิดดูดีๆ เด็กผู้หญิงตัวเล็ก ๆ จะทำลายรูปปั้นด้วยมือเปล่าได้อย่างไร?",
  ui_story_5043_50431302_37_dialog_content = "ดูเหมือนว่าคุณจะหลงทางอยู่ในกระบวนการคิดของคุณเอง ผู้พิพากษาลีน",
  ui_story_5043_50431302_38_dialog_content = "คุณลืมสิ่งที่คุณพูดเมื่อสองนาทีก่อนไปแล้วหรือ",
