  ui_story_5043_50431302_41_dialog_content = "แต่สุดท้ายก็คือ <color=#FFB400>ปลิวเป็นชิ้นเล็กชิ้นน้อยด้วยกำปั้นของทีน่า</color>.",
  ui_story_5043_50431302_42_dialog_content = "แน่นอนว่าคุณรู้จักเพื่อนร่วมงานของคุณดีกว่านั้น เพราะเธอคือผู้สืบทอดหัตถ์ศักดิ์สิทธิ์ของตระกูลแคมป์เบลล์",
  ui_story_5043_50431302_43_dialog_content = "สำหรับคนที่สามารถกำจัด Eclipsite ได้อย่างสมบูรณ์ด้วยหมัดเดียว หัวของรูปปั้นก็ไม่น่าจะมีปัญหาแต่อย่างใด",
