  ui_story_5043_50431302_45_dialog_content = "พ่อหนุ่ม คุณต้องคิดให้มากกว่านี้สักนิดในการหักเงินของคุณ",
  ui_story_5043_50431302_46_dialog_content = "(ฉันเดาว่าเขาแค่ขาดเครื่องหมาย ฮะ?)",
  ui_story_5043_50431302_47_dialog_content = "(หากเพียง Leyn สามารถก้าวนำหน้าศัตรูไปเพียงก้าวเล็กๆ และพบบางสิ่งที่หลุดจากสายตาของพวกเขา...)",
  ui_story_5043_50431302_48_dialog_content = "อา ใช่... ทีน่าสืบทอดหัตถ์ศักดิ์สิทธิ์",
