  ui_story_5043_50431302_50_dialog_content = "ถูกต้อง. มันเป็นข้อสรุปเชิงตรรกะเพียงอย่างเดียว",
  ui_story_5043_50431302_51_dialog_content = "และในขณะที่ฉันต้องปรบมือให้คุณสำหรับวิธีการวิเคราะห์ที่เข้มงวดของคุณ ผู้พิพากษาเลย์น...",
