  ui_story_5043_50431302_55_dialog_content = "ทีน่าใช้หัตถ์ศักดิ์สิทธิ์ทุบหัวรูปปั้น",
  ui_story_5043_50431302_56_dialog_content = "... เข้าประเด็นเลย ผู้พิพากษาลีน คุณกำลังพยายามจะพูดอะไร",
  ui_story_5043_50431302_57_dialog_content = "เมื่อมาถึงข้อสรุปนี้แล้ว สิ่งที่ต้องทำคือหันกลับมามองอีกครั้งเพื่อตระหนักถึงความจริง",
  ui_story_5043_50431302_58_dialog_content = "ถุงมือนั่น หลักฐานสำคัญชิ้นนั้น ไม่ใช่เครื่องพิสูจน์ความผิดของเธอที่หักล้างไม่ได้ แต่เป็นเครื่องพิสูจน์ความบริสุทธิ์ของเธอ!",
