  ui_story_5043_50431302_61_dialog_content = "เป็นไปได้ว่าถุงมือนั้นถูกชำระล้างจากหลักฐานที่กล่าวหาในขณะที่อยู่ในความครอบครองของคุณ ผู้มีเกียรติ...",
  ui_story_5043_50431302_62_dialog_content = "แต่ไม่เป็นไร ตราบใดที่ยังเป็นถุงมือเดิมจากสถานที่เกิดเหตุ เราแน่ใจได้ใช่ไหม ท่านผู้มีเกียรติ?",
  ui_story_5043_50431302_63_dialog_content = "คุณกำลังสงสัยในความสามารถของฉันในการเก็บรักษาหลักฐานคดี ซึ่งเป็นหนึ่งในความรับผิดชอบขั้นพื้นฐานที่สุดของ Hall of Justice หรือไม่!",
