  ui_story_5043_50431302_82_dialog_content = "ตอนนี้เรารู้แล้วว่านี่ไม่ใช่ถุงมือที่ปิดหัตถ์ศักดิ์สิทธิ์ของทีน่า ฉันสงสัยว่าบทสรุปจะเป็นอย่างไร",
