  ui_story_5043_50431302_98_dialog_content = "คุณเป็นหนี้บุญคุณเรามากทีเดียวรู้ไหม? โดยเฉพาะอย่างยิ่งสำหรับมือใหม่ทั่วไปของเรา",
  ui_story_5043_50431302_99_dialog_content = "สำหรับคดีสำคัญคดีแรกของเขา เขาทำได้ดีอย่างน่าทึ่ง",
  ui_story_5043_50431302_100_dialog_content = "ฉันไม่เห็นด้วยมากกว่านี้! ขอบคุณทั้งคู่มากสำหรับทุกสิ่งที่คุณทำเพื่อฉัน!",
  ui_story_5043_50431302_101_dialog_content = "ฉันภูมิใจที่จะเรียกคุณว่าเพื่อนร่วมงานที่รักที่สุด!",
  ui_story_5043_50431302_102_dialog_content = "เฮ้! นี่มันหมายความว่ายังไงกันเนี่ย?!",
  ui_story_5043_50431302_103_dialog_content = "หลังจากเสียเวลาไปครึ่งวันกับการเถียงตัวเองเสียงแหบๆ นี่จะบอกว่าคุณจับผิดคนแล้วเหรอ?!",
  ui_story_5043_50431302_104_dialog_content = "...",
  ui_story_5043_50431302_105_dialog_content = "เหลือเชื่อ. เหลือเชื่อ!",
  ui_story_5043_50431302_106_dialog_content = "บังคับให้ฉันนั่งพิจารณาทั้งหมดเพียงเพื่อบอกว่าเรากลับมาที่เราเริ่มต้น?",
  ui_story_5043_50431302_107_dialog_content = "ฉันบอกคุณมากก่อน! ความอดทนของฉันถึงขีดสุด!",
  ui_story_5043_50431302_108_dialog_content = "หากเจ้าไม่ปิดคดีนี้ภายในสิ้นวัน ข้าจะจัดการคดี Romance Division ของศาลนี้ให้สิ้นซาก!!!",
  ui_story_5043_50431302_109_dialog_content = "อย่ารีบร้อนเลยคนดีของฉัน ดังที่ได้กล่าวมาแล้ว เราได้พูดคุยกันเพียงครึ่งเดียวของเรื่อง",
  ui_story_5043_50431302_110_dialog_content = "ครึ่ง...?",
  ui_story_5043_50431302_111_dialog_content = "นั่งตรงนี้กับเรา ผู้พิพากษาทีน่า",
  ui_story_5043_50431302_112_dialog_content = "ถึงเวลาแล้วที่คนอื่นจะต้องทำหน้าที่เป็นจำเลยในตอนนี้",
  ui_story_5043_50431302_113_dialog_content = "ฮะ? หมายถึงใคร...?",
  ui_story_5043_50431302_114_dialog_content = "หลังจากการสืบสวนคดีอย่างละเอียดถี่ถ้วนของแผนกโรมานซ์และหลักฐานทั้งหมดที่ได้รับ ฉัน ผู้พิพากษาเลย์น—",
  ui_story_5043_50431302_115_dialog_content = "และฉันผู้พิพากษา Matthieu—",
  ui_story_5043_50431302_116_dialog_content = "ขอตั้งข้อหานาย Schwab Salar ในข้อหาทำลายทรัพย์สินสาธารณะและทำลายความรัก!",
  ui_story_5043_50431302_117_dialog_content = "หัวหน้าผู้พิพากษา Schwab ได้โปรดยืนหยัด",
  ui_story_5043_50431302_118_dialog_content = "อะไร เขากล่าวหา Schwab?!",
  ui_story_5043_50431302_119_dialog_content = "อย่าบอกนะว่านี่เป็นส่วนหนึ่งของแผนด้วย PlayerName?!",
  ui_story_5043_50431302_120_dialog_content = "เอ่อ...",
  ui_story_5043_50431302_121_dialog_content = "เรามีข้อสงสัยเกี่ยวกับ Schwab เมื่อวานนี้ แต่...",
  ui_story_5043_50431302_122_dialog_content = "ฉันไม่รู้ว่าพวกเขาจะกล่าวหาอะไรเขาจริงๆ...",
  ui_story_5043_50431302_123_dialog_content = "คุณและคนอื่นๆ จัดการเพื่อหาหลักฐานปรักปรำหรือไม่?",
  ui_story_5043_50431302_124_dialog_content = "ไม่รู้เลยสักนิด...",
  ui_story_5043_50431302_125_dialog_content = "กล่าวหาฉันใช่ไหม",
  ui_story_5043_50431302_126_dialog_content = "คุณรู้หรือไม่ว่าคุณกำลังทำอะไรอยู่ ผู้พิพากษาเลย์น?",
  ui_story_5043_50431302_127_dialog_content = "ผมแค่ทำตามหน้าที่ครับท่าน",
  ui_story_5043_50431302_128_dialog_content = "หืม คุณมีความหวังที่ดีกว่านั้น",
  ui_story_5043_50431302_129_dialog_content = "เพราะตอนนี้ฉันสามารถบอกคุณได้ว่า ฉันมีข้ออ้างที่ไม่อาจปฏิเสธได้สำหรับแต่ละเหตุการณ์จากสามเหตุการณ์นี้",
  ui_story_5043_50431302_130_dialog_content = "ไม่ว่าการไต่สวนโง่ๆ นี้อาจนำไปสู่ที่ใด จงรู้ไว้เถิดว่า Hall of Justice ทั้งหมดจะยืนยันเรื่องราวของฉัน",
  ui_story_5043_50431302_131_dialog_content = "ฉันไม่มีอะไรจะพูดเพิ่มเติมเกี่ยวกับข้อกล่าวหาที่ไร้เหตุผลของคุณในตอนนี้",
  ui_story_5043_50431302_132_dialog_content = "วางใจได้ ผู้พิพากษา Schwab คำถามของฉันจะสั้นและเรียบง่าย",
  ui_story_5043_50431302_133_dialog_content = "ข้าพเจ้าก็สามารถยืนยันถึงข้อแก้ตัวอันแนบแน่นของคุณสำหรับการกระทำผิดทั้งสามกรณีในกรณีนี้",
  ui_story_5043_50431302_134_dialog_content = "และคุณยังปฏิเสธที่จะถอนข้อกล่าวหาที่ไร้จุดหมายของคุณ?",
  ui_story_5043_50431302_135_dialog_content = "ถูกต้องครับท่าน เพราะผู้ร้ายไม่จำเป็นต้องอยู่ในที่เกิดเหตุ",
  ui_story_5043_50431302_136_dialog_content = "ฉันขอพยานใหม่ได้ไหม",
  ui_story_5043_50431302_137_dialog_content = "พยาน?",
  ui_story_5043_50431302_138_dialog_content = "โปรดเข้าใกล้อัฒจันทร์และเตรียมสาบานตน",
  ui_story_5043_50431302_139_dialog_content = "(เขาพบพยานเรื่องนี้เมื่อใด)",
  ui_story_5043_50431302_140_dialog_content = "(อยากรู้ว่าใคร...)",
  ui_story_5043_50431302_141_dialog_content = "ค-ฉัน...",
  ui_story_5043_50431302_142_dialog_content = "คุยตอนนี้ได้ไหม?",
  ui_story_5043_50431302_143_dialog_content = "สุริยุปราคา! และที่พูดได้ไม่น้อย!",
  ui_story_5043_50431302_144_dialog_content = "ที-โตโต้?!?",
  ui_story_5043_50431302_145_dialog_content = "ฮะ? เขามาทำอะไรที่นี่!",
  ui_story_5043_50431302_146_dialog_content = "มี Eclipsite เป็นพยาน... เขากำลังคิดอะไรอยู่?",
  ui_story_5043_50431302_147_dialog_content = "เสียสติไปแล้ว?! เจ้ากล้าดียังไงนำสัตว์โสโครกนั่นเข้าไปในศาลอันศักดิ์สิทธิ์ของ Hall of Justice!",
  ui_story_5043_50431302_148_dialog_content = "เจ้าพยายามบ่อนทำลายสิ่งที่เราสร้างไว้หรือไม่!",
  ui_story_5043_50431302_149_dialog_content = "ไม่มีเหตุผลที่จะต้องกังวล เราได้รับการยืนยันโดยไม่ต้องสงสัยเลยว่า Eclipsite นี้ไม่เป็นอันตรายอย่างสมบูรณ์",
