  ui_story_5043_50431302_151_dialog_content = "ฉันเชื่อว่าเราทุกคนมาที่นี่ด้วยเหตุผลเดียวกัน ใช่ไหม",
  ui_story_5043_50431302_152_dialog_content = "อืมมม... ถ้าคำให้การของเขาส่งเสริมการพิจารณาคดี ฉันคิดว่ามันยอมรับได้",
