  ui_story_5043_50431302_154_dialog_content = "นี่อาจไม่เคยเกิดขึ้นมาก่อนในประวัติศาสตร์ทั้งหมดของ Hall of Justice... ฉันสงสัยว่าเขาจะให้คำให้การแบบไหน?",
