  ui_story_5043_50431302_161_dialog_content = "ฮึ่ม! สหพันธ์อิลลูมินาทั่วไปแค่ไหนในการตะลุยงานวิจัยที่ยากจะบรรยายเช่นนี้!",
  ui_story_5043_50431302_162_dialog_content = "ว้าว... Universese ของเขาราบรื่นขึ้นมากตั้งแต่ครั้งสุดท้ายที่เราคุยกัน?",
  ui_story_5043_50431302_163_dialog_content = "ตั้งแต่นั้นเป็นต้นมา การเชื่อมต่อของฉันกับ Eclipsites อื่นก็เริ่มอ่อนแอลง...",
  ui_story_5043_50431302_164_dialog_content = "ฉันไม่สามารถควบคุมพวกเขาได้อีกต่อไป แต่พวกเขาก็ควบคุมฉันไม่ได้เช่นกัน!",
  ui_story_5043_50431302_165_dialog_content = "การใช้ชีวิตท่ามกลาง Eclipsites อื่น ๆ นั้นยากขึ้นเรื่อย ๆ... ไม่มีทางที่ฉันจะทำงานให้เสร็จโดยไม่มีภาวะแทรกซ้อนอย่างต่อเนื่อง...",
