  ui_story_5043_50431302_170_dialog_content = "หลังจากนั้นไม่นาน ฉันก็เริ่มเรียนรู้ทุกสิ่งที่ทำได้เกี่ยวกับชาวออโรเรียน ภาษาของพวกเขา วัฒนธรรมของพวกเขา...",
  ui_story_5043_50431302_171_dialog_content = "ฉันเดินทางไปทั่วแผ่นดิน หางานทำทุกที่ที่ทำได้ แต่ไม่ว่าจะไปที่ไหน ฉันก็โดนไล่ออกอยู่ดี...",
