  ui_story_5043_50431302_179_dialog_content = "ขอบคุณโตโต้ นั่นจะเป็นการแนะนำ",
  ui_story_5043_50431302_180_dialog_content = "โปรดบอกเหตุผลของคุณที่มาที่นี่และทำหน้าที่เป็นพยานในการพิจารณาคดีในวันนี้ให้ศาลทราบ",
  ui_story_5043_50431302_181_dialog_content = "II มารายงาน Aurorian สำหรับพฤติกรรมที่ผิดกฎหมาย!",
  ui_story_5043_50431302_182_dialog_content = "แล้วใครล่ะที่จะเป็น?",
  ui_story_5043_50431302_183_dialog_content = "ผู้ชายคนนั้นนั่นเอง! ผู้ซึ่งนั่งอยู่เหนือใครๆ คนที่ชื่อ Schwab!",
  ui_story_5043_50431302_184_dialog_content = "เธอ...",
  ui_story_5043_50431302_185_dialog_content = "เขาก่ออาชญากรรมอะไร",
  ui_story_5043_50431302_186_dialog_content = "H-เขาเป็นคนทำลายรูปปั้น!",
  ui_story_5043_50431302_187_dialog_content = "เขามีคำแก้ตัวที่พิสูจน์ว่าเขาไม่เคยอยู่ในที่เกิดเหตุ ดังนั้น อะไรทำให้คุณแน่ใจได้ว่าเขาเป็นผู้กระทำความผิด?",
