  ui_story_5043_50431401_1_dialog_content = "ควบคุม Eclipsites?!",
  ui_story_5043_50431401_2_dialog_content = "สวรรค์ของฉัน! คุณรู้หรือไม่ว่ามีความคิดว่าคุณกำลังหมายถึงอะไร?",
  ui_story_5043_50431401_3_dialog_content = "การคบหากับ Eclipsites เป็นอาชญากรรมที่ร้ายแรงที่สุดใน Lumopolis!",
  ui_story_5043_50431401_4_dialog_content = "จุ๊! ช่างเป็นพยานหลักฐานที่ไร้สาระสิ้นดี!",
