  ui_story_5043_50431401_6_dialog_content = "ช่างเป็นการเยาะเย้ยความยุติธรรม! คำให้การของคนขี้เมาจะกักเก็บน้ำได้มากกว่า Eclipsite ที่เหม็น!",
  ui_story_5043_50431401_7_dialog_content = "ทักษะของคุณยังขาดอยู่มาก Leyn!",
  ui_story_5043_50431401_8_dialog_content = "อย่างนั้นเหรอ? ถ้าอย่างนั้นฉันน่าจะเอาหนังสือของคุณออกสักหนึ่งหรือสองหน้า ผู้พิพากษาชวาบ?",
  ui_story_5043_50431401_9_dialog_content = "นาย...!",
  ui_story_5043_50431401_10_dialog_content = "ฉันไม่จำเป็นต้องใส่ร้ายคุณเพื่อพิสูจน์ความผิดของคุณ",
  ui_story_5043_50431401_11_dialog_content = "อย่างที่คุณพูด คำให้การของ Eclipsite เดียวนั้นไม่เพียงพอที่จะทำให้คุณมีส่วนรู้เห็นในอาชญากรรมเหล่านี้",
  ui_story_5043_50431401_12_dialog_content = "แต่ถ้า Eclipsite นั้นมีบทบาทพิเศษในคดีนี้ล่ะ?",
  ui_story_5043_50431401_13_dialog_content = "บทบาทพิเศษ...?",
  ui_story_5043_50431401_14_dialog_content = "ถ้าจะใจดีขนาดนั้น โตโต้?",
  ui_story_5043_50431401_15_dialog_content = "ฉันขอโทษ!!!",
  ui_story_5043_50431401_16_dialog_content = "ฉันทำผิด... ฉันจะยอมรับการลงโทษที่นี่และเดี๋ยวนี้!!!",
  ui_story_5043_50431401_17_dialog_content = "หา?",
  ui_story_5043_50431401_18_dialog_content = "คุณหมายถึงอะไรโตโต้? คุณกำลังพูดถึงข้อผิดพลาดอะไร",
  ui_story_5043_50431401_19_dialog_content = "พูดตามตรง ช่วงเวลาหนึ่งมันกล่าวหาหัวหน้าผู้พิพากษา และวินาทีต่อมา มันยอมรับความผิดของตัวเอง...",
  ui_story_5043_50431401_20_dialog_content = "หยุดเสียเวลาและพูดให้ชัดเจน ฉันพูด!",
  ui_story_5043_50431401_21_dialog_content = "S-ขอโทษ! ท-ความจริงก็คือ...",
  ui_story_5043_50431401_22_dialog_content = "ฉันเป็นคนทำลายรูปปั้น!",
  ui_story_5043_50431401_23_dialog_content = "อะไรนะ!",
  ui_story_5043_50431401_24_dialog_content = "ฮะ? แล้วคุณล่ะ?!",
  ui_story_5043_50431401_25_dialog_content = "คุณเป็นคนทำลายภรรยาและคนรักของฉัน?!",
  ui_story_5043_50431401_26_dialog_content = "ใช่ฉันเอง",
  ui_story_5043_50431401_27_dialog_content = "ทำไมเจ้าเน่าน้อย...!",
  ui_story_5043_50431401_28_dialog_content = "ว-เดี๋ยวก่อน! ฉันไม่ได้ตั้งใจ! ฉันถูกบังคับให้!",
  ui_story_5043_50431401_29_dialog_content = "Schwab เป็นคนที่ทำให้ฉันทำทุกครั้ง!",
  ui_story_5043_50431401_30_dialog_content = "ได้โปรดเถอะทุกคน โปรดเมตตาฉันด้วย—!",
  ui_story_5043_50431401_31_dialog_content = "<size=45>อะไร?!?</size>",
  ui_story_5043_50431401_32_dialog_content = "...",
  ui_story_5043_50431401_33_dialog_content = "นี่มันเกิดอะไรขึ้นกันแน่...?",
  ui_story_5043_50431401_34_dialog_content = "ฉัน-เรื่องทั้งหมดมันเริ่มเมื่อสองสัปดาห์ก่อน...",
  ui_story_5043_50431401_35_dialog_content = "ฉันเพิ่งมาถึงลูโมโปลิส และกำลังเตรียมตัวหางาน",
  ui_story_5043_50431401_36_dialog_content = "แต่ลูโมโพลิสนั้นใหญ่มาก และฉันก็ไม่รู้จักถนนดีนัก... กว่าจะรู้ตัวก็เป็นเวลากลางคืนแล้ว",
  ui_story_5043_50431401_37_dialog_content = "หลังจากนั้น ฉัน... ฉันบังเอิญเจอกลุ่ม Eclipsites ใน Lumopolis Courtyard",
  ui_story_5043_50431401_38_dialog_content = "เมื่อเร็ว ๆ นี้มีการพบเห็นกิจกรรม Eclipsite หลายครั้งในเมือง",
  ui_story_5043_50431401_39_dialog_content = "นี่เป็นความจริงอย่างน้อยที่สุด",
  ui_story_5043_50431401_40_dialog_content = "ฉันไม่คิดว่าจะได้พบคนแบบฉันอีกในเมืองนี้ มันรู้สึกแปลก",
  ui_story_5043_50431401_41_dialog_content = "ขณะที่ฉันยืนอยู่ตรงนั้นเพื่อทำความเข้าใจสิ่งต่างๆ พวกเขาคิดว่าฉันเป็นเพียง Eclipsite ที่หลงทางอีกแห่ง",
  ui_story_5043_50431401_42_dialog_content = "พวกเขายืนหยัดมากที่จะให้ฉันเข้าร่วมกลุ่มของพวกเขา",
  ui_story_5043_50431401_43_dialog_content = "แม้จะสับสนแต่ฉันก็เดินตามพวกเขาไปจนในที่สุด...",
  ui_story_5043_50431401_44_dialog_content = "เรามาถึงคฤหาสน์ซาลาร์",
  ui_story_5043_50431401_45_dialog_content = "เฮ้! นั่นคือบ้านของ Schwab!",
  ui_story_5043_50431401_46_dialog_content = "ใช่แล้ว และนั่นคือที่ที่ฉันเห็นเขาเป็นครั้งแรก",
  ui_story_5043_50431401_47_dialog_content = "เป็นสิ่งที่น่าตกใจที่สุดเท่าที่เคยเห็นมา...",
  ui_story_5043_50431401_48_dialog_content = "เขาสั่งให้ Eclipsites ราวกับว่าพวกเขาเป็นทาส",
  ui_story_5043_50431401_49_dialog_content = "และ Eclipsites... พวกเขาเชื่อฟังทุกคำสั่งของเขา!",
  ui_story_5043_50431401_50_dialog_content = "II ไม่มีทางหนีได้... ดังนั้นฉันจึงต้องแสร้งทำเป็นเป็นหนึ่งในนั้น",
  ui_story_5043_50431401_51_dialog_content = "นั่นคือตอนที่เขาขังพวกเราทุกคนไว้ในห้องใต้ดินของ Salar Manor!",
  ui_story_5043_50431401_52_dialog_content = "ห้องใต้ดิน?!",
  ui_story_5043_50431401_53_dialog_content = "ดังนั้นเขาจึงจับ Eclipsites เหล่านั้นเป็นเชลยในนั้นตลอดมา! ไม่น่าแปลกใจ...",
  ui_story_5043_50431401_54_dialog_content = "คุณเคยไปที่นั่นมาก่อนหรือไม่?",
  ui_story_5043_50431401_55_dialog_content = "เอ่อ ฉันไม่คิดว่านี่เป็นเวลาหรือสถานที่ที่เหมาะสมที่จะบอกคุณ...",
  ui_story_5043_50431401_56_dialog_content = "ฉันจะคุยกับคุณเกี่ยวกับเรื่องนี้หลังการทดลอง!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>หยุดเรื่องไร้สาระนี้เดี๋ยวนี้!</size>",
  ui_story_5043_50431401_58_dialog_content = "คุณเชื่อไหมว่าคอดสวัลลอปพ่นออกมาจากปากเจ้าสัตว์ร้ายตัวนี้?",
  ui_story_5043_50431401_59_dialog_content = "ฉันไม่มีเหตุผลที่จะต้องทนกับคำสบประมาทอันน่าหัวเราะนี้อีกต่อไป!!!",
  ui_story_5043_50431401_60_dialog_content = "เราจะดูว่าเป็นการใส่ร้ายเร็วพอหรือไม่ ผู้พิพากษาชวาบ",
  ui_story_5043_50431401_61_dialog_content = "โปรดบอกเราทีว่าเกิดอะไรขึ้นหลังจากนั้น โตโต้",
  ui_story_5043_50431401_62_dialog_content = "ในขณะที่คำให้การของคุณส่วนนี้น่าตกใจ แต่ก็ไม่มีอะไรเกี่ยวข้องกับการตัดศีรษะรูปปั้นต่อเนื่อง",
  ui_story_5043_50431401_63_dialog_content = "โอ้ใช่! ให้ฉันผูกมันกลับไปที่กรณี!",
  ui_story_5043_50431401_64_dialog_content = "นาน ๆ ครั้ง Schwab จะดึงพวกเราบางคนออกจากห้องใต้ดินเพื่อทำตามคำสั่งของเขา",
  ui_story_5043_50431401_65_dialog_content = "II หมดหวังที่จะหนี ดังนั้นฉันจึงกระวนกระวายยิ่งกว่าพี่น้องของฉันเสียอีก",
  ui_story_5043_50431401_66_dialog_content = "และในที่สุด... เขาก็เลือกฉันให้ทำงานอย่างหนึ่ง",
  ui_story_5043_50431401_67_dialog_content = "โดยเฉพาะอย่างยิ่ง... เขาบอกให้ฉันรอจนกว่า Moon Balloon จะลอยขึ้นสู่ท้องฟ้า แล้วค่อยทำลายรูปปั้นด้านล่าง!",
  ui_story_5043_50431401_68_dialog_content = "โอ้! ซึ่งตรงกับความรู้ที่เรามีเกี่ยวกับคดีนี้พอดี!",
  ui_story_5043_50431401_69_dialog_content = "สองครั้งแรกคือรูปปั้นหน้า Hall of Justice และ Meadow Square",
  ui_story_5043_50431401_70_dialog_content = "หน้าศาลาธรรม?!",
  ui_story_5043_50431401_71_dialog_content = "นั่นคือ... คนรักของฉัน!",
  ui_story_5043_50431401_72_dialog_content = "ฉันเสียใจอย่างสุดซึ้งสำหรับการสูญเสียของคุณ คุณไบรอน",
  ui_story_5043_50431401_73_dialog_content = "อาจเป็นเพราะสองครั้งแรกเป็นไปอย่างราบรื่น... แต่ Schwab ถามฉันมากขึ้นเป็นครั้งที่สาม",
  ui_story_5043_50431401_74_dialog_content = "H-เขาบอกฉันว่า...ให้สวมถุงมือประหลาดก่อนที่จะทำลายรูปปั้นที่สาม...",
  ui_story_5043_50431401_75_dialog_content = "นั่นอธิบายถุงมือ!!!",
  ui_story_5043_50431401_76_dialog_content = "และเมื่อฉันทำเสร็จ ฉันก็ต้องทิ้งถุงมือไว้ที่บ้านเกิดเหตุ",
  ui_story_5043_50431401_77_dialog_content = "นั่นคือตอนที่ฉันไปที่ Stairway to the Skies กับกลุ่ม Eclipsites...",
  ui_story_5043_50431401_78_dialog_content = "แต่หลังจากที่ฉันทุบหัวรูปปั้นแตก ผู้พิพากษา Leyn ก็สามารถคว้ามือขวาของฉันไว้ได้...",
  ui_story_5043_50431401_79_dialog_content = "โชคดีที่ฉันสามารถสะบัดมือออกจากถุงมือและวิ่งหนีไปได้... ด้วยเหตุนี้ \"งาน\" ของฉันจึงประสบผลสำเร็จ",
  ui_story_5043_50431401_80_dialog_content = "นี่คือถุงมือที่คุณทิ้งไว้หรือไม่?",
  ui_story_5043_50431401_81_dialog_content = "ใช่! นั่นแหละ!",
  ui_story_5043_50431401_82_dialog_content = "มันเพิ่มขึ้น! ตอนนี้มันรวมกันแล้ว!",
  ui_story_5043_50431401_83_dialog_content = "ปรากฏว่าคำให้การของ Toto สอดคล้องกับหลักฐานที่ให้ไว้ในการพิจารณาคดีนี้",
  ui_story_5043_50431401_84_dialog_content = "ต่อไปให้เรา...",
  ui_story_5043_50431401_85_dialog_content = "ฮึ่ม! \"เข้าแถว\" คุณพูด?",
  ui_story_5043_50431401_86_dialog_content = "\"ประจักษ์พยาน\" ของเสียงของเขาถูกซักซ้อมมาทั้งหมด! เรื่องเล่าจอมปลอม!",
  ui_story_5043_50431401_87_dialog_content = "มีหลักฐานใด ๆ ทั้งสิ้นที่พิสูจน์ว่าสิ่งที่เขาพูดเป็นความจริงแม้แต่ประโยคเดียว?!",
  ui_story_5043_50431401_88_dialog_content = "แม้ว่าเขาจะเต็มใจสารภาพ แต่คุณก็ยังไม่พบว่าคำให้การของเขาน่าเชื่อถือเพียงพอ ผู้พิพากษาชวาบ?",
  ui_story_5043_50431401_89_dialog_content = "ไม่แน่นอน! เพียงเพราะพยานสารภาพไม่ได้หมายความว่าพวกเขาเป็นผู้กระทำความผิด!",
  ui_story_5043_50431401_90_dialog_content = "ฉันมีเหตุผลมากพอที่จะสงสัยว่ามีคนซื้อ Eclipsite นี้เพื่อใส่ร้ายฉัน",
  ui_story_5043_50431401_91_dialog_content = "ท้ายที่สุด การใช้รูปแบบชีวิตที่ด้อยกว่าเพื่อปรักปรำผู้พิพากษาระดับสูงจะเป็นการต่อรอง คุณเห็นด้วยหรือไม่?",
  ui_story_5043_50431401_92_dialog_content = "ว-หมายความว่ายังไง?! B-นอกจากนี้ คุณเป็นคนปรักปรำผม!!",
  ui_story_5043_50431401_93_dialog_content = "ฉันเพิ่งมาที่ลูโมโพลิสเพื่อหางานทำ... ฉันไม่เคยอยากถูกจับตัวและถูกควบคุมเพราะแผนการของคุณ!",
  ui_story_5043_50431401_94_dialog_content = "ถ้ามีคนไม่เปิดประตูห้องใต้ดินทิ้งไว้เมื่อวานนี้ ฉันคงไม่มีวันพบอิสรภาพอีกแล้ว!",
  ui_story_5043_50431401_95_dialog_content = "ฉันเข้าใจแล้ว... ดูเหมือนว่าห้องใต้ดินนี้จะค่อนข้างน่าสนใจ",
  ui_story_5043_50431401_96_dialog_content = "ไร้สาระ! สำออยไร้สาระอีกแล้ว!",
  ui_story_5043_50431401_97_dialog_content = "บ้านของฉันไม่มีห้องใต้ดินทุกชนิด!",
  ui_story_5043_50431401_98_dialog_content = "โอ้ใช่? ทำไมเราไม่ส่งคนไปค้นหาและฟังสิ่งที่พวกเขาพูดล่ะ!",
  ui_story_5043_50431401_99_dialog_content = "ค้นหาบ้านของฉัน? นั่นจะผิดกฎหมาย เจ้าสัตว์ประหลาดโง่เขลา!",
  ui_story_5043_50431401_100_dialog_content = "ความเป็นส่วนตัวของครอบครัว Salar มีสิทธิ์ได้รับการคุ้มครองตามกฎหมายอย่างเต็มที่!",
  ui_story_5043_50431401_101_dialog_content = "แต่จะเป็นไปได้อย่างไร...?",
  ui_story_5043_50431401_102_dialog_content = "ผู้พิพากษา Schwab ถูกต้องอย่างสมบูรณ์ เราไม่มีสิทธิ์ที่จะเริ่มการสอบสวนที่พักส่วนตัวของตระกูลซาลาร์",
  ui_story_5043_50431401_103_dialog_content = "...",
  ui_story_5043_50431401_104_dialog_content = "เว้นแต่ว่าคุณได้พิสูจน์ตัวเองว่ามีความผิด",
