  ui_story_5043_50431401_107_dialog_content = "ฉันแน่ใจว่าคุณก็รู้เช่นกัน ผู้พิพากษาชวาบ ท้ายที่สุดแล้วคำพูดก็ออกมาจากปากคุณเอง...",
  ui_story_5043_50431401_108_dialog_content = "\"เพียงเพราะพยานสารภาพไม่ได้หมายความว่าพวกเขาเป็นผู้กระทำความผิด\"",
  ui_story_5043_50431401_109_dialog_content = "...",
  ui_story_5043_50431401_110_dialog_content = "คุณพูดคำเหล่านั้นเพราะคุณรู้ว่าทุกอย่างขึ้นอยู่กับพวกเขา",
  ui_story_5043_50431401_111_dialog_content = "ทันทีที่ Hall of Justice พบว่าเขามีความผิด ทุกสิ่งที่เขาพูดจะถูกตรวจสอบในระดับสูงสุด",
  ui_story_5043_50431401_112_dialog_content = "นั่นเป็นเพราะคำให้การของเขาเป็นการยอมรับความผิดด้วย",
  ui_story_5043_50431401_113_dialog_content = "และถ้าศาลยอมรับคำให้การของ Eclipsite ก็ยอมรับความจริงที่ว่าเขากบฏต่อใครบางคนที่ดึงเชือกจากเบื้องหลัง",
  ui_story_5043_50431401_114_dialog_content = "จากนั้น Hall of Justice จะได้รับอำนาจทุกอย่างในการสอบสวนองค์ประกอบของคำให้การของ Toto ในขอบเขตสูงสุดของกฎหมาย",
  ui_story_5043_50431401_115_dialog_content = "หากเป็นเช่นนั้น คำถามที่ว่า Salar Manor มีห้องใต้ดินหรือไม่นั้นจะได้รับคำตอบไม่ช้าก็เร็ว",
