  ui_story_5043_50431401_117_dialog_content = "คุณแค่ใช้คดีที่ไม่สำคัญและ Eclipsite ที่ไม่สำคัญยิ่งกว่าเพื่อละเมิดความเป็นส่วนตัวของครอบครัว Salar",
  ui_story_5043_50431401_118_dialog_content = "จำคำพูดของฉันไว้ Leyn คุณจะไม่ประสบความสำเร็จ!",
  ui_story_5043_50431401_119_dialog_content = "เฮ้! เรื่องไหนที่คุณเรียกว่า \"ไม่สำคัญ\"?!",
  ui_story_5043_50431401_120_dialog_content = "หุบปากซะ เจ้าคนชั่ว!",
  ui_story_5043_50431401_121_dialog_content = "ทะ-นั่นมันอะไร...?!",
  ui_story_5043_50431401_122_dialog_content = "ฉันมีเรื่องตลกของการทดลองนี้มามากพอแล้ว!",
  ui_story_5043_50431401_123_dialog_content = "ในฐานะหัวหน้าผู้พิพากษา ฉันขอประกาศว่าคำให้การของ Eclipsite ไม่มีผลต่อคดีนี้แต่อย่างใด!",
  ui_story_5043_50431401_124_dialog_content = "ตามที่ระบุไว้ก่อนหน้านี้ การพิจารณาคดีนี้ต้องเลื่อนออกไปเนื่องจากขาดหลักฐานที่น่าสนใจในปัจจุบัน",
  ui_story_5043_50431401_125_dialog_content = "ศาลถูกเลื่อนออกไปจนกว่าจะถึงวันที่หลักฐานที่สรุปได้ปรากฏออกมา—",
  ui_story_5043_50431401_126_dialog_content = "ว-เดี๋ยวก่อน! ฉันมีหลักฐานความผิดของฉัน!",
  ui_story_5043_50431401_127_dialog_content = "!!!",
  ui_story_5043_50431401_128_dialog_content = "มันอยู่ที่นี่! ในห้องพิจารณาคดีนี้!",
  ui_story_5043_50431401_129_dialog_content = "ให้ฉันเดาว่ามีเรื่องไร้สาระอีกเรื่องหนึ่งที่จะเกี่ยวข้องกับฉัน?",
  ui_story_5043_50431401_130_dialog_content = "ฉันมีหลักฐาน! จริงหรือ!",
  ui_story_5043_50431401_131_dialog_content = "แล้วหลักฐานนี้คืออะไร โตโต้?",
  ui_story_5043_50431401_132_dialog_content = "มันคือถุงมือที่ถูกทิ้งไว้ในที่เกิดเหตุ!",
  ui_story_5043_50431401_133_dialog_content = "ถุงมือ...?",
  ui_story_5043_50431401_134_dialog_content = "ฉันแน่ใจว่า Schwab ได้ทำความสะอาดถุงมือแล้วเพื่อกำจัดร่องรอยของ Eclipsites...",
  ui_story_5043_50431401_135_dialog_content = "แต่ก่อนที่ฉันจะทำลายรูปปั้น ฉันใช้เล็บข่วนถุงมือให้เป็นรู!",
  ui_story_5043_50431401_136_dialog_content = "ธ-นั่นไม่ใช่สิ่งที่เขาจะล้างออกได้!",
  ui_story_5043_50431401_137_dialog_content = "อะไร?!?",
  ui_story_5043_50431401_138_dialog_content = "ฉันเห็น. ดังนั้นหากเราพบรูนั้นในถุงมือ แสดงว่าคุณเป็นคนใส่มัน",
  ui_story_5043_50431401_139_dialog_content = "ซึ่งจะพิสูจน์ได้ว่าคุณเป็นผู้กระทำความผิดในอาชญากรรม",
  ui_story_5043_50431401_140_dialog_content = "ใช่แล้ว!",
  ui_story_5043_50431401_141_dialog_content = "ผู้พิพากษาชวาบ เราขอตรวจสอบหลักฐานชิ้นนั้นอีกครั้งได้ไหม",
  ui_story_5043_50431401_142_dialog_content = "...",
  ui_story_5043_50431401_143_dialog_content = "โปรดมอบให้ศาลดู",
  ui_story_5043_50431401_144_dialog_content = "ถ้าเลื่อนศาลเร็วๆ นี้ ผมสัญญาว่าไม่นาน นี่จะเป็นลำดับสุดท้ายของธุรกิจของเราสำหรับวันนี้",
  ui_story_5043_50431401_145_dialog_content = "...",
  ui_story_5043_50431401_146_dialog_content = "ผู้พิพากษาชวาบ?",
  ui_story_5043_50431401_147_dialog_content = "... ฮึ",
  ui_story_5043_50431401_148_dialog_content = "นี่คือเหตุผลที่ฉันคิดว่า <color=#FFB400>ความรักเป็นสิ่งที่น่ารังเกียจ</color>.",
  ui_story_5043_50431401_149_dialog_content = "อะไรนะ!",
  ui_story_5043_50431401_150_dialog_content = "นี่หมายความว่าเขา...?",
  ui_story_5043_50431401_151_dialog_content = "ฉันพบว่ามันน่าขยะแขยงที่ต้องอยู่ท่ามกลางผู้คนที่น่ารักมากมาย",
  ui_story_5043_50431401_152_dialog_content = "เข้าหาฉันตลอดเวลาพยายามสอดรู้สอดเห็นชีวิตส่วนตัวของฉันตลอดเวลา ไอ้พวกโง่เขลา!",
  ui_story_5043_50431401_153_dialog_content = "และใช่ คนของคุณทำให้ฉันนึกถึงพวกเขามาก",
  ui_story_5043_50431401_154_dialog_content = "คุณบอกว่าคุณพบว่าความรัก \"น่าขยะแขยง\"?",
  ui_story_5043_50431401_155_dialog_content = "แน่นอนฉันทำ! สิ่งที่คุณเรียกว่าความรักนั้นไม่มีอะไรมากไปกว่าฝันร้ายที่หลีกเลี่ยงไม่ได้!",
  ui_story_5043_50431401_156_dialog_content = "การถูกคนรอบข้างห้อมล้อมทุกวัน ต้องอดทนต่อคำเยินยอมากเกินไปของพวกเขาทุกครั้ง",
  ui_story_5043_50431401_157_dialog_content = "สมัยเป็นนักเรียน โต๊ะทำงานของฉันเต็มไปด้วยจดหมายรัก และบ้านของฉันก็เต็มไปด้วยของขวัญในช่วงวันหยุดสำหรับฉันโดยเฉพาะ",
  ui_story_5043_50431401_158_dialog_content = "เพื่อนๆรู้มั้ยว่าการถูกรักจากทุกคนมันเจ็บปวดแค่ไหน!?",
  ui_story_5043_50431401_159_dialog_content = "...",
  ui_story_5043_50431401_160_dialog_content = "... เขากำลังพูดถึงห่าอะไร?",
  ui_story_5043_50431401_161_dialog_content = "ฉันก็ไม่รู้เหมือนกัน",
  ui_story_5043_50431401_162_dialog_content = "ตอนแรกฉันคิดว่าทุกอย่างจะดีขึ้นหลังจากที่ฉันเริ่มทำงาน",
  ui_story_5043_50431401_163_dialog_content = "ฉันไม่เคยคิดเลยว่าคลื่นแห่งความรักที่ชวนให้อาเจียนจะแผ่ซ่านไปทั่วเมืองเช่นนี้!",
  ui_story_5043_50431401_164_dialog_content = "และราวกับจะทับถมความทุกข์ทรมานของฉัน พวกเขาทำให้ฉันเป็นหัวหน้าผู้พิพากษาของแผนกโรมานซ์ที่น่าขายหน้าใน Hall of Justice!",
  ui_story_5043_50431401_165_dialog_content = "ถูกตัอง. ทนไม่ได้จึงวางแผนทำลายรูปปั้นพวกนั้น!!!",
  ui_story_5043_50431401_166_dialog_content = "ฉันรู้ว่าผู้จัดงานตื้นเขินเหล่านั้นกำลังวางแผนที่จะใช้พวกเขาเป็นจุดศูนย์กลางของการเฉลิมฉลองที่เลวร้ายของพวกเขา และฉันสาบานว่าจะหยุดพวกเขาทุกวิถีทาง!",
  ui_story_5043_50431401_167_dialog_content = "เธอ...",
  ui_story_5043_50431401_168_dialog_content = "คุณเป็นคนตื้นเขินที่ใช้ความรุนแรงเพื่อส่งข้อความแสดงความเกลียดชัง!",
  ui_story_5043_50431401_169_dialog_content = "นั่นเป็นเหตุผลที่คุณสั่งให้ Eclipsites ทำลายรูปปั้นเหล่านั้น?",
  ui_story_5043_50431401_170_dialog_content = "ใช่... ฉันเป็นคนส่งพวกเขา ธรรมชาติที่โสโครกของพวกมันเหมาะอย่างยิ่งสำหรับการสร้างมลทินให้กับสิ่งที่เรียกว่า \"การเฉลิมฉลองความรัก\"",
  ui_story_5043_50431401_171_dialog_content = "นี่หมายความว่าฉันยอมรับผิดทุกอย่างที่คุณเพิ่งพูดไปงั้นเหรอ?",
  ui_story_5043_50431401_172_dialog_content = "คุณสามารถจัดการกับพิธีการปลอมๆ ได้แล้ว เลย์น",
  ui_story_5043_50431401_173_dialog_content = "คุณมีหลักฐานทั้งหมดที่คุณต้องการแล้ว คุณได้รับรางวัล.",
  ui_story_5043_50431401_174_dialog_content = "ความผิดเดียวของฉันคือฉันลืมทำลาย \"เครื่องมือ\" ที่ฉันใช้ก่ออาชญากรรม... ฉันไม่คิดว่ามันจะกลับมาเป็นพยานปรักปรำฉันแบบนี้",
  ui_story_5043_50431401_175_dialog_content = "...",
  ui_story_5043_50431401_176_dialog_content = "ไม่นะ ชวาบ เหตุผลที่คุณแพ้นั้นไม่ซับซ้อนเลย",
  ui_story_5043_50431401_177_dialog_content = "เหตุผลที่คุณแพ้คือคุณไม่ได้แสดงถุงมือให้เราดู",
  ui_story_5043_50431401_178_dialog_content = "<size=45>อะไร?!?</size>",
  ui_story_5043_50431401_179_dialog_content = "รอสักครู่! ถุงมือคือหลักฐานที่เราต้องการเพื่อเอาชนะไม่ใช่หรือ!",
  ui_story_5043_50431401_180_dialog_content = "เป็นไปได้ไหมว่า...ทั้งหมดเป็นการบลัฟ?",
  ui_story_5043_50431401_181_dialog_content = "ว้าว ขอบคุณพระเจ้าที่จบลงแล้ว! ในที่สุดฉันก็สามารถหายใจได้ตามปกติแล้ว",
  ui_story_5043_50431401_182_dialog_content = "ฉันต้องบอกว่า Leyn คุณเป็นเจ้าแห่งความผิดพลาดจริงๆ!",
  ui_story_5043_50431401_183_dialog_content = "เจ้าพวก... เจ้าหลอกข้า?!",
  ui_story_5043_50431401_184_dialog_content = "Th-Eclipsite ที่ถูกสาปนั่นไม่เคยทิ้งช่องโหว่ใด ๆ ไว้ในนั้นเลย !!!",
  ui_story_5043_50431401_185_dialog_content = "ฮิฮิฮิ... แต่เดี๋ยวก่อน ยังมีอีก!",
  ui_story_5043_50431401_186_dialog_content = "คุณไม่คิดว่าคุณคิดว่ามันบังเอิญไปหน่อยเหรอ?",
  ui_story_5043_50431401_187_dialog_content = "Eclipsite เดียวที่สามารถหลบหนีจากบ้านของคุณได้คือคนเดียวกับที่คุณสั่งให้ทำลายรูปปั้นหรือไม่?",
  ui_story_5043_50431401_188_dialog_content = "อย่าบอกนะว่าคุณ...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>เมื่อวาน...</color>",
  ui_story_5043_50431401_190_dialog_content = "พร้อมสำหรับการทำงานล่วงเวลาเล็กน้อยแล้วหรือยัง?",
  ui_story_5043_50431401_191_dialog_content = "แน่นอน. ด้วยกรณีที่ไม่ชัดเจนเช่นเคย หน้าที่ของฉันคือรวบรวมข้อมูลให้ได้มากที่สุดก่อนการพิจารณาคดี",
  ui_story_5043_50431401_192_dialog_content = "ถึงกระนั้น ฉันก็ไม่คิดว่าคุณจะเลือกติดแท็กกับฉัน",
  ui_story_5043_50431401_193_dialog_content = "ชิ! บอกฉันทีว่าคนธรรมดานั่นดูถูกจรรยาบรรณในการทำงานของฉันหรือมิตรภาพของฉันกับทีน่าในตอนนี้?",
  ui_story_5043_50431401_194_dialog_content = "ฉันคิดว่าไม่สำคัญ พักเรื่องความแตกต่างของเราไว้ก่อน แล้วโฟกัสไปที่คดีนี้...",
  ui_story_5043_50431401_195_dialog_content = "S-ขออภัยที่รบกวน Hall of Justice ยังเปิดอยู่หรือไม่?",
  ui_story_5043_50431401_196_dialog_content = "นี่คืออะไร? สุริยุปราคา?",
  ui_story_5043_50431401_197_dialog_content = "และที่หน้าประตู Hall of Justice ไม่น้อย! เตรียมตัวตายได้เลยเจ้าปีศาจ!",
  ui_story_5043_50431401_198_dialog_content = "W-เดี๋ยวก่อน อย่าทำร้ายฉัน! ฉันมาที่นี่เพื่อแจ้งความอาชญากร!!!",
  ui_story_5043_50431401_199_dialog_content = "ฉันขอโทษคุณ? Eclipsite รายงานอาชญากรรม?",
  ui_story_5043_50431401_200_dialog_content = "ลองมาฟังสิ่งที่เขาพูดกัน นอกจากนี้ ถ้าเขาสร้างปัญหา การกำจัดเขาก็จะไม่ใช่ปัญหา",
  ui_story_5043_50431401_201_dialog_content = "ดี. บอกเราเกี่ยวกับอาชญากรรมนี้แล้ว และทำให้เร็ว!",
  ui_story_5043_50431401_202_dialog_content = "คะ-ครับ!",
  ui_story_5043_50431401_203_dialog_content = "A-ให้ฉันแนะนำตัว m-ตัวเอง...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>10 นาทีให้หลัง...</color>",
  ui_story_5043_50431401_205_dialog_content = "... และนั่นคือตอนที่เขารวบพวกเราทั้งหมดและขังพวกเราไว้ในห้องใต้ดินของ Salar Manor!",
  ui_story_5043_50431401_206_dialog_content = "แต่นี่จะเป็นไปได้อย่างไร? ฉันหมายความว่า มันอธิบายว่าทำไมเราถึงพบ Eclipsites ในห้องใต้ดิน...",
  ui_story_5043_50431401_207_dialog_content = "ย-ใช่! นั่นคือตอนที่ฉันหนีไปพร้อมกับพวกที่เหลือ!",
  ui_story_5043_50431401_208_dialog_content = "อะไรนะ!",
  ui_story_5043_50431401_209_dialog_content = "นั่นหมายความว่า... เราคือคนที่ช่วยชีวิตคุณ!",
  ui_story_5043_50431401_210_dialog_content = "A-และฉันรู้สึกขอบคุณไปมากกว่านี้ไม่ได้แล้ว! พวกคุณคือฮีโร่ของฉัน!",
  ui_story_5043_50431401_211_dialog_content = "คุณต้องการที่จะกล่าวหา Schwab ว่าเก็บงำ Eclipsites โดยไม่ตั้งใจหรือไม่?",
  ui_story_5043_50431401_212_dialog_content = "ย-ใช่! ฉันรู้ว่ากฎของ L-Lumopolis จะไม่ปกป้อง E-Eclipsite แต่ฉันรู้ว่าเขาต้องเจอเรื่องแย่กว่านี้แน่!",
  ui_story_5043_50431401_213_dialog_content = "งานง่ายพอ แค่มาที่ศาลในวันพรุ่งนี้ และบอกทุกคนถึงสิ่งที่คุณเพิ่งบอกเรา",
  ui_story_5043_50431401_214_dialog_content = "อีกไม่นานทุกคนจะได้รู้ว่า Schwab กำลังทำอะไรอยู่ในเงามืด!",
  ui_story_5043_50431401_215_dialog_content = "S-แน่นอน! ฉันทำได้!",
  ui_story_5043_50431401_216_dialog_content = "... คุณมีหลักฐานไหม?",
  ui_story_5043_50431401_217_dialog_content = "พี-พรูฟ?",
  ui_story_5043_50431401_218_dialog_content = "จำไว้ว่าคุณคือ Eclipsite",
  ui_story_5043_50431401_219_dialog_content = "เราไปถึงห้องใต้ดินของครอบครัว Salar แล้ว ดังนั้นเราจึงเชื่อคำพูดของคุณได้ แต่คนอื่นๆ ล่ะ?",
  ui_story_5043_50431401_220_dialog_content = "หากไม่มีหลักฐานใดๆ สิ่งที่ Schwab ต้องทำคือปฏิเสธคำให้การของคุณ และคุณจะถูกไล่ออก",
  ui_story_5043_50431401_221_dialog_content = "ไม่เพียงแค่นั้น เขาอาจจะตามคุณมาเมื่อการทดลองสิ้นสุดลง",
  ui_story_5043_50431401_222_dialog_content = "การก้าวไปข้างหน้าด้วยสิ่งนี้จะเป็นการตัดสินใจที่อันตรายอย่างยิ่ง",
  ui_story_5043_50431401_223_dialog_content = "ฉันขอโทษ แต่ฉันไม่มีหลักฐานใดๆ...",
  ui_story_5043_50431401_224_dialog_content = "ฉัน-ต้องใช้ทั้งหมดที่ฉันมีเพื่อหนีออกจากห้องใต้ดินของเขา...",
  ui_story_5043_50431401_225_dialog_content = "เฮ้! เราไม่สามารถยอมจำนนเพียงเพราะเราไม่มีหลักฐาน!",
  ui_story_5043_50431401_226_dialog_content = "ทำไมเราไม่ลองไปเยี่ยม Salar Manor อีกครั้งดูล่ะ?",
  ui_story_5043_50431401_227_dialog_content = "เดี๋ยวก่อน ฉันไม่คิดว่าเราต้องไปไกลขนาดนั้น ฉันมีความคิด...",
  ui_story_5043_50431401_228_dialog_content = "ต่อไป?",
  ui_story_5043_50431401_229_dialog_content = "เนื่องจากเราไม่มีหลักฐาน สิ่งที่เราต้องทำคือให้เขายอมรับผิด!",
  ui_story_5043_50431401_230_dialog_content = "... คุณล้อเล่นใช่ไหม?",
  ui_story_5043_50431401_231_dialog_content = "เราจะทำให้เขายอมรับได้อย่างไรโดยไม่มีข้อพิสูจน์!",
  ui_story_5043_50431401_232_dialog_content = "บอกฉันที ทำไมคุณถึงคิดว่าเขาจับ Eclipsites เป็นเชลยตั้งแต่แรก?",
  ui_story_5043_50431401_233_dialog_content = "อืม... การที่เขาจะทำอะไรที่อันตรายขนาดนั้น มันจะต้องมีเหตุผลที่สำคัญมากแน่ๆ",
  ui_story_5043_50431401_234_dialog_content = "ฉันคิดว่าเขาสั่งให้พวกเขาทำลายรูปปั้น",
  ui_story_5043_50431401_235_dialog_content = "โอ้? พูดอะไรหยั่งงั้น?",
  ui_story_5043_50431401_236_dialog_content = "จำตอนที่ฉันคว้ามือผู้ร้ายกลับมาที่ Stairway to the Skies ได้ไหม?",
  ui_story_5043_50431401_237_dialog_content = "หลังจากที่คุณและคนอื่นๆ กำจัด Eclipsites ที่เหลือหมดแล้ว ก็ไม่มีใครอยู่รอบๆ",
  ui_story_5043_50431401_238_dialog_content = "ด้านบนของ Stairway to the Skies เป็นพื้นที่เปิดโล่งขนาดใหญ่ ไม่มีทางที่ใครจะหายหน้าหายตาเราไปเร็วขนาดนั้น",
  ui_story_5043_50431401_239_dialog_content = "แน่นอนว่าผู้ร้ายคือ Eclipsite",
  ui_story_5043_50431401_240_dialog_content = "โอ้ฉันเห็นแล้ว! ถ้าผู้ร้ายเป็น Eclipsite เราคงจะกำจัดมันพร้อมกับคนอื่นๆ!",
  ui_story_5043_50431401_241_dialog_content = "นั่นจะอธิบายได้ว่าทำไมเราถึงไม่พบพวกเขา!",
  ui_story_5043_50431401_242_dialog_content = "นี่คือเหตุผลที่น่าจะใช่",
  ui_story_5043_50431401_243_dialog_content = "คุณวางแผนที่จะใช้ข้อมูลนี้อย่างไร",
  ui_story_5043_50431401_244_dialog_content = "ก่อนอื่น เราจะให้ Toto เป็นผู้ร้าย",
  ui_story_5043_50431401_245_dialog_content = "ต่อไป เราจะให้เขาให้ความจริงในแบบของเราเป็นประจักษ์พยานของเขา",
  ui_story_5043_50431401_246_dialog_content = "ตราบเท่าที่ลางสังหรณ์ของเราใกล้เคียงกับความจริง Schwab จะเชื่อว่า Toto คือ Eclipsite ที่เขาสั่งให้ทำลายรูปปั้น",
  ui_story_5043_50431401_247_dialog_content = "มันสมบูรณ์แบบ! เป้าหมายของคุณคือทำให้เขาเชื่อว่าเรามีหลักฐานปรักปรำเขา และเมื่อเขายอมรับความพ่ายแพ้ เขาจะสารภาพความผิดด้วยความหงุดหงิด!",
  ui_story_5043_50431401_248_dialog_content = "ถูกตัอง. เราต้องเอาชนะเขาในการต่อสู้ด้วยไหวพริบ",
  ui_story_5043_50431401_249_dialog_content = "โตโต้ว่าไงนะ? คุณเต็มใจที่จะโกหกภายใต้คำสาบานหรือไม่?",
  ui_story_5043_50431401_250_dialog_content = "A-ตราบใดที่มันเปิดเผย Schwab ฉันจะทำ!",
  ui_story_5043_50431401_251_dialog_content = "ดี. เราจะใช้เวลาที่เหลือของวันเพื่อซ้อมบทของคุณ",
  ui_story_5043_50431401_252_dialog_content = "หากเราต้องการเพิ่มโอกาสแห่งความสำเร็จให้สูงสุด เราจะต้องคิดหาสิ่งที่น่าเชื่อถือ",
  ui_story_5043_50431401_253_dialog_content = "บางอย่างที่จะทำให้ Schwab สงสัยในตัวเองมากพอที่จะเชื่อว่าเรากำลังพูดความจริง",
  ui_story_5043_50431401_254_dialog_content = "คุณ... คุณคนหลอกลวงที่น่าสมเพช!",
  ui_story_5043_50431401_255_dialog_content = "ทั้งหมดที่เราทำคือสู้ด้วยไฟ ผู้พิพากษาชวาบ",
  ui_story_5043_50431401_256_dialog_content = "ให้คิดว่าผู้ร้ายเป็นหัวหน้าผู้พิพากษามาโดยตลอด",
  ui_story_5043_50431401_257_dialog_content = "นี่เป็นเรื่องที่ไม่น่าเชื่อ พวกเจ้าจะก้มต่ำได้อย่างไร? คุณเรียกตัวเองว่าเป็นสมาชิกของ Hall of Justice?!",
  ui_story_5043_50431401_258_dialog_content = "ถึงอย่างนั้น ในที่สุดศาลก็สามารถนำความจริงมาเปิดเผยได้ใช่หรือไม่?",
  ui_story_5043_50431401_259_dialog_content = "บางครั้ง วิธีเดียวที่จะเอาชนะความมืดได้ก็คือความมืดนั่นเอง!",
  ui_story_5043_50431401_260_dialog_content = "มันจบแล้ว ผู้พิพากษาชวาบ มาร่วมอย่างสันติและรับผิดชอบต่อการกระทำของคุณ",
  ui_story_5043_50431401_261_dialog_content = "หืม จบมั้ยเอ่ย?",
  ui_story_5043_50431401_262_dialog_content = "ดูเหมือนว่าคุณเองก็ทำผิดพลาดครั้งใหญ่เพียงครั้งเดียว เลย์ คุณต้องการที่จะเดาว่ามันคืออะไร?",
  ui_story_5043_50431401_263_dialog_content = "คุณหมายความว่าอย่างไร...?",
  ui_story_5043_50431401_264_dialog_content = "ความผิดพลาดของคุณคือการสันนิษฐานว่าสิ่งต่าง ๆ จะจบลงเมื่อคุณเปิดเผยความจริง",
  ui_story_5043_50431401_265_dialog_content = "ในฐานะหัวหน้าผู้พิพากษา ข้าพเจ้าขอประกาศ ณ ที่นี้ว่าผู้พิพากษาเลย์น ผู้พิพากษาทีน่า และผู้พิพากษาแมทธิเยอ ล้วนมีส่วนพัวพันในอาชญากรรมที่นำขึ้นสู่ศาล!",
  ui_story_5043_50431401_266_dialog_content = "ผู้กระทำความผิดทั้งสามจะถูกจับกุมทันทีเมื่อการพิจารณาคดีเลื่อนออกไป!",
  ui_story_5043_50431401_267_dialog_content = "นี่มันบ้าอะไรกัน ชวาบ!",
  ui_story_5043_50431401_268_dialog_content = "ทุกคนที่นี่เพิ่งได้ยินคุณสารภาพ! คุณคือผู้ร้ายตัวจริง ไม่ใช่พวกเรา!",
  ui_story_5043_50431401_269_dialog_content = "โอ้ ดูเหมือนว่าเรายังหาข้อตกลงร่วมกันไม่ได้สำหรับกรณีนี้",
