  ui_story_5043_50431401_271_dialog_content = "คณะลูกขุน?!",
  ui_story_5043_50431401_272_dialog_content = "เดี๋ยวก่อน พวกนั้น...?",
  ui_story_5043_50431401_273_dialog_content = "E-Eclipsites?! แต่ยังไงล่ะ!",
  ui_story_5043_50431401_274_dialog_content = "โปรดส่งคำแถลงปิดท้ายของคุณ ผู้พิพากษาลีน",
  ui_story_5043_50431401_275_dialog_content = "... จากเหตุการณ์ทั้งหมดที่เกิดขึ้น ฉันสรุปได้ว่า Schwab Salar เป็นผู้ร้ายที่แท้จริงในกรณีนี้",
  ui_story_5043_50431401_276_dialog_content = "ดีดี... ใครเห็นด้วยกับข้อกล่าวหายกมือขึ้น",
