  ui_story_5043_50431401_301_dialog_content = "กรร...",
  ui_story_5043_50431401_302_dialog_content = "Drat ฉันคิดว่านั่นคือ Eclipsites ที่ซ่อนอยู่ภายใต้หน้ากากเหล่านั้น!",
  ui_story_5043_50431401_303_dialog_content = "อย่างแท้จริง. หากนี่คือไพ่ตายของ Schwab พวกเขาจะรับมือได้ไม่ยาก",
  ui_story_5043_50431401_304_dialog_content = "ใช้ความรุนแรงทั้งหมดเพราะคุณแพ้ในศาล? ช่างเล็กน้อย!",
  ui_story_5043_50431401_305_dialog_content = "ไม่ดีเลย Hall of Justice เหมาะกับสไตล์การต่อสู้ของพวกเขามากกว่า เราจะถูกล้อมในไม่ช้า!",
  ui_story_5043_50431401_306_dialog_content = "เราพูดถูก... เราพูดถูก Schwab! คุณจะปล่อยให้ความชั่วร้ายมีชัยในบ้านแห่งความยุติธรรมได้อย่างไร!",
  ui_story_5043_50431401_307_dialog_content = "ปล่อยนะเลย์! ความยุติธรรมเข้าข้างผู้ชนะเสมอ และเรากำลังต่อสู้กับการต่อสู้ที่ยากเย็นแสนเข็ญที่นี่!",
  ui_story_5043_50431401_308_dialog_content = "เราต้องหนีในขณะที่เราทำได้!",
  ui_story_5043_50431401_309_dialog_content = "เธอพูดถูก ขยับได้แล้ว!",
  ui_story_5043_50431401_310_dialog_content = "ทางนี้รีบเลย!",
  ui_story_5043_50431402_1_dialog_content = "ความรักของเราลอยอยู่สูงเหนือหัวของเราเหมือนเมฆ! ♪",
  ui_story_5043_50431402_2_dialog_content = "ซ่อนอยู่หลังม่าน ความรักของเราภูมิใจมาก! ♪",
  ui_story_5043_50431402_3_dialog_content = "จากระยะไกลเราสงสัยว่าความงามอยู่ภายใน♪",
  ui_story_5043_50431402_4_dialog_content = "การได้เห็นความรักของเราผลิบานเป็นความปรารถนาที่เราไม่สามารถซ่อนเร้นได้! ♪",
  ui_story_5043_50431402_5_dialog_content = "ฉันได้ยินว่าวันนี้พวกเขาจะไปเป่าลูกโป่งพระจันทร์ คิดว่าจริงมั้ย?",
  ui_story_5043_50431402_6_dialog_content = "แน่นอนพวกเขา! นั่นคือเหตุผลทั้งหมดที่เรารวมตัวกันที่นี่ในวันนี้!",
  ui_story_5043_50431402_7_dialog_content = "พวกเขาบอกว่าบอลลูนเต็มไปด้วยสิ่งต่างๆ มากมาย เช่น ดอกไม้ งานประดิษฐ์จากกระดาษ หรือแม้แต่ฟองหลากสี!",
  ui_story_5043_50431402_8_dialog_content = "ฟังดูดีกว่าดอกไม้ไฟ! เป็นเครื่องบรรณาการที่สมบูรณ์แบบสำหรับพลังแห่งความรัก!",
  ui_story_5043_50431402_9_dialog_content = "ฮะ? ดูเหมือนว่าฝูงชนกำลังวิ่งออกจาก Hall of Justice",
  ui_story_5043_50431402_10_dialog_content = "สงสัยว่าพวกเขากำลังทำอะไร?",
  ui_story_5043_50431402_11_dialog_content = "ว้า ในที่สุดเราก็หนีออกมาได้แล้ว",
  ui_story_5043_50431402_12_dialog_content = "เรายังพักผ่อนไม่ได้! พวกเขาจะตามทันทุกวินาที!",
  ui_story_5043_50431402_13_dialog_content = "...",
  ui_story_5043_50431402_14_dialog_content = "สัตว์ประหลาดถาวร ใช่ไหม?",
  ui_story_5043_50431402_15_dialog_content = "พวกมันตั้งใจจะไล่ล่าพวกเราไปจนถึงอัมบราตันงั้นหรือ?!",
  ui_story_5043_50431402_16_dialog_content = "เดี๋ยวก่อน ดูเหมือนว่าขบวนพาเหรดกำลังมุ่งหน้าไปทางนี้!",
