  ui_story_5043_50431402_18_dialog_content = "เราจะหนีไปตอนนี้ไม่ได้แล้ว! Eclipsites จะโจมตีคนเหล่านั้นถ้าเราทำ!",
  ui_story_5043_50431402_19_dialog_content = "ถูกตัอง. เราจะต้องเอาชนะพวกเขาที่นี่และเดี๋ยวนี้",
  ui_story_5043_50431402_20_dialog_content = "PlayerNameคุณสามารถเตือนขบวนพาเหรดและให้พวกเขาอพยพออกจากพื้นที่ได้หรือไม่?",
  ui_story_5043_50431402_21_dialog_content = "แน่นอน ปล่อยให้เป็นหน้าที่ของผม!",
  ui_story_5043_50431402_22_dialog_content = "พวกเขามาดูการแสดงที่พวกเขาไม่เคยเห็นมาก่อน",
  ui_story_5043_50431402_23_dialog_content = "คุณมีใจจริง ๆ ที่จะปล้นพวกเขาจากประสบการณ์ที่คาดหวังสูงเช่นนี้หรือไม่?",
  ui_story_5043_50431402_24_dialog_content = "แก... แกกล้าดียังไงมาล้อเล่นในเวลาแบบนี้!",
  ui_story_5043_50431402_25_dialog_content = "ฉันจริงจังมาก Matthieu ทั้งหมดที่ฉันต้องการคือให้การแสดงที่พวกเขาอยากดูแทบตาย",
  ui_story_5043_50431402_26_dialog_content = "ตอนจบที่ยิ่งใหญ่สำหรับเรื่องตลกของการเฉลิมฉลองนี้!",
  ui_story_5043_50431402_27_dialog_content = "<size=45>ทางนี้ค่ะทุกคน! เร็วเข้า!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>การแสดงกำลังจะเริ่มขึ้นแล้ว!</size>",
  ui_story_5043_50431402_29_dialog_content = "Schwab ความหมายของสิ่งนี้คืออะไร!",
  ui_story_5043_50431402_30_dialog_content = "เขากำลังพยายามทำลายงานฉลอง! คนเหล่านั้นกำลังตกอยู่ในอันตราย!",
  ui_story_5043_50431402_31_dialog_content = "พวกเขากำลังเร่งรีบ! อย่าปล่อยให้พวกเขาเข้าใกล้ Eclipsites!",
  ui_story_5043_50431402_32_dialog_content = "ไม่ต้องห่วง ฉันจะปกป้องพวกเขาเอง!",
  ui_story_5043_50431402_33_dialog_content = "ทำไมจริงจังจัง? มันไม่มีอะไรมากไปกว่าการแสดง",
  ui_story_5043_50431402_34_dialog_content = "ตอนนี้ฉันจำได้แล้ว วันนี้บอลลูนพระจันทร์ควรจะระเบิดไม่ใช่เหรอ?",
  ui_story_5043_50431402_35_dialog_content = "ฉันสงสัยว่าเราจะพบอะไรซ่อนอยู่ในอนุสาวรีย์ความรักลอยน้ำไร้สาระเมื่อมันพบ",
  ui_story_5043_50431402_36_dialog_content = "อย่าบอกนะว่าคุณ...",
  ui_story_5043_50431402_37_dialog_content = "ดูผลของความเชื่อที่น่าหัวเราะของคุณ!",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>โผล่-!!!</color>",
  ui_story_5043_50431402_39_dialog_content = "อู้วววว!!!",
  ui_story_5043_50431402_40_dialog_content = "ทุกคน ระวังนะ!",
  ui_story_5043_50431402_41_dialog_content = "เฮ้ย นี่อะไรลอยมาชนเรา...?",
  ui_story_5043_50431402_42_dialog_content = "ของขวัญจากเทศกาลโบราณ - ช่อโคลเวอร์ของฉัน - นี่คืออะไร?",
  ui_story_5043_50431402_43_dialog_content = "ดอกไม้ที่ตายแล้วเหล่านี้หรือไม่?",
  ui_story_5043_50431402_44_dialog_content = "ใช่ กุหลาบที่ตายแล้ว แน่นอน...",
  ui_story_5043_50431402_45_dialog_content = "ท้องฟ้าเต็มไปด้วยดอกไม้ที่ตายแล้ว...",
  ui_story_5043_50431402_46_dialog_content = "น่าเกลียดอะไรอย่างนี้ แค่เห็นก็รู้สึกแย่แล้ว",
  ui_story_5043_50431402_47_dialog_content = "นี่เป็นวิธีการระเบิดของ Moon Balloon ที่ควรจะเป็นจริงๆ เหรอ?",
  ui_story_5043_50431402_48_dialog_content = "แท้จริงแล้วคือ!",
  ui_story_5043_50431402_49_dialog_content = "ไม่ใช่ขั้นตอนอื่น Schwab!",
  ui_story_5043_50431402_50_dialog_content = "เกิดอะไรขึ้น ผู้พิพากษาทีน่า? นี่ไม่ใช่ภาพแห่งความรักใช่ไหม",
  ui_story_5043_50431402_51_dialog_content = "ความงามที่เราจินตนาการได้ก็ต่อเมื่อเราละสายตาจากสิ่งที่อยู่ภายใน",
  ui_story_5043_50431402_52_dialog_content = "เช่นเดียวกับดวงจันทร์บนท้องฟ้ายามค่ำคืน มันดึงดูดใจเราด้วยความงามที่ลึกลับและห่างไกล",
  ui_story_5043_50431402_53_dialog_content = "เสน่ห์ดึงดูดพลังจากสิ่งที่ไม่รู้จัก จากความไม่รู้ของผู้คนเกี่ยวกับธรรมชาติที่แท้จริงของมัน",
  ui_story_5043_50431402_54_dialog_content = "และตอนนี้ทุกคนได้เห็นมันด้วยตัวเอง",
  ui_story_5043_50431402_55_dialog_content = "นี่คือความหมายที่แท้จริงของความรักของคุณ",
  ui_story_5043_50431402_56_dialog_content = "สิ่งที่เหลืออยู่หลังจากความตื่นเต้นและความไร้เหตุผลตายลงคือโลกที่เหลืออยู่ในความโกลาหล",
  ui_story_5043_50431402_57_dialog_content = "และนับแต่วันนี้เป็นต้นไปจะไม่มีใครเห็นพระจันทร์งามอีกเลย",
  ui_story_5043_50431402_58_dialog_content = "เขาพูดถูกเรื่องหนึ่ง ฉันไม่อยากเห็นลูกโป่งโง่ๆ นั่นอีก",
  ui_story_5043_50431402_59_dialog_content = "ไม่ล้อเล่น ใครมีความคิดที่จะเติมดอกไม้ที่ตายแล้ว? มันเป็นแค่ถุงขยะลอยน้ำ...",
  ui_story_5043_50431402_60_dialog_content = "เพียงพอแล้วสำหรับวาทศิลป์ที่ผิดพลาดของคุณ! คุณเป็นคนเปลี่ยนสิ่งที่อยู่ในลูกโป่งไม่ใช่เหรอ!",
  ui_story_5043_50431402_61_dialog_content = "ฉันไม่เคยสัมผัสเนื้อหาของบอลลูน ทั้งหมดที่ฉันทำคือเอา Luminatics ที่อยู่รอบๆ ออก",
  ui_story_5043_50431402_62_dialog_content = "นาย...!",
  ui_story_5043_50431402_63_dialog_content = "อย่ามองฉันแบบนั้น คุณเป็นคนหนึ่งที่อยากจะโกหกประชาชนด้วยการรักษาดอกไม้เหล่านั้นด้วย Lumina",
  ui_story_5043_50431402_64_dialog_content = "ทั้งหมดที่ฉันทำคือเปิดเผยความจริง",
  ui_story_5043_50431402_65_dialog_content = "ความงามจะได้รับการชื่นชมก็ต่อเมื่อมีคนรับผิดชอบต่อความอัปลักษณ์",
  ui_story_5043_50431402_66_dialog_content = "เฉกเช่นสาวใช้ตาใสที่ไล่ตามฉันด้วยคำสัญญาแห่งความรัก พวกเธอไม่รู้หรอกว่าฉันต้องทนทุกข์ทรมานมากเพียงใดเพราะความเพ้อฝันของพวกเธอ",
  ui_story_5043_50431402_67_dialog_content = "ความรักคืออะไรกันแน่...?",
  ui_story_5043_50431402_68_dialog_content = "อะไรหนักหนาจนสร้างภาระให้คนอื่น...",
  ui_story_5043_50431402_69_dialog_content = "ดูเหมือนว่าคุณจะเริ่มเข้าใจข้อความของฉันในที่สุด",
  ui_story_5043_50431402_70_dialog_content = "...",
  ui_story_5043_50431402_71_dialog_content = "(เป็นไปได้ไหมว่า... ฉันทำผิดแบบเดียวกัน?)",
  ui_story_5043_50431402_72_dialog_content = "นั่นไม่ใช่เลย Tina! อย่าให้ความเข้าใจผิดของ Schwab หลอกคุณ!",
  ui_story_5043_50431402_73_dialog_content = "หา?",
  ui_story_5043_50431402_74_dialog_content = "\"ความจริง\" ของเขาจะมีความสำคัญเหนือประสบการณ์ของคนอื่นได้อย่างไร?",
  ui_story_5043_50431402_75_dialog_content = "เช่นเดียวกับอารมณ์อื่นๆ เราทุกคนรู้สึกถึงความรักในแบบของเรา",
  ui_story_5043_50431402_76_dialog_content = "ฉันอาจไม่รู้ถึง \"ความจริง\" เบื้องหลังแนวคิดของความรัก... แต่แค่ได้เห็นทุกคนมีความสุขในงานแบบนี้ก็เพียงพอแล้วสำหรับฉัน!",
  ui_story_5043_50431402_77_dialog_content = "และนอกจากนี้ ฉันไม่คิดว่าชวาบเคยรู้สึกถึงความรักที่มีต่อตัวเองอย่างแท้จริง!",
  ui_story_5043_50431402_78_dialog_content = "เขามีสิทธิ์อะไรไปบอกคนอื่นว่ารู้สึกยังไง!",
  ui_story_5043_50431402_79_dialog_content = "เธอ...",
  ui_story_5043_50431402_80_dialog_content = "แน่นอนฉันไม่เคยรู้สึกรักมาก่อน! ฉันจะปล่อยให้ตัวเองรู้สึกถึงอารมณ์ที่น่าขยะแขยงแบบนี้ได้อย่างไร!",
  ui_story_5043_50431402_81_dialog_content = "ถูกของคุณ, PlayerName!",
  ui_story_5043_50431402_82_dialog_content = "ไม่มีความจริงในสิ่งที่เขาพูดเลย เขาแค่จับจ้องไปที่ผลลัพธ์ที่เลวร้ายที่สุด!",
  ui_story_5043_50431402_83_dialog_content = "ยิ่งไปกว่านั้น การจินตนาการถึงความสวยงามของความรักก็ไม่ผิดเช่นกัน!",
  ui_story_5043_50431402_84_dialog_content = "ความรักไม่ใช่สิ่งที่ตัดสินกันในศาล แล้วเราจะตัดสินใครดีล่ะ?",
  ui_story_5043_50431402_85_dialog_content = "ไม่ว่าจะเป็นการสารภาพรักหรือการบอกรักจากคนไกล การจากกันหรือการจากลา ประสบการณ์ทั้งหมดนี้เป็นการแสดงความรักที่ถูกต้อง!",
  ui_story_5043_50431402_86_dialog_content = "Schwab คุณไม่รู้หรอกว่าความรักหมายถึงอะไร!",
  ui_story_5043_50431402_87_dialog_content = "อืม คุณอาจพูดถูกว่าฉันไม่เข้าใจความหมายของความรัก",
  ui_story_5043_50431402_88_dialog_content = "ฉันก็ไม่เข้าใจเหมือนกันว่าทำไมพวกคุณถึงยอมทุ่มเทเพื่อไล่ตามมัน",
  ui_story_5043_50431402_89_dialog_content = "สำหรับฉันแล้ว ความรักเป็นเพียงสิ่งกีดขวาง อารมณ์กาฝากที่ทำลายความสงบสุขของฉันและเชื้อเชิญให้คนอื่นเข้ามายุ่งในชีวิตของฉัน",
  ui_story_5043_50431402_90_dialog_content = "ไม่ อิทธิพลชั่วร้ายของมันแผ่ขยายไปไกลกว่าแค่ชีวิตของฉัน! มันคุกคามอาชีพและความสามารถในการปฏิบัติหน้าที่ของฉัน มันคุกคามความสมดุลของ Lumopolis ทั้งหมด!",
  ui_story_5043_50431402_91_dialog_content = "ทำไมเธอคิดแบบนั้นล่ะ?",
  ui_story_5043_50431402_92_dialog_content = "แค่ลองมองดูผู้คนรอบตัวเรา แม้แต่ความรู้สึกเพียงเล็กน้อยก็สามารถทำให้พวกเขาละทิ้งเหตุผลทั้งหมดได้",
  ui_story_5043_50431402_93_dialog_content = "อารมณ์เดียวกับตนเองเหล่านั้นนำไปสู่การสร้างการเยาะเย้ยที่รู้จักกันในชื่อ Romance Division!",
  ui_story_5043_50431402_94_dialog_content = "ความรักทำอะไรให้เราจริงๆ อืม? นอกเหนือจากการให้อาชญากรมีโอกาสหลบหนีการลงโทษแล้ว ยังทำให้เราตั้งข้อหาผู้บริสุทธิ์ในอาชญากรรมที่พวกเขาไม่เคยก่ออีกด้วย",
  ui_story_5043_50431402_95_dialog_content = "มันทำลายล้างกฎหมายอายุหลายศตวรรษที่ยึดเกาะลูโมโปลิสไว้ด้วยกันตลอดประวัติศาสตร์อันรุ่งโรจน์!",
  ui_story_5043_50431402_96_dialog_content = "ด้วยเหตุผลนี้ ฉันจึงเลือกที่จะใช้กฎหมายอย่างเต็มกำลังเพื่อต่อต้านคลื่นแห่ง \"ความรัก\" ที่ถูกสาปแช่งนี้ซึ่งก่อกวนเมืองอันสวยงามของเรา...",
  ui_story_5043_50431402_97_dialog_content = "ทั้งหมดที่ฉันทำ ฉันทำไปโดยมีจุดประสงค์เพียงเพื่อกำจัดความรักที่เป็นปัจจัยในการประหารชีวิต!",
  ui_story_5043_50431402_98_dialog_content = "ฉันต้องการคณะลูกขุนที่มีความเห็นสอดคล้องกับฉันเอง ซึ่งการตัดสินจะไม่ถูกวางยาโดยอารมณ์ที่ไม่จำเป็นใดๆ",
  ui_story_5043_50431402_99_dialog_content = "โชคดีที่สัตว์ประหลาดน่าเกลียดเหล่านี้มีความสามารถมากกว่าที่จะทำหน้าที่เหล่านั้นได้",
  ui_story_5043_50431402_100_dialog_content = "...",
  ui_story_5043_50431402_101_dialog_content = "นั่นคือสิ่งที่เขาคิดมาตลอด...",
  ui_story_5043_50431402_102_dialog_content = "เพื่อพิสูจน์ความหวาดระแวงของตัวเองด้วยวิธีนี้",
  ui_story_5043_50431402_103_dialog_content = "คนประเภทนี้น่ากลัวกว่าอาชญากรที่น่าอับอายเสียอีก",
  ui_story_5043_50431402_104_dialog_content = "แต่ให้เรานำบทสนทนาที่ไม่มีจุดหมายเกี่ยวกับความรักมาปิดฉากลง",
  ui_story_5043_50431402_105_dialog_content = "ให้เรามุ่งความสนใจไปที่คดีที่อยู่ในมือแทน",
  ui_story_5043_50431402_106_dialog_content = "ท้ายที่สุดคุณทั้งหมด <color=#FFB400>รู้สึกผิด</color> อยู่ในสายตาของศาล!",
  ui_story_5043_50431402_107_dialog_content = "เฮ่ ดูนั่นสิ!",
  ui_story_5043_50431402_108_dialog_content = "Eclipsites กำลังหลั่งไหลออกมาจากภายใน Hall of Justice!",
  ui_story_5043_50431402_109_dialog_content = "วันนี้จะบ้าไปกว่านี้ไม่ได้แล้ว! หนี!!!",
  ui_story_5043_50431402_110_dialog_content = "ดูเหมือนว่า Schwab จะรุกอีกครั้ง",
  ui_story_5043_50431402_111_dialog_content = "เขาบ้าไปแล้วถ้าเขาคิดว่าเขาสามารถเรียก Eclipsites ต่อหน้าสาธารณชนได้ ผู้คุมจะจับเขาใส่กุญแจมือในไม่ช้า",
  ui_story_5043_50431402_112_dialog_content = "สำหรับตอนนี้ เรายังคงต้องควบคุมสถานการณ์และตรวจสอบให้แน่ใจว่าไม่มีพลเรือนคนใดได้รับอันตรายจากการกระทำของเขา",
  ui_story_5043_50431402_113_dialog_content = "คุณพูดอย่างนั้น แต่ Eclipsites ที่สวมหน้ากากนั้นไม่ง่ายที่จะจัดการกับ...",
  ui_story_5043_50431402_114_dialog_content = "ตรงนี้ให้ฉันจัดการเอง",
  ui_story_5043_50431402_115_dialog_content = "ด้วยเกียรติของฉัน และเกียรติยศของครอบครัวแคมป์เบลล์—",
  ui_story_5043_50431402_116_dialog_content = "ดูพลังของหัตถ์ศักดิ์สิทธิ์!",
  ui_story_5043_50431402_117_dialog_content = "โว้ว! Lumina นี่มันอะไรกัน!",
  ui_story_5043_50431402_118_dialog_content = "การโจมตีเช่นนี้อาจเพียงพอที่จะ—",
  ui_story_5043_50431402_119_dialog_content = "ย่าาาาาา—",
  ui_story_5043_50431402_120_dialog_content = "ฮะ? ฮ-เฮ้! ทำไมคุณถึงหาวในเวลาเช่นนี้!",
  ui_story_5043_50431402_121_dialog_content = "ขอโทษนะ... แต่ฉัน... เกินขีดจำกัดแล้ว... สำหรับวันนี้...",
  ui_story_5043_50431402_122_dialog_content = "หืม พาพวกเขาไป อัศวินทั้งสี่",
  ui_story_5043_50431402_123_dialog_content = "W-เดี๋ยวก่อน หมดเวลา! ไม่ยุติธรรมเลย!!",
  ui_story_5043_50431402_124_dialog_content = "รีบออกมาทีน่า! เฮ้! เฮ้!!!",
  ui_story_5043_50431402_125_dialog_content = "หนุงหนิง...ดูอานุภาพ...หัตถ์เทวะ...!",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>ตกต่ำ-</color>",
  ui_story_5043_50431402_127_dialog_content = "ช-เธอหลับไปตั้งแต่ยังไม่เริ่มการต่อสู้ด้วยซ้ำ!!!",
  ui_story_5043_50431402_128_dialog_content = "เราจะทำอย่างไรดี?! ที่นี่ไม่ใช่ที่งีบหลับ!!!",
  ui_story_5043_50431402_129_dialog_content = "ตื่นได้แล้ว ทีน่า! ศัตรูกำลังจะโจมตี!",
  ui_story_5043_50431402_130_dialog_content = "ดวงดาว... ฉันเห็นดวงดาว... บนหัวเธอ... เลย์...",
  ui_story_5043_50431402_131_dialog_content = "นี่ไม่ใช่เวลาดูดาว! เตรียมพร้อมสำหรับการต่อสู้!",
  ui_story_5043_50431402_132_dialog_content = "ขอโทษ... แต่ฉันทำไม่ได้...",
  ui_story_5043_50431402_133_dialog_content = "นี่กินแค่นี้เอง",
  ui_story_5043_50431402_134_dialog_content = "นั่นชอคโกแลตเหรอ! นี่ไม่ใช่เวลาของว่างเหมือนกัน เลย์!!!",
  ui_story_5043_50431402_135_dialog_content = "ฉัน... ฉัน...",
  ui_story_5043_50431402_136_dialog_content = "พวกเราทำอะไร? พวกมันอยู่ตรงหน้าเราแล้ว...",
  ui_story_5043_50431402_137_dialog_content = "ตอนนี้ฉันตื่นเต็มทีแล้ว!!!",
  ui_story_5043_50431402_138_dialog_content = "หา?!",
  ui_story_5043_50431402_139_dialog_content = "พูดถึงการงีบหลับ!!!",
  ui_story_5043_50431402_140_dialog_content = "เฮ้! เมื่อพูดถึงการเอาชนะใจใครสักคน คุณต้องพึ่งพากลยุทธ์มากกว่าหนึ่งกลยุทธ์!",
  ui_story_5043_50431402_141_dialog_content = "ให้ฉันแสดงวิธีทำ!",
  ui_story_5043_50431402_142_dialog_content = "เอ่อ? นั่นอะไร?",
  ui_story_5043_50431402_143_dialog_content = "คุณลืมแล้วหรือยัง? คุณและคนอื่น ๆ เป็นคนที่แสดงให้ฉันเห็นตั้งแต่แรก!",
  ui_story_5043_50431402_144_dialog_content = "มีหลายวิธีในการติดตามความสนใจด้านความรัก รวมถึง... <color=#FFB400>คำสารภาพ</color>!",
  ui_story_5043_50431402_145_dialog_content = "คุณพูดถูกมาตลอด ลีน! การได้รับความสนใจอย่างเต็มที่ของอีกฝ่ายเป็นขั้นตอนแรกและขั้นตอนที่สำคัญที่สุด!",
  ui_story_5043_50431402_X145_dialog_content = "ดึงสัตว์ประหลาดออกจากฝูงชน!",
  ui_story_5043_50431402_146_dialog_content = "ฉันขอโทษ อะไรนะ...?",
  ui_story_5043_50431402_147_dialog_content = "เอาล่ะ เจ้าสัตว์ประหลาดสวมหน้ากาก รับนี่ไป!",
  ui_story_5043_50431402_148_dialog_content = "กรร...",
  ui_story_5043_50431402_149_dialog_content = "ฉันเชื่อว่าหัตถ์ศักดิ์สิทธิ์สามารถดึงความสนใจจากคุณได้ ใช่หรือไม่?",
  ui_story_5043_50431402_X149_dialog_content = "กร๊าาาาซ!",
  ui_story_5043_50431402_X150_dialog_content = "พลังระดับนี้นายจะไม่แม้แต่จะทิ้งรอยไว้บนอัศวินของฉัน! อย่าหยุดโจมตี!",
  ui_story_5043_50431402_150_dialog_content = "ผู้พิพากษา Matthieu เป็นคนที่แสดงให้ฉันเห็นว่าต้องทำอย่างไรต่อไป ยังจำได้ใช่ไหม?",
  ui_story_5043_50431402_151_dialog_content = "ผู้คนไม่สามารถพึ่งพาการริเริ่มเพียงอย่างเดียว พวกเขายังต้องเรียนรู้... <color=#FFB400>ศิลปะแห่งการปกปิด</color>!",
  ui_story_5043_50431402_152_dialog_content = "และเป็นเช่นนั้น! ฉันจะครอบคลุมคุณทีน่า!",
  ui_story_5043_50431402_153_dialog_content = "เร็วเข้า ไปหลบหลังกำแพงนั้นกันเถอะ!",
  ui_story_5043_50431402_154_dialog_content = "หืม พร้อมที่จะยอมแพ้หลังจากความพ่ายแพ้เล็กน้อยหรือไม่? ความรักของคุณช่างเปราะบางเสียจริง",
  ui_story_5043_50431402_155_dialog_content = "เมื่อกี้คุณไม่ได้พูดว่าคุณต้องการปกป้องผู้คนเหรอ?",
  ui_story_5043_50431402_156_dialog_content = "กราาาาาา...",
  ui_story_5043_50431402_157_dialog_content = "กรา?",
  ui_story_5043_50431402_158_dialog_content = "ฉันรู้แล้ว! พวกเขาหาเราไม่เจอ!",
  ui_story_5043_50431402_159_dialog_content = "ฉันคิดว่าหน้ากากที่พวกเขาใส่อาจจะเป็นจุดอ่อนของพวกเขา!",
  ui_story_5043_50431402_160_dialog_content = "คุณอาจจะพูดถูก มาดูกันดีกว่าว่าภายใต้การปลอมตัวของพวกเขามีอะไรกันบ้าง!",
  ui_story_5043_50431402_161_dialog_content = "นี่คือที่มาของวิธีที่สาม!",
  ui_story_5043_50431402_162_dialog_content = "เพื่อหาจุดสมดุลระหว่างการเดินหน้าและถอยหลัง... <color=#FFB400>การลาดตระเวน</color>!",
  ui_story_5043_50431402_163_dialog_content = "เราต้องเข้าใจผู้อื่นให้มากที่สุดก่อนที่จะทำขั้นตอนสุดท้ายนั้น",
  ui_story_5043_50431402_X163_dialog_content = "เราแค่ต้องค้นหาจุดอ่อนของพวกมันให้เจอและจัดการกับการโจมตีที่เด็ดขาดเพื่อยุติเรื่องทั้งหมดนี้!",
  ui_story_5043_50431402_164_dialog_content = "เริ่มจากการโจมตีหน้ากากของพวกมันกันเถอะ!",
  ui_story_5043_50431402_165_dialog_content = "โอกาสของเรามาถึงแล้ว! จู่โจม!",
  ui_story_5043_50431402_166_dialog_content = "กร๊าาาาาา!!!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>แว่บ แว่บ แว่บ!!!</color>",
  ui_story_5043_50431402_168_dialog_content = "อั๊ยย่ะ อะไรพวกนั้นทำมาจากอะไรเนี่ย!",
  ui_story_5043_50431402_169_dialog_content = "ดูเหมือนว่าการทำลายหน้ากากเหล่านั้นจะไม่ง่ายอย่างที่คิด",
  ui_story_5043_50431402_170_dialog_content = "ฮ่าฮ่าฮ่า! โอ้ถ้าเพียงคุณเห็นใบหน้าโง่ ๆ ของคุณ!",
  ui_story_5043_50431402_171_dialog_content = "คุณเชื่ออย่างสัตย์จริงไหมว่าคุณสามารถทำร้ายอัศวินของฉันด้วยการโจมตีที่น่าสมเพชเช่นนี้?",
  ui_story_5043_50431402_172_dialog_content = "ฮึ่ม แม้ทุกอย่างจะดูสิ้นหวัง แต่ก็ยังมีโอกาสที่ความรักจะชนะ!",
  ui_story_5043_50431402_173_dialog_content = "ณ จุดนี้ กลเม็ดและกลยุทธ์หมดคำถาม ทั้งหมดที่เหลือที่ต้องทำ—",
  ui_story_5043_50431402_174_dialog_content = "เดี๋ยวทีน่า!",
  ui_story_5043_50431402_175_dialog_content = "โชว์ความในใจให้โลกรู้!!!",
  ui_story_5043_50431402_176_dialog_content = "ถูกตัอง! ฉันจะเอาความจริงใจของฉันไปทุกออนซ์!",
  ui_story_5043_50431402_177_dialog_content = "และใช้มันเพื่อโจมตีครั้งสุดท้าย!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>ความงดงามของพระเจ้า</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "ว้า เธอทำมันได้หรือไม่",
  ui_story_5043_50431402_180_dialog_content = "เธอทำ! เธอเป่าหน้ากากออกจาก Eclipsites ทันที!",
  ui_story_5043_50431402_181_dialog_content = "H-เป็นไปได้ยังไงเนี่ย?! อัศวินของฉัน...",
  ui_story_5043_50431402_182_dialog_content = "ก้าวไปข้างหน้า อัศวินของฉัน!",
  ui_story_5043_50431402_183_dialog_content = "คุณไม่สามารถทำให้ฉันผิดหวังตอนนี้! ไม่ใช่เมื่อความยุติธรรมยังไม่ได้รับ!",
  ui_story_5043_50431402_184_dialog_content = "มันจบลงแล้ว ชวาบ",
  ui_story_5043_50431402_185_dialog_content = "เช่นเดียวกับคุณ พวกเขาไม่รู้สึกถึงความรักหรือความภักดี สิ่งที่พวกเขาทำได้คือทำตามคำสั่งอย่างไร้สติ",
  ui_story_5043_50431402_186_dialog_content = "อย่างที่คุณเป็นอยู่ตอนนี้ คุณจะไม่มีทางหวังว่าจะเอาชนะพลังดิบของอารมณ์ของเราได้",
  ui_story_5043_50431402_187_dialog_content = "ถึงตอนนี้คุณยังยืนยันที่จะพูดเกี่ยวกับความรู้สึกของคุณ?!",
  ui_story_5043_50431402_188_dialog_content = "เธอพูดถูก รู้ไหม? สำหรับความยุติธรรมที่ไม่ได้รับการปรนนิบัติ... คุณไม่ต้องกังวลอีกต่อไป",
  ui_story_5043_50431402_189_dialog_content = "จากสิ่งที่เกิดขึ้น Hall of Justice จะดำเนินการกับคดีนี้อย่างจริงจังมากขึ้นอย่างแน่นอน",
  ui_story_5043_50431402_190_dialog_content = "อันที่จริง ฉันจะไม่แปลกใจเลยถ้าหัวหน้าผู้พิพากษา Irridon จะเป็นประธานทั้งหมด",
  ui_story_5043_50431402_191_dialog_content = "ฉันแน่ใจว่าเธอจะให้ความยุติธรรมแก่คุณอย่างที่คุณต้องการ ชวาบ",
  ui_story_5043_50431402_192_dialog_content = "บริการฉัน? ไม่ไม่! นี้ไม่ได้!",
  ui_story_5043_50431402_193_dialog_content = "ฉันบริสุทธิ์ ฉันบอกคุณ! ไม่มีใครตัดสินฉันได้!!!",
  ui_story_5043_50431402_194_dialog_content = "นั่นไม่ใช่สำหรับคุณที่จะตัดสินใจ",
  ui_story_5043_50431402_195_dialog_content = "แน่นอน เจ้าโง่! ฉันคือหัวหน้าผู้พิพากษา!!!",
  ui_story_5043_50431402_196_dialog_content = "สถานะนั้นไม่ได้มีไว้ให้คุณตัดสินใจอีกต่อไปเช่นกัน",
  ui_story_5043_50431402_197_dialog_content = "เน่าเสีย! เมืองนี้และกฎหมายของเมืองนี้เน่าเสียจนถึงแก่นแล้ว!",
  ui_story_5043_50431402_198_dialog_content = "ไปให้พ้น! พ่อจะได้ยินเรื่องนี้!",
  ui_story_5043_50431402_199_dialog_content = "จำคำพูดของฉัน ครอบครัว Salar จะไม่พักผ่อนจนกว่าความยุติธรรมที่แท้จริงจะเกิดขึ้น!",
  ui_story_5043_50431402_200_dialog_content = "คุณชวาบน่าละอายใจแค่ไหน วิ่งกลับบ้านไปหาพ่อเมื่อสิ่งต่าง ๆ ไม่เป็นไปตามที่คุณต้องการ?",
  ui_story_5043_50431402_201_dialog_content = "ช่างน่าขายหน้าเสียนี่กระไร",
  ui_story_5043_50431402_202_dialog_content = "ฉันพูดออกไปแล้ว!!!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5043_50431402_204_dialog_content = "อึก...!",
  ui_story_5043_50431402_205_dialog_content = "ว-ใครวะ? ใครตีฉันเมื่อกี้?!",
  ui_story_5043_50431402_206_dialog_content = "ฉันเอง และถ้าคุณไม่มากับเราอย่างสงบที่ Hall of Justice... มันจะมีที่มาที่ไปมากกว่านี้",
  ui_story_5043_50431402_207_dialog_content = "เลย์! ไอโง่!",
  ui_story_5043_50431402_208_dialog_content = "เจ้ารู้หรือไม่ว่าเจ้าเพิ่งทำอะไรลงไป เจ้าคนธรรมดาสามัญผู้น่าสมเพช?!",
  ui_story_5043_50431402_209_dialog_content = "มันเป็นไปเพื่อประโยชน์ของคุณเอง",
  ui_story_5043_50431402_210_dialog_content = "คุณอาจไม่ผ่านการพิจารณาคดีหากทีน่าตีคุณแทน",
  ui_story_5043_50431402_211_dialog_content = "มันเป็นเรื่องจริงนะ!",
  ui_story_5043_50431402_212_dialog_content = "ย-ทุกท่าน...",
  ui_story_5043_50431402_213_dialog_content = "ที่จะทำทุกคน พนักงานของแผนก Romance ยังคงทำงานตลอดเวลา!",
  ui_story_5043_50431402_214_dialog_content = "มา มา! ได้เวลากลับมาทำหน้าที่ของเราแล้ว!",
  ui_story_5043_50431402_215_dialog_content = "ฉันเดาว่าเรายังมีงานอีกมากสำหรับวันนี้ ฮะ?",
  ui_story_5043_50431402_216_dialog_content = "ย่าาาา... โอ้ ขอบคุณพระเจ้า โซฟา...",
  ui_story_5043_50431402_217_dialog_content = "เฮ้! เอามือสกปรกของคุณออกจากฉัน!",
  ui_story_5043_50431402_218_dialog_content = "ฉันจะไม่ถูกผลักเหมือนอาชญากรทั่วไป!",
  ui_story_5043_50431402_219_dialog_content = "โว้ว! ในที่สุดพวกเขาก็จับ Schwab เข้าคุก!",
  ui_story_5043_50431402_220_dialog_content = "ดูเหมือนว่าทุกอย่างจะจบลงด้วยดีใช่ไหม?",
  ui_story_5043_50431402_221_dialog_content = "อย่างแท้จริง. Schwab มีคำตอบมากมาย การลงโทษของเขาจะไม่เบา",
  ui_story_5043_50431402_222_dialog_content = "แม้ว่าการกระทำของเขาจะไม่ก่อให้เกิดความเสียหายใดๆ ก็ตาม การกระทำเหล่านี้ยังคงเป็นการละเมิดกฎหมายของ Lumopolis โดยตรง",
  ui_story_5043_50431402_223_dialog_content = "เขาควรจะเลือกจัดการกับ Eclipsites แบบนี้อีกไหม... ฉันไม่กล้าจินตนาการถึงผลที่ตามมา",
