  ui_story_5043_50431501_64_dialog_content = "พาเขาไปที่สำนักแม่ชีและเตรียมเขาให้พร้อมสำหรับชีวิตใหม่แห่งการศึกษาและการไตร่ตรอง",
  ui_story_5043_50431501_65_dialog_content = "นอกเหนือจาก Schwab แล้ว ยังมีฝ่ายอื่นๆ ในกรณีนี้ที่ต้องการการตำหนิ",
  ui_story_5043_50431501_66_dialog_content = "ผู้พิพากษาลีน",
  ui_story_5043_50431501_67_dialog_content = "ใช่ ผู้มีเกียรติของคุณ!",
  ui_story_5043_50431501_68_dialog_content = "คุณถูกกล่าวหาว่าบุกเข้าไปในคฤหาสน์ Salar คุณยอมรับในอาชญากรรมนี้หรือไม่?",
  ui_story_5043_50431501_69_dialog_content = "ชอบครับ",
  ui_story_5043_50431501_70_dialog_content = "(ฉันคิดว่าเขาคงไม่โกหกหัวหน้าผู้พิพากษา...)",
  ui_story_5043_50431501_71_dialog_content = "ดีมาก. โดยอำนาจของสภายุติธรรม และตามมาตรา 127 ของจรรยาบรรณผู้พิพากษา...",
  ui_story_5043_50431501_72_dialog_content = "คะแนนประสิทธิภาพรายเดือนของคุณจะถูกรีเซ็ตเป็นศูนย์ และค่าจ้างของคุณสำหรับเดือนนี้จะลดลงเป็นระดับค่าจ้างขั้นต่ำที่อนุญาตในฐานะข้าราชการของ Lumopolis",
  ui_story_5043_50431501_73_dialog_content = "ฉันเข้าใจ...",
  ui_story_5043_50431501_74_dialog_content = "(เขาพูดแบบนั้น แต่ฉันคิดว่านั่นเป็นการลงโทษที่เจ็บปวดที่สุดที่เขาจะได้รับ!)",
  ui_story_5043_50431501_75_dialog_content = "เอาล่ะ จริง ๆ แล้ว... ฉันก็มีความผิดในอาชญากรรมนี้เหมือนกัน ท่านผู้มีเกียรติ!",
  ui_story_5043_50431501_76_dialog_content = "ตอนนั้นฉันอยู่กับเขา ดังนั้นฉันเชื่อว่าการลงโทษนี้ควรแบ่งระหว่างเราสองคน",
  ui_story_5043_50431501_77_dialog_content = "อย่างนั้นหรือ ผู้พิพากษามัตติเยอ",
  ui_story_5043_50431501_78_dialog_content = "ฉันอยู่ที่นั่นด้วย! อย่าลืมฉัน!",
  ui_story_5043_50431501_79_dialog_content = "ฉันต้องบอกว่าความเต็มใจที่จะยอมรับความผิดพลาดของคุณนั้นค่อนข้างสดชื่น ดีมาก! นอกเหนือจากค่าจ้างของผู้พิพากษา Matthieu ที่ค้างอยู่ในเดือนนี้...",
  ui_story_5043_50431501_80_dialog_content = "ฉันสั่งให้พวกคุณสามคนไปกวาดบริเวณด้านนอก Hall of Justice ในภายหลัง",
  ui_story_5043_50431501_81_dialog_content = "สายตาของดอกไม้ที่ตายแล้วนั้นไม่เป็นที่พอใจนัก",
  ui_story_5043_50431501_82_dialog_content = "ท-นี่คือการลงโทษแบบไหน??",
  ui_story_5043_50431501_83_dialog_content = "คุณต้องการให้ฉันพิจารณาใหม่หรือไม่?",
  ui_story_5043_50431501_84_dialog_content = "N-ไม่ ขอบคุณ ผู้มีเกียรติของคุณ! เราเต็มใจที่จะยอมรับมากกว่า!",
  ui_story_5043_50431501_85_dialog_content = "ดี. นั่นเป็นเพียงคำตัดสินสุดท้ายที่จะผ่านไป",
  ui_story_5043_50431501_86_dialog_content = "พยาน, โตโต้, กรุณาเข้าใกล้อัฒจันทร์?",
  ui_story_5043_50431501_87_dialog_content = "ฉันอยู่ที่นี่ ผู้มีเกียรติของคุณ!",
  ui_story_5043_50431501_88_dialog_content = "โตโต้!",
  ui_story_5043_50431501_89_dialog_content = "(โอ้โห! โตโต้ไปใส่ชุดนั้นตั้งแต่เมื่อไหร่เนี่ย?)",
  ui_story_5043_50431501_90_dialog_content = "(มันดูประณีตมาก เขากลมกลืนกับส่วนที่เหลือของ Lumopolis ได้อย่างสมบูรณ์แบบ!)",
  ui_story_5043_50431501_91_dialog_content = "ในฐานะเหยื่อในกรณีนี้ คุณยังคงเต็มใจที่จะช่วยเหลือชาว Aurorian ในการแสวงหาความยุติธรรม สำหรับสิ่งนั้นฉันต้องขอชมเชยคุณ",
  ui_story_5043_50431501_92_dialog_content = "อย่างไรก็ตาม ความผิดฐานให้การเท็จไม่ได้ถูกยอมความใน Hall of Justice ที่นี่",
  ui_story_5043_50431501_93_dialog_content = "ในฐานะผู้สมรู้ร่วมคิดในกลยุทธ์ของ Judge Leyn คุณก็มีความผิดเท่าเทียมกันในความผิดนี้",
  ui_story_5043_50431501_94_dialog_content = "ฉัน... ฉันเข้าใจ...",
  ui_story_5043_50431501_95_dialog_content = "ในฐานะหัวหน้าผู้พิพากษา การลงโทษของคุณคือ—",
  ui_story_5043_50431501_96_dialog_content = "...ขอโทษชวาบ.",
  ui_story_5043_50431501_97_dialog_content = "เอ่อ... อะไรนะ?",
  ui_story_5043_50431501_98_dialog_content = "Y-คุณต้องการให้เราขอโทษ? นั่นคือทั้งหมด?",
  ui_story_5043_50431501_99_dialog_content = "การให้การเท็จของคุณยังเป็นการดูหมิ่นเกียรติของเขาในฐานะผู้พิพากษาของ Hall of Justice ดังนั้นอย่าลืมแสดงความจริงใจเพียงเล็กน้อยเมื่อคุณขอโทษ",
  ui_story_5043_50431501_100_dialog_content = "ด้วยเหตุนี้ การลงโทษทั้งหมดที่เกี่ยวข้องกับคดีนี้จึงถูกระงับ",
  ui_story_5043_50431501_101_dialog_content = "คดีของ Serial Statue Decapitations ปิดลงแล้ว! ศาลเลื่อน!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>ไม่กี่วันหลังจากนั้น...</color>",
  ui_story_5043_50431501_104_dialog_content = "อะแฮ่ม นี่คือรายละเอียดการเดินทางของฉันในหลงโจวเมื่อสองสามเดือนก่อน",
  ui_story_5043_50431501_105_dialog_content = "ดีมาก. ขอบคุณ, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "ในขณะที่ความสมดุลของพลังเปลี่ยนไปในโลกรอบตัวเรา จุดยืนของ Lumopolis จะไม่มีวันเปลี่ยนแปลง",
  ui_story_5043_50431501_107_dialog_content = "ฉันภาวนาให้ Eraveil รักษาความสัมพันธ์ฉันมิตรกับเมืองที่ยุติธรรมของเราต่อไป",
  ui_story_5043_50431501_108_dialog_content = "ฉันภาวนาให้คุณรู้สึกแบบเดียวกัน เพื่อนหนุ่มของฉัน",
  ui_story_5043_50431501_109_dialog_content = "O-แน่นอน ท่านชวาร์ตษ์! ฉันยินดีเสมอที่จะช่วยเหลือในเรื่องการสร้างสันติภาพกับผู้อื่น!",
