  ui_story_5043_50431501_112_dialog_content = "คุณรู้ไหม คุณสามารถเป็นนักการทูตได้เมื่อคุณใส่ใจ PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "หึหึหึหึหึหึหึหึหึหึหึหึหึ พูดตามตรงฉันยังรู้สึกประหม่าอยู่เล็กน้อย",
  ui_story_5043_50431501_114_dialog_content = "จบการประชุมของเราในวันนี้ มีคำถามเพิ่มเติมหรือไม่?",
