  ui_story_5043_50431501_116_dialog_content = "ดยุคออตโต?",
  ui_story_5043_50431501_117_dialog_content = "อืม ขาของฉันเริ่มล้าจากการนั่งทั้งหมดนี้",
  ui_story_5043_50431501_118_dialog_content = "ดีมากแล้ว ขอบคุณทุกท่านอีกครั้ง คุณมีอิสระที่จะออกไปเดี๋ยวนี้",
  ui_story_5043_50431501_119_dialog_content = "(ยังไม่ มีสิ่งสุดท้ายที่ฉันต้องนำเสนอในขณะที่ตัวแทน Hall of Justice และ Elder Council ยังอยู่ที่นี่)",
  ui_story_5043_50431501_120_dialog_content = "(นอกเหนือจาก Eclipsites และฝูงชนที่ควบคุมไม่ได้แล้ว พรรคอื่นใน Lumopolis ได้หว่านความบาดหมางกันเมื่อเร็ว ๆ นี้)",
  ui_story_5043_50431501_121_dialog_content = "(ในฐานะหัวหน้าผู้พิทักษ์สวนลุมโปลิส ฉันมีหน้าที่ต้องบอกสภาผู้อาวุโส!)",
