  ui_story_5043_50431501_123_dialog_content = "ฉันต้องบอกว่าท่านลอร์ดชวาร์ตษ์ สวนลูโมโพลิสได้จัดการกับเหตุฉุกเฉินล่าสุดทั้งหมดอย่างมีประสิทธิภาพ",
  ui_story_5043_50431501_124_dialog_content = "ฉันรู้สึกประหลาดใจมากที่เห็นว่าพวกเขาทำงานร่วมกับชาวลูโมโพลิสได้ดีเพียงใด",
  ui_story_5043_50431501_125_dialog_content = "ฮ่าฮ่า คำชมของคุณช่างสง่างามเหลือเกิน Duke Otto โดยปกติแล้ว ความสำเร็จของเราส่วนใหญ่มาจากการสนับสนุนของสภาผู้สูงอายุ",
  ui_story_5043_50431501_126_dialog_content = "หากไม่มีความช่วยเหลือของคุณในการต่อสู้กับ Eclipsites ผู้พิทักษ์สวน Lumopolis จะไม่สามารถตอบสนองต่อความต้องการของเมืองของเราได้",
  ui_story_5043_50431501_127_dialog_content = "คาร์ลีน นี่มันอะไรน่ะ?",
  ui_story_5043_50431501_128_dialog_content = "...",
  ui_story_5043_50431501_129_dialog_content = "อา ไม่พูดอะไรอีกแล้ว ไมเลดี้ ฉันไม่อยากก้าวก่ายบทสนทนาระหว่างพ่อกับลูกสาว ขอให้เป็นวันที่ดี.",
