  ui_story_5043_50431501_132_dialog_content = "ในปีที่ผ่านมา คุณแสดงให้เห็นว่าตัวเองใจเย็นขึ้นและกล้าหาญมากขึ้นกว่าที่เคยเป็นมา",
  ui_story_5043_50431501_133_dialog_content = "อย่างไรก็ตาม การจัดการเรื่องการเมืองเช่นนี้ต้องอาศัยความกล้าหาญมากกว่า",
  ui_story_5043_50431501_134_dialog_content = "เมื่องานปัจจุบันของฉันเสร็จสิ้น ฉันจะจัดเวลาวันหยุดให้กับทุกคนในสวนลุมโปลิส",
