  ui_story_5043_50431501_139_dialog_content = "เรารู้ทันทีที่เห็นหัวหน้าผู้พิพากษา Irridon เดินออกจากห้องประชุม!",
  ui_story_5043_50431501_140_dialog_content = "ประทัดเหล่านี้เป็นของเหลือจากตอนที่มอบให้ Byron เพื่อเป็นรูปปั้นของเขา",
  ui_story_5043_50431501_141_dialog_content = "ปล่อยให้สูญเปล่าไม่ได้แล้วใช่ไหม?",
  ui_story_5043_50431501_142_dialog_content = "เกิดอะไรขึ้น? ประหลาดใจเกินไปที่จะพูด?",
  ui_story_5043_50431501_143_dialog_content = "เชียร์ขึ้นใช่ไหม นั่นก็เพื่อคุณเช่นกัน เลดี้คาร์ลีน!",
