  ui_story_5043_50431501_153_dialog_content = "ดังนั้นแม้ฝ่ายโรมานซ์จะเลิกกิจการไปแล้ว ก็ยังมีหลายคดีที่ยังไม่ได้รับการคลี่คลาย",
  ui_story_5043_50431501_154_dialog_content = "ศาลยุติธรรมยังคงขยันขันแข็งเช่นเคย หัวหน้าผู้พิพากษา",
  ui_story_5043_50431501_155_dialog_content = "ว้าว แค่ดูที่ไฟล์เหล่านี้ทั้งหมด! เราจะอยู่ที่นี่เป็นเวลาหลายสัปดาห์เพื่อพยายามอ่านทั้งหมด...",
