  ui_story_5043_50431501_159_dialog_content = "การสำรวจที่ลึกลงไปในเนื้อหาของพวกเขาเผยให้เห็นปัญหามากมายที่ส่งผลกระทบต่อ Lumopolis ในระดับพื้นฐานและสังคมอย่างรวดเร็ว",
